import React, { useState } from 'react';
import { Product, Customer, CartItem, Sale } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS } from '../constants';

interface POSModuleProps {
  onBack: () => void;
}

export const POSModule: React.FC<POSModuleProps> = ({ onBack }) => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) {
        return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  const filteredCustomers = INITIAL_CUSTOMERS.filter(c => 
    c.name.toLowerCase().includes(search.toLowerCase()) || 
    c.alias.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="h-full flex flex-col animate-fadeIn overflow-hidden">
      <div className="px-6 pt-8 pb-4 flex items-center gap-4">
        <button onClick={onBack} className="w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-sm text-sky-600">
          <i className="fas fa-arrow-left"></i>
        </button>
        <h2 className="text-2xl font-black text-sky-900">Venta Rápida</h2>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-24">
        {/* Customer Search */}
        <section>
          <label className="text-xs font-bold uppercase tracking-widest text-sky-400 mb-2 block">Cliente</label>
          <div className="relative">
            <input 
              type="text" 
              placeholder="Buscar por nombre o alias..." 
              className="w-full bg-white border-none rounded-2xl py-4 px-6 shadow-sm focus:ring-2 ring-sky-300 outline-none"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
            {search && !customer && (
              <div className="absolute top-full left-0 right-0 bg-white shadow-xl rounded-2xl mt-2 z-20 max-h-40 overflow-y-auto">
                {filteredCustomers.map(c => (
                  <button 
                    key={c.id}
                    onClick={() => { setCustomer(c); setSearch(c.alias); }}
                    className="w-full text-left p-4 hover:bg-sky-50 border-b last:border-none"
                  >
                    <div className="font-bold">{c.alias}</div>
                    <div className="text-xs text-sky-400">{c.name}</div>
                  </button>
                ))}
              </div>
            )}
          </div>
          {customer && (
            <div className="mt-2 bg-sky-500 text-white p-3 rounded-2xl flex justify-between items-center animate-fadeIn">
              <span>Cliente: <strong>{customer.alias}</strong></span>
              <button onClick={() => setCustomer(null)}><i className="fas fa-times"></i></button>
            </div>
          )}
        </section>

        {/* Products */}
        <section>
          <label className="text-xs font-bold uppercase tracking-widest text-sky-400 mb-3 block">Productos</label>
          <div className="grid grid-cols-2 gap-3">
            {INITIAL_PRODUCTS.map(p => (
              <button 
                key={p.id}
                onClick={() => addToCart(p)}
                className="bg-white p-4 rounded-[2rem] shadow-sm border border-transparent hover:border-sky-300 transition-all text-left"
              >
                <div className="text-sm font-bold text-sky-800 line-clamp-1">{p.name}</div>
                <div className="text-sky-500 font-black mt-1">${p.price}</div>
                <div className="text-[10px] text-sky-300 mt-1 uppercase">Stock: {p.stock}</div>
              </button>
            ))}
          </div>
        </section>

        {/* Cart */}
        {cart.length > 0 && (
          <section className="bg-white rounded-[2.5rem] p-6 shadow-md">
            <h3 className="font-bold text-lg mb-4 text-sky-900">Carrito</h3>
            <div className="space-y-4">
              {cart.map(item => (
                <div key={item.id} className="flex justify-between items-center text-sm">
                  <div className="flex items-center gap-3">
                    <span className="bg-sky-100 text-sky-600 px-2 py-1 rounded-lg font-bold">{item.quantity}</span>
                    <span className="text-sky-800">{item.name}</span>
                  </div>
                  <span className="font-bold">${item.price * item.quantity}</span>
                </div>
              ))}
              <div className="border-t pt-4 flex justify-between items-center font-black text-xl text-sky-900">
                <span>TOTAL</span>
                <span>${total}</span>
              </div>
            </div>
          </section>
        )}
      </div>

      <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/80 backdrop-blur-xl border-t border-sky-100">
        <button 
          disabled={cart.length === 0}
          className="w-full bg-sky-600 text-white py-5 rounded-full font-bold text-lg shadow-xl shadow-sky-200 active:scale-95 transition-all disabled:opacity-50"
          onClick={() => alert(`Venta completada por $${total}. Ticket generado.`)}
        >
          Confirmar Venta y Ticket
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';

export const ProductionModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [seconds, setSeconds] = useState(0);
  const [isRunning, setIsRunning] = useState(false);
  const [activeProcess, setActiveProcess] = useState<'none' | 'backwash' | 'regeneration'>('none');

  useEffect(() => {
    let interval: any;
    if (isRunning) {
      interval = setInterval(() => {
        setSeconds(s => s + 1);
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isRunning]);

  const formatTime = (total: number) => {
    const m = Math.floor(total / 60);
    const s = total % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const startProcess = (type: 'backwash' | 'regeneration') => {
    setActiveProcess(type);
    setSeconds(0);
    setIsRunning(true);
  };

  return (
    <div className="px-6 py-8 animate-fadeIn h-full overflow-y-auto pb-24">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={onBack} className="w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-sm text-sky-600">
          <i className="fas fa-arrow-left"></i>
        </button>
        <h2 className="text-2xl font-black text-sky-900">Producción</h2>
      </div>

      <div className="space-y-6">
        <section className="bg-white rounded-[2.5rem] p-8 shadow-md flex flex-col items-center">
          <h3 className="text-sky-400 font-bold uppercase text-xs tracking-widest mb-4">Cronómetro de Filtros</h3>
          <div className="text-6xl font-black text-sky-900 mb-4 font-mono">
            {formatTime(seconds)}
          </div>
          <div className="flex gap-4">
            {!isRunning ? (
              <>
                <button 
                  onClick={() => startProcess('backwash')}
                  className="bg-sky-500 text-white px-6 py-3 rounded-full font-bold shadow-lg shadow-sky-100"
                >
                  Retrolavado
                </button>
                <button 
                  onClick={() => startProcess('regeneration')}
                  className="bg-indigo-500 text-white px-6 py-3 rounded-full font-bold shadow-lg shadow-indigo-100"
                >
                  Regeneración
                </button>
              </>
            ) : (
              <button 
                onClick={() => setIsRunning(false)}
                className="bg-red-500 text-white px-10 py-3 rounded-full font-bold"
              >
                Detener {activeProcess === 'backwash' ? 'Lavado' : 'Regen'}
              </button>
            )}
          </div>
        </section>

        <section className="bg-white rounded-[2.5rem] p-8 shadow-md">
          <h3 className="text-sky-900 font-bold text-lg mb-6">Registro Calidad (Muestra)</h3>
          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <span className="text-sky-600 font-medium">TDS (Sólidos)</span>
              <div className="flex items-center gap-2">
                <input type="number" defaultValue="008" className="w-16 bg-sky-50 border-none rounded-xl p-2 text-center font-bold" />
                <span className="text-xs font-bold text-sky-400">PPM</span>
              </div>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-sky-600 font-medium">pH (Acidez)</span>
              <div className="flex items-center gap-2">
                <input type="number" defaultValue="7.2" className="w-16 bg-sky-50 border-none rounded-xl p-2 text-center font-bold" />
                <span className="text-xs font-bold text-sky-400">PH</span>
              </div>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-sky-600 font-medium">Dureza</span>
              <div className="flex items-center gap-2">
                <input type="number" defaultValue="0" className="w-16 bg-sky-50 border-none rounded-xl p-2 text-center font-bold" />
                <span className="text-xs font-bold text-sky-400">GH</span>
              </div>
            </div>
          </div>
          <button className="w-full mt-8 bg-sky-900 text-white py-4 rounded-full font-bold shadow-xl active:scale-95 transition-all">
            Guardar Reporte
          </button>
        </section>

        <div className="bg-amber-50 border border-amber-100 rounded-[2rem] p-6 flex gap-4">
          <div className="bg-amber-100 w-12 h-12 rounded-full flex items-center justify-center text-amber-600 shrink-0">
            <i className="fas fa-triangle-exclamation"></i>
          </div>
          <div>
            <h4 className="font-bold text-amber-800">Recordatorio</h4>
            <p className="text-amber-700 text-sm">Cambio de Lecho de Carbón Activado en 3 días.</p>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { ViewType } from './types';
import { Dashboard } from './components/Dashboard';
import { POSModule } from './components/POSModule';
import { ProductionModule } from './components/ProductionModule';
import { VoiceAI } from './components/VoiceAI';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  // Android Back Button Logic using History API
  const handleBack = useCallback(() => {
    if (currentView !== 'dashboard') {
      setCurrentView('dashboard');
      window.history.pushState({ view: 'dashboard' }, '');
    }
  }, [currentView]);

  useEffect(() => {
    // Initial state
    window.history.replaceState({ view: 'dashboard' }, '');

    const onPopState = (event: PopStateEvent) => {
      if (event.state?.view) {
        setCurrentView(event.state.view);
      } else {
        setCurrentView('dashboard');
      }
    };

    window.addEventListener('popstate', onPopState);
    return () => window.removeEventListener('popstate', onPopState);
  }, []);

  const setViewWithHistory = (view: ViewType) => {
    setCurrentView(view);
    window.history.pushState({ view }, '');
  };

  const onVoiceAction = (result: any) => {
    if (result.action === 'SALE') {
      setViewWithHistory('pos');
    }
    // Implement other voice-triggered shortcuts here
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard setView={setViewWithHistory} />;
      case 'pos':
        return <POSModule onBack={handleBack} />;
      case 'production':
      case 'quality':
        return <ProductionModule onBack={handleBack} />;
      case 'logistics':
        return (
          <div className="p-8 text-center animate-fadeIn">
            <button onClick={handleBack} className="mb-4 text-sky-500"><i className="fas fa-arrow-left"></i> Volver</button>
            <h2 className="text-2xl font-bold">Logística y Rutas</h2>
            <div className="mt-8 bg-white p-10 rounded-[2.5rem] shadow-lg border border-sky-100">
              <i className="fas fa-map-location-dot text-6xl text-sky-200 mb-4"></i>
              <p className="text-sky-600">Integrando Google Maps API para seguimiento en tiempo real...</p>
            </div>
          </div>
        );
      case 'sync':
        return (
          <div className="p-8 text-center animate-fadeIn">
            <button onClick={handleBack} className="mb-4 text-sky-500"><i className="fas fa-arrow-left"></i> Volver</button>
            <h2 className="text-2xl font-bold">Sincronización P2P</h2>
            <div className="mt-8 bg-sky-900 text-white p-10 rounded-[2.5rem] shadow-2xl">
              <div className="w-20 h-20 border-4 border-sky-400 border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
              <p className="font-bold">Buscando terminales en la red local...</p>
              <p className="text-sky-300 text-sm mt-2">(PeerJS Engine Active)</p>
            </div>
          </div>
        );
      case 'whatsapp':
        return (
          <div className="p-8 text-center animate-fadeIn">
            <button onClick={handleBack} className="mb-4 text-sky-500"><i className="fas fa-arrow-left"></i> Volver</button>
            <h2 className="text-2xl font-bold">WhatsApp Marketing</h2>
            <div className="mt-8 space-y-4">
              <div className="bg-white p-6 rounded-[2rem] shadow-sm text-left">
                <h4 className="font-bold text-green-600"><i className="fab fa-whatsapp"></i> Recordatorio de Pago</h4>
                <p className="text-sm text-gray-500 mt-1">"Hola [Cliente], te recordamos que tu saldo está por vencer..."</p>
                <button className="mt-4 w-full bg-green-500 text-white py-2 rounded-full text-xs font-bold">Enviar a 15 clientes</button>
              </div>
            </div>
          </div>
        );
      default:
        return <Dashboard setView={setViewWithHistory} />;
    }
  };

  return (
    <div className="max-w-md mx-auto min-h-screen bg-sky-50 relative">
      <main className="pb-24">
        {renderContent()}
      </main>

      {currentView === 'dashboard' && <VoiceAI onAction={onVoiceAction} />}

      {/* Visual Feedback for Android Feel */}
      <div className="fixed top-0 left-0 right-0 h-1 bg-sky-400/20 z-50">
        <div className="h-full bg-sky-500 transition-all duration-300" style={{ width: currentView === 'dashboard' ? '0%' : '100%' }}></div>
      </div>
    </div>
  );
};

