import { useState, useEffect, useCallback } from 'react';
import { ViewType } from '../types';

export const useNavigation = (initialView: ViewType = 'dashboard') => {
  const [currentView, setCurrentView] = useState<ViewType>(initialView);

  const navigateTo = useCallback((view: ViewType) => {
    setCurrentView(view);
    window.history.pushState({ view }, '');
  }, []);

  const goBack = useCallback(() => {
    if (currentView !== 'dashboard') {
      navigateTo('dashboard');
    }
  }, [currentView, navigateTo]);

  useEffect(() => {
    window.history.replaceState({ view: 'dashboard' }, '');
    const handlePopState = (event: PopStateEvent) => {
      const view = event.state?.view || 'dashboard';
      setCurrentView(view as ViewType);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  return { currentView, navigateTo, goBack };
};

import { useState, useEffect } from 'react';
import { Product, Customer, Sale, CartItem } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS } from '../constants';

export const useERPData = () => {
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers] = useState<Customer[]>(INITIAL_CUSTOMERS);

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
  }, [products, sales]);

  const addSale = (customerId: string, items: CartItem[], total: number) => {
    const newSale: Sale = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      customerId,
      items,
      total,
      synced: false
    };

    setSales(prev => [newSale, ...prev]);

    // Update stock
    setProducts(prev => prev.map(p => {
      const cartItem = items.find(item => item.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    return newSale;
  };

  return { products, customers, sales, addSale };
};

