interface POSModuleProps {
  onBack: () => void;
}

export const POSModule: React.FC<POSModuleProps> = ({ onBack }) => {
  const { products, customers, addSale } = useERPData();
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) {
        return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  const handleCheckout = () => {
    if (!customer) {
      alert("Por favor selecciona un cliente primero.");
      return;
    }
    addSale(customer.id, cart, total);
    alert(`Venta guardada. Ticket Aqua-${Math.floor(Math.random()*1000)} generado.`);
    onBack();
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn overflow-hidden pb-24">
      <ModuleHeader title="Venta Rápida" onBack={onBack} />

      <div className="flex-1 overflow-y-auto px-6 space-y-6">
        <section>
          <label className="text-[10px] font-bold uppercase tracking-[0.2em] text-sky-400 mb-2 block">Selección de Cliente</label>
          <div className="relative">
            <input 
              type="text" 
              placeholder="Nombre o alias..." 
              className="w-full bg-white border-none rounded-2xl py-4 px-6 shadow-sm focus:ring-2 ring-sky-300 outline-none transition-all"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
            {search && !customer && (
              <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-2xl mt-2 z-50 max-h-40 overflow-y-auto border border-sky-50">
                {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                  <button 
                    key={c.id}
                    onClick={() => { setCustomer(c); setSearch(c.alias); }}
                    className="w-full text-left p-4 hover:bg-sky-50 border-b border-sky-50 last:border-none font-medium text-sky-800"
                  >
                    {c.alias} <span className="text-xs text-sky-300 font-normal">({c.name})</span>
                  </button>
                ))}
              </div>
            )}
          </div>
          {customer && (
            <div className="mt-3 bg-sky-500 text-white p-4 rounded-2xl flex justify-between items-center animate-fadeIn shadow-lg shadow-sky-100">
              <span className="font-bold">{customer.alias}</span>
              <button onClick={() => { setCustomer(null); setSearch(''); }}><i className="fas fa-times-circle"></i></button>
            </div>
          )}
        </section>

        <section>
          <label className="text-[10px] font-bold uppercase tracking-[0.2em] text-sky-400 mb-3 block">Catálogo</label>
          <div className="grid grid-cols-2 gap-3">
            {products.map(p => (
              <button 
                key={p.id}
                onClick={() => addToCart(p)}
                className="bg-white p-5 rounded-[2rem] shadow-sm border border-transparent hover:border-sky-200 active:bg-sky-50 transition-all text-left group"
              >
                <div className="text-sm font-black text-sky-900 line-clamp-1 mb-1">{p.name}</div>
                <div className="text-sky-600 font-bold">${p.price}</div>
                <div className="text-[10px] text-sky-300 mt-2 font-bold">Stock: {p.stock}</div>
              </button>
            ))}
          </div>
        </section>

        {cart.length > 0 && (
          <RoundedCard className="mb-8 border-sky-100">
            <h3 className="font-black text-sky-900 mb-4 flex items-center gap-2">
              <i className="fas fa-shopping-basket text-sky-400"></i> Mi Carrito
            </h3>
            <div className="space-y-3">
              {cart.map(item => (
                <div key={item.id} className="flex justify-between items-center animate-fadeIn">
                  <div className="flex items-center gap-2">
                    <span className="bg-sky-100 text-sky-600 w-6 h-6 flex items-center justify-center rounded-lg text-[10px] font-black">{item.quantity}</span>
                    <span className="text-xs font-medium text-sky-800">{item.name}</span>
                  </div>
                  <span className="text-xs font-black text-sky-900">${item.price * item.quantity}</span>
                </div>
              ))}
              <div className="border-t border-sky-50 pt-3 mt-3 flex justify-between items-center">
                <span className="font-bold text-sky-400 text-xs">TOTAL A PAGAR</span>
                <span className="font-black text-2xl text-sky-900">${total}</span>
              </div>
            </div>
          </RoundedCard>
        )}
      </div>

      <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/90 backdrop-blur-xl border-t border-sky-50 z-40">
        <ActionButton 
          disabled={cart.length === 0 || !customer}
          onClick={handleCheckout}
        >
          Finalizar Pedido
        </ActionButton>
      </div>
    </div>
  );
};

