export type ViewType = 'dashboard' | 'pos' | 'logistics' | 'production' | 'quality' | 'sync' | 'whatsapp';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
}

export interface Customer {
  id: string;
  name: string;
  alias: string;
  specialPrice?: number;
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Crédito';

export interface Sale {
  id: string;
  timestamp: number;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  paymentMethod: PaymentMethod;
  synced: boolean;
}

export interface ProductionEvent {
  id: string;
  timestamp: number;
  type: 'backwash' | 'regeneration';
  duration: number; // in seconds
  operator?: string;
}

export interface QualityLog {
  id: string;
  timestamp: number;
  tds: number;
  ph: number;
  hardness: number;
  notes: string;
  status: 'optimal' | 'warning' | 'critical';
}

export interface Route {
  id: string;
  driverName: string;
  vehiclePlate: string;
  status: 'pending' | 'in-progress' | 'completed';
  orders: number;
  inventory: { productId: string; quantity: number }[];
}

import { useState, useEffect } from 'react';
import { Product, Customer, Sale, CartItem, PaymentMethod, ProductionEvent, QualityLog } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS } from '../constants';

export const useERPData = () => {
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers] = useState<Customer[]>(INITIAL_CUSTOMERS);

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [productionLogs, setProductionLogs] = useState<ProductionEvent[]>(() => {
    const saved = localStorage.getItem('aqua_prod_logs');
    return saved ? JSON.parse(saved) : [];
  });

  const [qualityLogs, setQualityLogs] = useState<QualityLog[]>(() => {
    const saved = localStorage.getItem('aqua_quality_logs');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_prod_logs', JSON.stringify(productionLogs));
    localStorage.setItem('aqua_quality_logs', JSON.stringify(qualityLogs));
  }, [products, sales, productionLogs, qualityLogs]);

  const addSale = (customerId: string, customerAlias: string, items: CartItem[], total: number, paymentMethod: PaymentMethod) => {
    const newSale: Sale = {
      id: `TKT-${Math.floor(1000 + Math.random() * 9000)}`,
      timestamp: Date.now(),
      customerId,
      customerAlias,
      items,
      total,
      paymentMethod,
      synced: false
    };

    setSales(prev => [newSale, ...prev]);

    setProducts(prev => prev.map(p => {
      const cartItem = items.find(item => item.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    return newSale;
  };

  const addProductionLog = (event: Omit<ProductionEvent, 'id' | 'timestamp'>) => {
    const newLog: ProductionEvent = {
      ...event,
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
    };
    setProductionLogs(prev => [newLog, ...prev]);
  };

  const addQualityLog = (log: Omit<QualityLog, 'id' | 'timestamp' | 'status'>) => {
    let status: QualityLog['status'] = 'optimal';
    if (log.tds > 20 || log.ph < 6.5 || log.ph > 8.5) status = 'warning';
    if (log.tds > 50) status = 'critical';

    const newLog: QualityLog = {
      ...log,
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      status
    };
    setQualityLogs(prev => [newLog, ...prev]);
  };

  return { products, customers, sales, productionLogs, qualityLogs, addSale, addProductionLog, addQualityLog };
};

