import React, { useState } from 'react';
import { Product, Customer, CartItem, PaymentMethod } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

export const POSModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { products, customers, sales, addSale } = useERPData();
  const [activeTab, setActiveTab] = useState<'sell' | 'history'>('sell');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>('Efectivo');

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  const handleCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    addSale(customer.id, customer.alias, cart, total, paymentMethod);
    setCart([]);
    setCustomer(null);
    setSearch('');
    alert("Venta registrada exitosamente.");
    setActiveTab('history');
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn overflow-hidden bg-sky-50 pb-24">
      <ModuleHeader title="POS Fundadores" onBack={onBack} />

      {/* Tab Switcher */}
      <div className="px-6 flex gap-2 mb-4">
        <button 
          onClick={() => setActiveTab('sell')}
          className={`flex-1 py-3 rounded-2xl text-xs font-bold transition-all ${activeTab === 'sell' ? 'bg-sky-600 text-white' : 'bg-white text-sky-400'}`}
        >
          Nueva Venta
        </button>
        <button 
          onClick={() => setActiveTab('history')}
          className={`flex-1 py-3 rounded-2xl text-xs font-bold transition-all ${activeTab === 'history' ? 'bg-sky-600 text-white' : 'bg-white text-sky-400'}`}
        >
          Historial
        </button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6">
          <section>
            <div className="relative">
              <input 
                type="text" 
                placeholder="Cliente (Alias)..." 
                className="w-full bg-white border-none rounded-3xl py-4 px-6 shadow-sm focus:ring-2 ring-sky-300 outline-none"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
              {search && !customer && (
                <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 z-50 border border-sky-50 max-h-40 overflow-y-auto">
                  {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                    <button 
                      key={c.id}
                      onClick={() => { setCustomer(c); setSearch(c.alias); }}
                      className="w-full text-left p-4 hover:bg-sky-50 border-b border-sky-50 last:border-none font-bold text-sky-900"
                    >
                      {c.alias}
                    </button>
                  ))}
                </div>
              )}
            </div>
            {customer && (
              <div className="mt-3 bg-indigo-500 text-white p-4 rounded-3xl flex justify-between items-center shadow-lg shadow-indigo-100">
                <span className="font-bold flex items-center gap-2"><i className="fas fa-user-check"></i> {customer.alias}</span>
                <button onClick={() => { setCustomer(null); setSearch(''); }}><i className="fas fa-times-circle"></i></button>
              </div>
            )}
          </section>

          <section>
            <div className="grid grid-cols-2 gap-3">
              {products.map(p => (
                <button 
                  key={p.id}
                  onClick={() => addToCart(p)}
                  className="bg-white p-5 rounded-[2.5rem] shadow-sm border border-transparent hover:border-sky-200 active:bg-sky-50 transition-all text-left group"
                >
                  <div className="text-sm font-black text-sky-900 mb-1">{p.name}</div>
                  <div className="text-sky-600 font-bold">${p.price}</div>
                  <div className="text-[10px] text-sky-300 mt-2 font-bold">Stock: {p.stock}</div>
                </button>
              ))}
            </div>
          </section>

          {cart.length > 0 && (
            <RoundedCard className="bg-white border-sky-100">
              <div className="flex justify-between items-center mb-4">
                <h3 className="font-black text-sky-900 text-sm uppercase">Resumen</h3>
                <div className="flex gap-1">
                  {(['Efectivo', 'Transferencia'] as PaymentMethod[]).map(m => (
                    <button 
                      key={m}
                      onClick={() => setPaymentMethod(m)}
                      className={`text-[9px] font-bold px-3 py-1 rounded-full border transition-all ${paymentMethod === m ? 'bg-sky-600 text-white border-sky-600' : 'bg-white text-sky-400 border-sky-100'}`}
                    >
                      {m}
                    </button>
                  ))}
                </div>
              </div>
              <div className="space-y-2 mb-4">
                {cart.map(item => (
                  <div key={item.id} className="flex justify-between text-xs">
                    <span className="text-sky-700">{item.quantity}x {item.name}</span>
                    <span className="font-bold text-sky-900">${item.price * item.quantity}</span>
                  </div>
                ))}
