                  <div className="flex justify-between mt-1">
                    <span className="text-xs text-sky-400">{s.id} • {s.items.length} prod.</span>
                    <span className="font-black text-sky-600 text-sm">${s.total}</span>
                  </div>
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      )}

      {activeTab === 'sell' && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/90 backdrop-blur-xl border-t border-sky-50 z-40">
          <ActionButton disabled={cart.length === 0} onClick={handleCheckout}>
            Confirmar e Imprimir
          </ActionButton>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard } from './ui/Cards';

export const ProductionModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { productionLogs, qualityLogs, addProductionLog, addQualityLog } = useERPData();
  const [seconds, setSeconds] = useState(0);
  const [isRunning, setIsRunning] = useState(false);
  const [activeProcess, setActiveProcess] = useState<'none' | 'backwash' | 'regeneration'>('none');
  const [qualityInput, setQualityInput] = useState({ tds: 8, ph: 7.2, hardness: 0 });

  useEffect(() => {
    let interval: any;
    if (isRunning) {
      interval = setInterval(() => setSeconds(s => s + 1), 1000);
    }
    return () => clearInterval(interval);
  }, [isRunning]);

  const stopProcess = () => {
    if (isRunning) {
      addProductionLog({ type: activeProcess as any, duration: seconds });
      setIsRunning(false);
      setActiveProcess('none');
      setSeconds(0);
      alert("Proceso registrado en historial.");
    }
  };

  const saveQuality = () => {
    addQualityLog({ ...qualityInput, notes: "Medición rutinaria" });
    alert("Control de calidad guardado.");
  };

  return (
    <div className="px-6 py-8 animate-fadeIn h-full overflow-y-auto pb-24 bg-sky-50">
      <ModuleHeader title="Planta Fundadores" onBack={onBack} />

      <div className="space-y-6">
        {/* Timer Section */}
        <RoundedCard className="flex flex-col items-center bg-white border-none shadow-xl">
          <h3 className="text-sky-400 font-bold uppercase text-[10px] tracking-widest mb-4">Cronómetro de Filtración</h3>
          <div className="text-6xl font-black text-sky-900 mb-6 font-mono tracking-tighter">
            {Math.floor(seconds / 60).toString().padStart(2, '0')}:{(seconds % 60).toString().padStart(2, '0')}
          </div>
          <div className="flex gap-3 w-full">
            {!isRunning ? (
              <>
                <button 
                  onClick={() => { setActiveProcess('backwash'); setIsRunning(true); }}
                  className="flex-1 bg-sky-500 text-white py-4 rounded-3xl font-bold text-sm shadow-lg shadow-sky-100 active:scale-95 transition-all"
                >
                  Retrolavado
                </button>
                <button 
                  onClick={() => { setActiveProcess('regeneration'); setIsRunning(true); }}
                  className="flex-1 bg-indigo-500 text-white py-4 rounded-3xl font-bold text-sm shadow-lg shadow-indigo-100 active:scale-95 transition-all"
                >
                  Regen.
                </button>
              </>
            ) : (
              <button 
                onClick={stopProcess}
                className="w-full bg-red-500 text-white py-4 rounded-3xl font-bold text-sm animate-pulse"
              >
                Finalizar {activeProcess}
              </button>
            )}
          </div>
        </RoundedCard>

        {/* Quality Input */}
        <RoundedCard className="bg-white border-none shadow-md">
          <h3 className="text-sky-900 font-bold text-sm uppercase mb-6 tracking-wide">Control de Calidad</h3>
          <div className="grid grid-cols-3 gap-4 mb-6">
            <div className="text-center">
              <label className="text-[10px] font-bold text-sky-400 uppercase block mb-2">TDS</label>
              <input 
                type="number" 
                value={qualityInput.tds} 
                onChange={e => setQualityInput({...qualityInput, tds: Number(e.target.value)})}
                className="w-full bg-sky-50 border-none rounded-2xl p-3 text-center font-black text-sky-900 text-lg outline-none" 
              />
            </div>
            <div className="text-center">
              <label className="text-[10px] font-bold text-sky-400 uppercase block mb-2">pH</label>
              <input 
                type="number" 
                step="0.1"
                value={qualityInput.ph} 
                onChange={e => setQualityInput({...qualityInput, ph: Number(e.target.value)})}
                className="w-full bg-sky-50 border-none rounded-2xl p-3 text-center font-black text-sky-900 text-lg outline-none" 
              />
            </div>
            <div className="text-center">
              <label className="text-[10px] font-bold text-sky-400 uppercase block mb-2">Dureza</label>
              <input 
                type="number" 
                value={qualityInput.hardness} 
                onChange={e => setQualityInput({...qualityInput, hardness: Number(e.target.value)})}
                className="w-full bg-sky-50 border-none rounded-2xl p-3 text-center font-black text-sky-900 text-lg outline-none" 
              />
            </div>
          </div>
          <button 
            onClick={saveQuality}
            className="w-full bg-sky-900 text-white py-4 rounded-3xl font-bold text-sm shadow-xl hover:bg-black active:scale-[0.98] transition-all"
          >
            Registrar Muestra
          </button>
        </RoundedCard>

        {/* History Log */}
        <section>
          <h4 className="text-[10px] font-black uppercase text-sky-400 mb-3 px-2">Últimos Registros</h4>
          <div className="space-y-3">
            {qualityLogs.slice(0, 3).map(log => (
              <div key={log.id} className="bg-white/60 p-4 rounded-3xl flex justify-between items-center border border-white">
                <div>
                  <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-full ${
                    log.status === 'optimal' ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'
                  }`}>
                    {log.status}
                  </span>
                  <p className="text-xs font-bold text-sky-900 mt-1">TDS: {log.tds}ppm • pH: {log.ph}</p>
                </div>
                <span className="text-[9px] text-sky-300 font-bold">{new Date(log.timestamp).toLocaleDateString()}</span>
              </div>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
};

