                    className="w-full py-2 bg-white text-sky-600 rounded-xl text-[10px] font-bold shadow-sm"
                  >
                    Probar en Google Maps
                  </button>
                </div>
              ) : (
                <p className="text-[10px] text-sky-400 mb-4">Aún no se ha capturado la ubicación para optimizar la ruta de este cliente.</p>
