                disabled={isCapturingLocation}
                className={`w-full mt-2 py-3 rounded-2xl font-bold text-xs flex items-center justify-center gap-2 transition-all ${
                  isCapturingLocation ? 'bg-sky-200 text-sky-400 cursor-not-allowed' : 'bg-sky-900 text-white shadow-lg active:scale-95'
                }`}
              >
                {isCapturingLocation ? (
                  <i className="fas fa-spinner animate-spin"></i>
                ) : (
