                  <div>
                    <h4 className="font-black text-sky-900 leading-tight">{c.alias}</h4>
                    <p className="text-[10px] text-sky-400 font-bold uppercase">{c.name}</p>
                    <div className="flex gap-2 mt-1">
                      {c.specialPrice && (
                        <span className="bg-emerald-100 text-emerald-600 text-[8px] font-black px-2 py-0.5 rounded-full">
                          ${c.specialPrice}
                        </span>
                      )}
                      {c.lat && (
                        <span className="bg-sky-100 text-sky-600 text-[8px] font-black px-2 py-0.5 rounded-full flex items-center gap-1">
                          <i className="fas fa-map-pin"></i> GPS
                        </span>
                      )}
                    </div>
                  </div>
                </div>
                <div className="flex gap-1">
                  {c.lat && (
                    <button 
                      onClick={() => window.open(`https://www.google.com/maps?q=${c.lat},${c.lng}`, '_blank')}
                      className="w-8 h-8 bg-sky-50 text-sky-500 rounded-lg flex items-center justify-center text-xs"
                    >
                      <i className="fas fa-location-arrow"></i>
                    </button>
                  )}
                  {c.phone && (
                    <a href={`https://wa.me/52${c.phone}`} className="w-8 h-8 bg-emerald-50 text-emerald-500 rounded-lg flex items-center justify-center text-xs">
                      <i className="fab fa-whatsapp"></i>
                    </a>
                  )}
                  <button onClick={() => handleEdit(c)} className="w-8 h-8 bg-sky-50 text-sky-500 rounded-lg flex items-center justify-center text-xs">
                    <i className="fas fa-pen"></i>
                  </button>
                  <button onClick={() => handleDelete(c.id)} className="w-8 h-8 bg-red-50 text-red-500 rounded-lg flex items-center justify-center text-xs">
                    <i className="fas fa-trash-alt"></i>
                  </button>
                </div>
              </div>
            </RoundedCard>
          ))}
        </div>

        <button 
          onClick={() => setEditingCustomer({})}
          className="w-full py-4 border-2 border-dashed border-sky-200 rounded-[2rem] text-sky-400 font-bold text-sm mt-4 hover:bg-white transition-colors"
        >
          <i className="fas fa-plus mr-2"></i> Registrar Nuevo Cliente
        </button>
      </div>
    </div>
  );
};

export type ViewType = 'dashboard' | 'pos' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  balance: number; // Positive means debt
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Crédito' | 'Multimodal';

export interface PaymentSplit {
  method: 'Efectivo' | 'Transferencia';
  amount: number;
}

export interface Sale {
  id: string;
  timestamp: number;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  paidAmount: number;
  change: number;
  paymentSplits: PaymentSplit[];
  emptyGarrafonsReturned: number;
  synced: boolean;
}

export type FilterStage = 'Multicama' | 'Carbon Activado' | 'Zeolita';
export type FilterProcess = 'Backwash' | 'Fast Rinse';

export interface ProductionStep {
  stage: FilterStage;
  process: FilterProcess;
  duration: number; // seconds
}

export interface Employee {
  id: string;
  name: string;
  role: 'Repartidor' | 'Planta' | 'Administrador';
  phone: string;
}

export interface Vehicle {
  id: string;
  plate: string;
  description: string;
  loadCapacity: number;
  currentLoad: number;
}

import { useState, useEffect } from 'react';
import { Product, Customer, Sale, CartItem, PaymentMethod, Employee, Vehicle, PaymentSplit } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS } from '../constants';

export const useERPData = () => {
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    return saved ? JSON.parse(saved) : [
      { id: 'e1', name: 'Oscar El Rayo', role: 'Repartidor', phone: '3312345678' },
      { id: 'e2', name: 'Ana Gomez', role: 'Planta', phone: '3387654321' }
    ];
  });

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    return saved ? JSON.parse(saved) : [
      { id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0 }
    ];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
  }, [products, customers, sales, employees, vehicles]);

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number
  ) => {
    const change = Math.max(0, paidAmount - total);
    const debtAmount = Math.max(0, total - paidAmount);

    const newSale: Sale = {
      id: `TKT-${Date.now().toString().slice(-6)}`,
      timestamp: Date.now(),
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change,
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false
    };

    setSales(prev => [newSale, ...prev]);

    // Update Customer Debt
    setCustomers(prev => prev.map(c => {
      if (c.id === customerId) {
        return { ...c, balance: (c.balance || 0) + debtAmount };
      }
      return c;
    }));

    // Update Inventory
    setProducts(prev => prev.map(p => {
      const cartItem = items.find(item => item.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    return newSale;
  };

  const saveCustomer = (customer: Customer) => {
    setCustomers(prev => {
      const exists = prev.find(c => c.id === customer.id);
      if (exists) return prev.map(c => c.id === customer.id ? customer : c);
      return [...prev, customer];
    });
  };

  return { 
    products, setProducts,
    customers, saveCustomer,
    sales, addSale,
    employees, setEmployees,
    vehicles, setVehicles
  };
};

import React, { useState } from 'react';
import { Product, Customer, CartItem, PaymentSplit, Sale } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

export const POSModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { products, customers, sales, addSale } = useERPData();
  const [activeTab, setActiveTab] = useState<'sell' | 'history'>('sell');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);

  // Payment State
  const [paidCash, setPaidCash] = useState<string>('');
  const [paidTransfer, setPaidTransfer] = useState<string>('');

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  const totalPaid = (parseFloat(paidCash) || 0) + (parseFloat(paidTransfer) || 0);
  const change = Math.max(0, totalPaid - total);
  const remainingDebt = Math.max(0, total - totalPaid);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(i => {
      if (i.id === id) {
        const newQty = Math.max(0, i.quantity + delta);
        return { ...i, quantity: newQty };
      }
      return i;
    }).filter(i => i.quantity > 0));
  };

  const encryptData = (data: string) => {
    return btoa(`AQUA-PRO-SECURE|${data}`);
  };

  const generateTicketPDF = (sale: Sale) => {
    const qrData = encryptData(JSON.stringify({ id: sale.id, total: sale.total, date: sale.timestamp }));
    const ticketHtml = `
      <div style="font-family: sans-serif; padding: 20px; text-align: center; border: 1px solid #eee; width: 300px; margin: auto;">
        <h2 style="color: #0284c7; margin-bottom: 5px;">AQUA+ FUNDADORES</h2>
        <p style="font-size: 10px; margin: 0;">Agua Purificada de Alta Calidad</p>
        <p style="font-size: 10px; margin: 0;">Tel: 33-1234-5678</p>
        <hr/>
        <p style="font-size: 12px; font-weight: bold;">Ticket: ${sale.id}</p>
        <p style="font-size: 10px;">${new Date(sale.timestamp).toLocaleString()}</p>
        <div style="text-align: left; margin: 15px 0; font-size: 12px;">
          ${sale.items.map(i => `<div>${i.quantity}x ${i.name} - $${i.quantity * i.price}</div>`).join('')}
        </div>
        <hr/>
        <div style="display: flex; justify-content: space-between; font-weight: bold;">
          <span>TOTAL:</span><span>$${sale.total}</span>
        </div>
        <div style="display: flex; justify-content: space-between; font-size: 10px;">
          <span>PAGADO:</span><span>$${sale.paidAmount}</span>
        </div>
        <div style="display: flex; justify-content: space-between; font-size: 10px;">
          <span>CAMBIO:</span><span>$${sale.change}</span>
        </div>
        <p style="margin-top: 15px; font-weight: bold; color: #0284c7;">¡Gracias por tu preferencia!</p>
        <div style="margin-top: 20px;">
          <img src="https://api.qrserver.com/v1/create-qr-code/?size=120x120&data=${encodeURIComponent(qrData)}" alt="QR Secure"/>
          <p style="font-size: 8px; color: #aaa; margin-top: 5px;">Validación Exclusiva Aqua+</p>
        </div>
      </div>
    `;

    const win = window.open('', '_blank');
    win?.document.write(ticketHtml);
    win?.print();
    win?.close();
  };

  const handleCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    if (cart.length === 0) return alert("El carrito está vacío.");

    const splits: PaymentSplit[] = [];
    if (parseFloat(paidCash) > 0) splits.push({ method: 'Efectivo', amount: parseFloat(paidCash) });
    if (parseFloat(paidTransfer) > 0) splits.push({ method: 'Transferencia', amount: parseFloat(paidTransfer) });

    const sale = addSale(customer.id, cart, total, totalPaid, splits, vacios);

    // Clean up
    setCart([]);
    setCustomer(null);
    setSearch('');
    setVacios(0);
    setPaidCash('');
    setPaidTransfer('');

    alert(`Venta exitosa. ${remainingDebt > 0 ? 'Deuda registrada: $' + remainingDebt : ''}`);
    generateTicketPDF(sale);
    setActiveTab('history');
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-sky-50 pb-24 overflow-hidden">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'sell' ? 'bg-sky-600 text-white' : 'bg-white text-sky-400'}`}>Nueva Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'history' ? 'bg-sky-600 text-white' : 'bg-white text-sky-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-20">
          {/* Customer Search */}
          <section>
            <div className="relative">
              <input 
                type="text" 
                placeholder="Buscar Cliente..." 
                className="w-full bg-white border-none rounded-3xl py-4 px-6 shadow-sm outline-none"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
              {search && !customer && (
                <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 z-50 overflow-hidden">
                  {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                    <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 border-b border-sky-50 font-bold text-sky-900">{c.alias} (Deuda: ${c.balance})</button>
                  ))}
                </div>
              )}
            </div>
            {customer && (
              <div className="mt-3 bg-indigo-500 text-white p-4 rounded-3xl flex justify-between items-center shadow-lg">
                <span className="font-bold"><i className="fas fa-user-check mr-2"></i>{customer.alias} (Saldo: ${customer.balance})</span>
                <button onClick={() => { setCustomer(null); setSearch(''); }}><i className="fas fa-times-circle"></i></button>
              </div>
            )}
          </section>

          {/* Catalog */}
          <div className="grid grid-cols-2 gap-3">
            {products.map(p => (
              <button key={p.id} onClick={() => addToCart(p)} className="bg-white p-5 rounded-[2rem] shadow-sm border border-transparent active:bg-sky-50 transition-all text-left">
                <div className="text-sm font-black text-sky-900">{p.name}</div>
                <div className="text-sky-600 font-bold">${p.price}</div>
              </button>
            ))}
          </div>

          {/* Cart & Vacios */}
          {cart.length > 0 && (
            <div className="space-y-4">
              <RoundedCard>
                <h3 className="text-[10px] font-black uppercase text-sky-400 mb-3">Carrito Editable</h3>
                <div className="space-y-3">
                  {cart.map(item => (
                    <div key={item.id} className="flex justify-between items-center">
                      <div className="flex-1 text-xs font-bold text-sky-900">{item.name}</div>
                      <div className="flex items-center gap-2">
                        <button onClick={() => updateQuantity(item.id, -1)} className="w-8 h-8 bg-sky-50 rounded-lg text-sky-600">-</button>
                        <span className="font-black w-6 text-center">{item.quantity}</span>
                        <button onClick={() => updateQuantity(item.id, 1)} className="w-8 h-8 bg-sky-50 rounded-lg text-sky-600">+</button>
                      </div>
                    </div>
                  ))}
                </div>
              </RoundedCard>

              <RoundedCard className="bg-sky-900 text-white">
                <div className="flex justify-between items-center">
                  <span className="font-bold text-sm">Garrafones Vacíos Recibidos:</span>
                  <div className="flex items-center gap-3">
                    <button onClick={() => setVacios(Math.max(0, vacios - 1))} className="w-10 h-10 bg-white/20 rounded-full">-</button>
                    <span className="text-xl font-black">{vacios}</span>
                    <button onClick={() => setVacios(vacios + 1)} className="w-10 h-10 bg-white/20 rounded-full">+</button>
                  </div>
                </div>
              </RoundedCard>

              <RoundedCard>
                <div className="flex justify-between items-end mb-4">
                  <div>
                    <span className="text-xs text-sky-400 font-bold block">TOTAL A PAGAR</span>
                    <span className="text-3xl font-black text-sky-900">${total}</span>
                  </div>
                </div>

                <div className="space-y-3">
                  <div className="flex items-center gap-3">
                    <div className="flex-1">
                      <label className="text-[9px] font-black text-sky-400 block ml-2">EFECTIVO</label>
                      <input type="number" value={paidCash} onChange={e => setPaidCash(e.target.value)} className="w-full bg-sky-50 p-3 rounded-2xl outline-none font-bold" placeholder="0.00"/>
                    </div>
                    <div className="flex-1">
                      <label className="text-[9px] font-black text-sky-400 block ml-2">TRANSFERENCIA</label>
                      <input type="number" value={paidTransfer} onChange={e => setPaidTransfer(e.target.value)} className="w-full bg-sky-50 p-3 rounded-2xl outline-none font-bold" placeholder="0.00"/>
                    </div>
                  </div>

                  <div className="flex justify-between pt-2 border-t border-sky-50">
                    <span className="text-xs font-bold text-sky-400">CAMBIO:</span>
                    <span className="font-black text-emerald-600">${change}</span>
                  </div>
                  {remainingDebt > 0 && (
                    <div className="flex justify-between">
                      <span className="text-xs font-bold text-red-400">RESTANTE (DEUDA):</span>
                      <span className="font-black text-red-600">${remainingDebt}</span>
                    </div>
                  )}
                </div>
              </RoundedCard>
            </div>
          )}
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto px-6 space-y-4">
          {sales.map(s => (
            <RoundedCard key={s.id} className="py-4">
              <div className="flex justify-between items-start">
                <div>
                  <h4 className="font-bold text-sky-900">{s.customerAlias}</h4>
                  <p className="text-[10px] text-sky-400">{new Date(s.timestamp).toLocaleString()}</p>
                </div>
                <div className="text-right">
                  <span className="font-black text-sky-600 block">${s.total}</span>
                  <button onClick={() => generateTicketPDF(s)} className="text-[9px] text-sky-400 underline uppercase font-bold">Re-imprimir</button>
                </div>
              </div>
            </RoundedCard>
          ))}
        </div>
      )}

      {activeTab === 'sell' && (
