  );
};

import React, { useState, useEffect } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard } from './ui/Cards';

const FILTER_SEQUENCE: { stage: string, process: string, time: number }[] = [
  { stage: 'Multicama', process: 'Backwash', time: 300 }, // 5 min
  { stage: 'Multicama', process: 'Fast Rinse', time: 180 }, // 3 min
  { stage: 'Carbon Activado', process: 'Backwash', time: 300 },
  { stage: 'Carbon Activado', process: 'Fast Rinse', time: 180 },
  { stage: 'Zeolita', process: 'Backwash', time: 300 },
  { stage: 'Zeolita', process: 'Fast Rinse', time: 180 },
];

export const ProductionModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [currentStepIdx, setCurrentStepIdx] = useState(0);
  const [timeLeft, setTimeLeft] = useState(0);
  const [isRunning, setIsRunning] = useState(false);

  const [hardness, setHardness] = useState(8);
  const [showRegenAlert, setShowRegenAlert] = useState(false);

  useEffect(() => {
    let timer: any;
    if (isRunning && timeLeft > 0) {
      timer = setInterval(() => setTimeLeft(t => t - 1), 1000);
    } else if (isRunning && timeLeft === 0) {
      if (currentStepIdx < FILTER_SEQUENCE.length - 1) {
        setCurrentStepIdx(i => i + 1);
        setTimeLeft(FILTER_SEQUENCE[currentStepIdx + 1].time);
      } else {
        setIsRunning(false);
        alert("Ciclo de filtrado completado exitosamente.");
      }
    }
    return () => clearInterval(timer);
  }, [isRunning, timeLeft, currentStepIdx]);

  const startSequence = () => {
    setCurrentStepIdx(0);
    setTimeLeft(FILTER_SEQUENCE[0].time);
    setIsRunning(true);
  };

  const handleHardnessChange = (val: number) => {
    setHardness(val);
    setShowRegenAlert(val > 50);
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  return (
    <div className="px-6 py-8 animate-fadeIn h-full bg-sky-50 overflow-y-auto pb-24">
      <ModuleHeader title="Tren de Filtrado" onBack={onBack} />

      <div className="space-y-6">
        {/* Sequence Control */}
        <RoundedCard className="text-center bg-white border-none shadow-xl">
          <div className="mb-4">
            <span className="text-[10px] font-black uppercase tracking-widest text-sky-400">Paso {currentStepIdx + 1} de 6</span>
            <h3 className="text-2xl font-black text-sky-900">{FILTER_SEQUENCE[currentStepIdx].stage}</h3>
            <p className="text-sky-500 font-bold uppercase text-xs">{FILTER_SEQUENCE[currentStepIdx].process}</p>
          </div>

          <div className="text-6xl font-mono font-black text-sky-900 mb-6 tabular-nums">
            {formatTime(timeLeft)}
          </div>

          {!isRunning ? (
            <button onClick={startSequence} className="w-full bg-sky-600 text-white py-5 rounded-[2rem] font-black shadow-lg shadow-sky-100">INICIAR CICLO COMPLETO</button>
          ) : (
            <button onClick={() => setIsRunning(false)} className="w-full bg-red-500 text-white py-5 rounded-[2rem] font-black shadow-lg shadow-red-100">PAUSAR PROCESO</button>
          )}

          <div className="mt-6 flex justify-between gap-1">
            {FILTER_SEQUENCE.map((_, idx) => (
              <div key={idx} className={`h-2 flex-1 rounded-full transition-colors ${idx === currentStepIdx ? 'bg-sky-500' : idx < currentStepIdx ? 'bg-emerald-400' : 'bg-sky-100'}`}></div>
            ))}
          </div>
        </RoundedCard>

        {/* Quality Alerts */}
        <section className="space-y-4">
          <h4 className="text-[10px] font-black uppercase text-sky-400 ml-2 tracking-widest">Monitoreo de Resinas</h4>
          <RoundedCard>
            <div className="flex justify-between items-center mb-4">
              <span className="text-sm font-bold text-sky-900">Medición de Dureza (PPM)</span>
              <input 
                type="number" 
                value={hardness} 
                onChange={e => handleHardnessChange(Number(e.target.value))}
                className="w-16 bg-sky-50 p-2 rounded-xl text-center font-black outline-none"
              />
            </div>

            {showRegenAlert ? (
              <div className="bg-red-50 border border-red-100 p-4 rounded-3xl animate-pulse">
                <div className="flex items-center gap-3 text-red-600 font-black text-xs uppercase mb-2">
                  <i className="fas fa-triangle-exclamation"></i> ALERTA DE REGENERACIÓN
                </div>
                <p className="text-[10px] text-red-800 font-medium">La dureza es superior a 50. Es necesario cargar sal al tanque de salmuera para regenerar el filtro de Zeolita.</p>
                <button className="mt-3 w-full bg-red-600 text-white py-3 rounded-2xl text-[10px] font-black uppercase">Marcar como Atendido</button>
              </div>
            ) : (
              <div className="bg-emerald-50 p-4 rounded-3xl flex items-center gap-3">
                <i className="fas fa-check-circle text-emerald-500 text-xl"></i>
                <span className="text-xs font-bold text-emerald-700">Dureza óptima. Resina funcionando correctamente.</span>
              </div>
            )}
          </RoundedCard>
        </section>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Customer, GarrafonType } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

const GARRAFON_TYPES: GarrafonType[] = ['Aqua', 'Bonafont', 'Ciel', 'Generico'];

export const CustomersModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { customers, saveCustomer, deleteCustomer, sales } = useERPData();
  const [search, setSearch] = useState('');
  const [editingCustomer, setEditingCustomer] = useState<Partial<Customer> | null>(null);
  const [viewingHistory, setViewingHistory] = useState<Customer | null>(null);

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(search.toLowerCase()) || 
    c.alias.toLowerCase().includes(search.toLowerCase())
  );

  const handleSave = () => {
    if (!editingCustomer?.name || !editingCustomer?.alias) {
      alert("Nombre y Alias son obligatorios.");
      return;
    }
    const customerToSave: Customer = {
      id: editingCustomer.id || Math.random().toString(36).substr(2, 9),
      name: editingCustomer.name,
      alias: editingCustomer.alias,
      phone: editingCustomer.phone || '',
      specialPrice: editingCustomer.specialPrice || undefined,
      garrafonType: editingCustomer.garrafonType || 'Generico',
      balance: editingCustomer.balance || 0,
      lat: editingCustomer.lat,
      lng: editingCustomer.lng,
    };
    saveCustomer(customerToSave);
    setEditingCustomer(null);
  };

  if (viewingHistory) {
    const customerSales = sales.filter(s => s.customerId === viewingHistory.id);
    return (
      <div className="h-full bg-sky-50 overflow-y-auto">
        <ModuleHeader title={`Historial: ${viewingHistory.alias}`} onBack={() => setViewingHistory(null)} />
        <div className="px-6 space-y-4 pb-10">
          {customerSales.length === 0 ? (
            <p className="text-center py-20 text-sky-300">Sin compras registradas.</p>
          ) : (
            customerSales.map(s => (
              <RoundedCard key={s.id} className="py-4">
                <div className="flex justify-between font-bold">
                  <span className="text-sky-900">{s.id}</span>
                  <span className="text-sky-600">${s.total}</span>
                </div>
                <p className="text-[10px] text-sky-400">{new Date(s.timestamp).toLocaleDateString()}</p>
                <div className="mt-2 flex gap-1">
                  {s.items.map(i => <span key={i.id} className="bg-sky-50 text-[8px] px-2 py-0.5 rounded-full">{i.quantity}x {i.name}</span>)}
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      </div>
    );
  }

  if (editingCustomer) {
    return (
      <div className="h-full bg-sky-50 overflow-y-auto pb-24">
        <ModuleHeader title={editingCustomer.id ? "Editar Cliente" : "Nuevo Cliente"} onBack={() => setEditingCustomer(null)} />
        <div className="px-6 space-y-4">
          <input className="w-full bg-white p-4 rounded-3xl outline-none" placeholder="Nombre" value={editingCustomer.name || ''} onChange={e => setEditingCustomer({...editingCustomer, name: e.target.value})}/>
          <input className="w-full bg-white p-4 rounded-3xl outline-none" placeholder="Alias" value={editingCustomer.alias || ''} onChange={e => setEditingCustomer({...editingCustomer, alias: e.target.value})}/>

          <div className="space-y-2">
            <label className="text-[10px] font-black uppercase text-sky-400 ml-2">Tipo de Garrafón Predominante</label>
            <div className="grid grid-cols-2 gap-2">
              {GARRAFON_TYPES.map(t => (
                <button 
                  key={t}
                  onClick={() => setEditingCustomer({...editingCustomer, garrafonType: t})}
                  className={`py-3 rounded-2xl text-[10px] font-black transition-all ${editingCustomer.garrafonType === t ? 'bg-sky-600 text-white' : 'bg-white text-sky-400'}`}
                >
                  {t}
                </button>
              ))}
            </div>
          </div>

          <ActionButton onClick={handleSave}>Guardar Cliente</ActionButton>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 overflow-y-auto pb-24">
      <ModuleHeader title="Clientes" onBack={onBack} />
      <div className="px-6 space-y-4">
        <input type="text" placeholder="Buscar..." className="w-full bg-white p-4 rounded-3xl outline-none" value={search} onChange={e => setSearch(e.target.value)}/>
        {filteredCustomers.map(c => (
          <RoundedCard key={c.id} className="py-4">
            <div className="flex justify-between items-center">
              <div>
                <h4 className="font-black text-sky-900 leading-tight">{c.alias}</h4>
                <div className="flex gap-2 mt-1">
                  <span className="bg-sky-100 text-sky-600 text-[8px] font-black px-2 py-0.5 rounded-full">{c.garrafonType || 'Aqua'}</span>
                  {c.balance > 0 && <span className="bg-red-100 text-red-600 text-[8px] font-black px-2 py-0.5 rounded-full">Adeudo: ${c.balance}</span>}
                </div>
              </div>
              <div className="flex gap-2">
                <button onClick={() => setViewingHistory(c)} className="w-8 h-8 bg-sky-50 text-sky-500 rounded-lg flex items-center justify-center text-xs"><i className="fas fa-receipt"></i></button>
                <button onClick={() => setEditingCustomer(c)} className="w-8 h-8 bg-sky-50 text-sky-500 rounded-lg flex items-center justify-center text-xs"><i className="fas fa-pen"></i></button>
              </div>
            </div>
          </RoundedCard>
        ))}
        <button onClick={() => setEditingCustomer({})} className="w-full py-4 border-2 border-dashed border-sky-200 rounded-[2rem] text-sky-400 font-bold text-sm">+ Nuevo Cliente</button>
      </div>
    </div>
  );
};

