               </div>
               <div className="flex gap-2">
                 <button onClick={() => updateLoad(v.id, -1)} className="w-12 h-12 bg-sky-50 rounded-2xl flex items-center justify-center text-sky-600 font-black">-</button>
                 <button onClick={() => updateLoad(v.id, 1)} className="w-12 h-12 bg-sky-900 rounded-2xl flex items-center justify-center text-white font-black">+</button>
