        {renderContent()}
      </main>
      {currentView === 'dashboard' && <VoiceAI onAction={(res) => res.action === 'SALE' && navigateTo('pos')} />}
    </div>
  );
};

export default App;

export type ViewType = 'dashboard' | 'pos' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  balance: number; // Positive means debt
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Crédito' | 'Multimodal';

export interface PaymentSplit {
  method: 'Efectivo' | 'Transferencia';
  amount: number;
}

export interface Sale {
  id: string;
  timestamp: number;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  paidAmount: number;
  change: number;
  paymentSplits: PaymentSplit[];
  emptyGarrafonsReturned: number;
  synced: boolean;
}

export type FilterStage = 'Multicama' | 'Carbon Activado' | 'Zeolita';
export type FilterProcess = 'Backwash' | 'Fast Rinse';

export interface ProductionStep {
  stage: FilterStage;
  process: FilterProcess;
  duration: number; // seconds
}

export interface Employee {
  id: string;
  name: string;
  role: 'Repartidor' | 'Planta' | 'Administrador';
  phone: string;
}

export interface Vehicle {
  id: string;
  plate: string;
  description: string;
  loadCapacity: number;
  currentLoad: number;
}

import React, { useState } from 'react';
import { Product, Customer, CartItem, PaymentSplit, Sale } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

export const POSModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { products, customers, sales, addSale } = useERPData();
  const [activeTab, setActiveTab] = useState<'sell' | 'history'>('sell');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);

  // Payment State
  const [paidCash, setPaidCash] = useState<string>('');
  const [paidTransfer, setPaidTransfer] = useState<string>('');

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  const totalPaid = (parseFloat(paidCash) || 0) + (parseFloat(paidTransfer) || 0);
  const change = Math.max(0, totalPaid - total);
  const remainingDebt = Math.max(0, total - totalPaid);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(i => {
      if (i.id === id) {
        const newQty = Math.max(0, i.quantity + delta);
        return { ...i, quantity: newQty };
      }
      return i;
    }).filter(i => i.quantity > 0));
  };

  const encryptData = (data: string) => {
    return btoa(`AQUA-PRO-SECURE|${data}`);
  };

  const generateTicketPDF = (sale: Sale) => {
    const qrData = encryptData(JSON.stringify({ id: sale.id, total: sale.total, date: sale.timestamp }));
    const ticketHtml = `
      <div style="font-family: 'Helvetica', sans-serif; padding: 20px; text-align: center; border: 1px solid #eee; width: 300px; margin: auto; background: white;">
        <h2 style="color: #0284c7; margin-bottom: 5px;">AQUA+ FUNDADORES</h2>
        <p style="font-size: 10px; margin: 0;">Ruta de Entrega Pro ERP</p>
        <p style="font-size: 10px; margin: 0;">Agua Purificada de Alta Calidad</p>
        <p style="font-size: 10px; margin: 0;">WhatsApp: 33-1234-5678</p>
        <hr style="border: 0; border-top: 1px dashed #ccc; margin: 15px 0;"/>
        <p style="font-size: 12px; font-weight: bold;">Ticket: ${sale.id}</p>
        <p style="font-size: 10px;">${new Date(sale.timestamp).toLocaleString()}</p>
        <hr style="border: 0; border-top: 1px dashed #ccc; margin: 15px 0;"/>
        <div style="text-align: left; margin: 15px 0; font-size: 12px;">
          ${sale.items.map(i => `
            <div style="display: flex; justify-content: space-between; margin-bottom: 5px;">
              <span>${i.quantity}x ${i.name}</span>
              <span>$${i.quantity * i.price}</span>
            </div>`).join('')}
        </div>
        <hr style="border: 0; border-top: 1px solid #eee; margin: 10px 0;"/>
        <div style="display: flex; justify-content: space-between; font-weight: bold; font-size: 16px;">
          <span>TOTAL:</span><span>$${sale.total}</span>
        </div>
        <div style="display: flex; justify-content: space-between; font-size: 12px; color: #666; margin-top: 5px;">
          <span>PAGADO:</span><span>$${sale.paidAmount}</span>
        </div>
        <div style="display: flex; justify-content: space-between; font-size: 12px; color: #10b981;">
          <span>CAMBIO:</span><span>$${sale.change}</span>
        </div>
        <hr style="border: 0; border-top: 1px dashed #ccc; margin: 15px 0;"/>
        <p style="font-size: 12px; font-weight: bold; color: #0284c7;">¡Gracias por tu preferencia!</p>
        <p style="font-size: 10px; color: #999;">"Cada gota cuenta, cada cliente es familia"</p>
        <div style="margin-top: 20px; display: flex; flex-direction: column; align-items: center;">
          <img src="https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrData)}" alt="QR Secure"/>
          <p style="font-size: 8px; color: #aaa; margin-top: 5px; letter-spacing: 1px;">VALIDACIÓN EXCLUSIVA AQUA+ APP</p>
        </div>
      </div>
    `;

    const win = window.open('', '_blank');
    if (win) {
      win.document.write(`<html><head><title>Ticket ${sale.id}</title></head><body>${ticketHtml}</body></html>`);
      win.document.close();
      setTimeout(() => {
        win.print();
        win.close();
      }, 500);
    }
  };

  const handleCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    if (cart.length === 0) return alert("El carrito está vacío.");

    const splits: PaymentSplit[] = [];
    if (parseFloat(paidCash) > 0) splits.push({ method: 'Efectivo', amount: parseFloat(paidCash) });
    if (parseFloat(paidTransfer) > 0) splits.push({ method: 'Transferencia', amount: parseFloat(paidTransfer) });

    const sale = addSale(customer.id, cart, total, totalPaid, splits, vacios);

    // Cleanup state
    setCart([]);
    setCustomer(null);
    setSearch('');
    setVacios(0);
    setPaidCash('');
    setPaidTransfer('');

    alert(`Venta registrada. ${remainingDebt > 0 ? 'Saldo deudor: $' + remainingDebt : ''}`);
    generateTicketPDF(sale);
    setActiveTab('history');
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-sky-50 pb-24 overflow-hidden">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4 shrink-0">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-xs font-bold transition-all ${activeTab === 'sell' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Nueva Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-xs font-bold transition-all ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-20 no-scrollbar">
          {/* Customer Search */}
          <section>
            <div className="relative">
              <input 
                type="text" 
                placeholder="Buscar Cliente (Nombre o Alias)..." 
                className="w-full bg-white border-none rounded-[2rem] py-5 px-8 shadow-sm outline-none focus:ring-2 ring-sky-300"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
              {search && !customer && (
                <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 z-50 overflow-hidden border border-sky-100">
                  {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase()) || c.name.toLowerCase().includes(search.toLowerCase())).map(c => (
                    <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 border-b border-sky-50 last:border-none font-bold text-sky-900 flex justify-between items-center">
                      <span>{c.alias}</span>
                      <span className="text-[10px] bg-red-50 text-red-500 px-2 py-0.5 rounded-full">${c.balance}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
            {customer && (
              <div className="mt-3 bg-indigo-500 text-white p-5 rounded-[2rem] flex justify-between items-center shadow-xl animate-fadeIn">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center">
                    <i className="fas fa-user-check"></i>
                  </div>
                  <div>
                    <span className="font-black block">{customer.alias}</span>
                    <span className="text-[10px] opacity-80 uppercase font-bold">Saldo: ${customer.balance}</span>
                  </div>
                </div>
                <button onClick={() => { setCustomer(null); setSearch(''); }} className="w-8 h-8 flex items-center justify-center bg-white/10 rounded-full"><i className="fas fa-times"></i></button>
              </div>
            )}
          </section>

          {/* Catalog */}
          <div className="grid grid-cols-2 gap-3">
            {products.map(p => (
              <button key={p.id} onClick={() => addToCart(p)} className="bg-white p-5 rounded-[2rem] shadow-sm border border-transparent active:bg-sky-50 hover:border-sky-100 transition-all text-left group">
                <div className="text-sm font-black text-sky-900 group-hover:text-sky-600 transition-colors">{p.name}</div>
                <div className="text-sky-600 font-bold">${p.price}</div>
                <div className="mt-2 h-1 w-8 bg-sky-100 rounded-full group-active:w-full transition-all"></div>
              </button>
            ))}
          </div>

          {/* Cart & Payment */}
          {cart.length > 0 && (
            <div className="space-y-4 animate-fadeIn">
              <RoundedCard className="bg-white/90">
                <h3 className="text-[10px] font-black uppercase text-sky-400 mb-4 tracking-widest">Carrito de Compra</h3>
                <div className="space-y-3">
                  {cart.map(item => (
                    <div key={item.id} className="flex justify-between items-center bg-sky-50/30 p-3 rounded-2xl">
                      <div className="flex-1 text-xs font-bold text-sky-900">{item.name}</div>
                      <div className="flex items-center gap-3">
                        <button onClick={() => updateQuantity(item.id, -1)} className="w-8 h-8 bg-white shadow-sm rounded-xl text-sky-600 flex items-center justify-center"><i className="fas fa-minus text-[10px]"></i></button>
                        <span className="font-black w-6 text-center text-sky-900">{item.quantity}</span>
                        <button onClick={() => updateQuantity(item.id, 1)} className="w-8 h-8 bg-white shadow-sm rounded-xl text-sky-600 flex items-center justify-center"><i className="fas fa-plus text-[10px]"></i></button>
                      </div>
                    </div>
                  ))}
                </div>
              </RoundedCard>

              <RoundedCard className="bg-sky-900 text-white shadow-sky-200">
                <div className="flex justify-between items-center">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center">
                      <i className="fas fa-recycle text-sky-400"></i>
                    </div>
                    <span className="font-bold text-sm">Vacíos Recibidos</span>
                  </div>
                  <div className="flex items-center gap-4">
                    <button onClick={() => setVacios(Math.max(0, vacios - 1))} className="w-10 h-10 bg-white/10 hover:bg-white/20 rounded-full flex items-center justify-center"><i className="fas fa-minus"></i></button>
                    <span className="text-2xl font-black min-w-[30px] text-center">{vacios}</span>
                    <button onClick={() => setVacios(vacios + 1)} className="w-10 h-10 bg-white/10 hover:bg-white/20 rounded-full flex items-center justify-center"><i className="fas fa-plus"></i></button>
                  </div>
                </div>
              </RoundedCard>

              <RoundedCard className="border-t-4 border-t-sky-600">
                <div className="flex justify-between items-start mb-6">
                  <div>
                    <span className="text-[10px] text-sky-400 font-black uppercase tracking-widest block mb-1">Total Venta</span>
                    <span className="text-4xl font-black text-sky-900">${total}</span>
                  </div>
                  {remainingDebt > 0 && (
                    <div className="text-right">
                      <span className="text-[10px] text-red-400 font-black uppercase tracking-widest block mb-1">Restante</span>
                      <span className="text-2xl font-black text-red-500">${remainingDebt}</span>
                    </div>
                  )}
                </div>

                <div className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="text-[9px] font-black text-sky-400 uppercase ml-2">Efectivo</label>
                      <input 
                        type="number" 
                        value={paidCash} 
                        onChange={e => setPaidCash(e.target.value)} 
                        className="w-full bg-sky-50/50 p-4 rounded-2xl outline-none font-bold text-sky-900 border border-transparent focus:border-sky-300 transition-all" 
                        placeholder="0.00"
                      />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black text-sky-400 uppercase ml-2">Transferencia</label>
                      <input 
                        type="number" 
                        value={paidTransfer} 
                        onChange={e => setPaidTransfer(e.target.value)} 
                        className="w-full bg-sky-50/50 p-4 rounded-2xl outline-none font-bold text-sky-900 border border-transparent focus:border-sky-300 transition-all" 
                        placeholder="0.00"
                      />
                    </div>
                  </div>

                  <div className="flex justify-between items-center p-4 bg-emerald-50 rounded-2xl border border-emerald-100">
                    <span className="text-xs font-bold text-emerald-700">CAMBIO A DEVOLVER:</span>
                    <span className="text-xl font-black text-emerald-600">${change}</span>
                  </div>
                </div>
              </RoundedCard>
            </div>
          )}
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto px-6 space-y-4 no-scrollbar">
          {sales.length === 0 ? (
            <div className="text-center py-20 text-sky-300 italic">No hay ventas hoy.</div>
          ) : (
            sales.map(s => (
              <RoundedCard key={s.id} className="py-5 border-none shadow-sm hover:shadow-md transition-shadow group">
                <div className="flex justify-between items-start">
                  <div className="flex gap-4">
                    <div className="w-12 h-12 bg-sky-100 rounded-2xl flex items-center justify-center text-sky-600 font-black">
                      <i className="fas fa-receipt"></i>
                    </div>
                    <div>
                      <h4 className="font-black text-sky-900">{s.customerAlias}</h4>
                      <p className="text-[10px] text-sky-400 font-bold">{new Date(s.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})} • {s.id}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="font-black text-sky-600 block text-lg">${s.total}</span>
                    <button 
                      onClick={() => generateTicketPDF(s)} 
                      className="text-[9px] text-sky-400 underline uppercase font-black tracking-tighter hover:text-sky-600"
                    >
                      <i className="fas fa-print mr-1"></i>Re-imprimir
                    </button>
                  </div>
                </div>
              </RoundedCard>
            ))
