import { useState, useEffect, useCallback } from 'react';
import { Product, Customer, Sale, CartItem, PaymentMethod, Employee, Vehicle, PaymentSplit } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS } from '../constants';

export const useERPData = () => {
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    return saved ? JSON.parse(saved) : [
      { id: 'e1', name: 'Oscar El Rayo', role: 'Repartidor', phone: '3312345678' },
      { id: 'e2', name: 'Ana Gomez', role: 'Planta', phone: '3387654321' }
    ];
  });

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    return saved ? JSON.parse(saved) : [
      { id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0 }
    ];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
  }, [products, customers, sales, employees, vehicles]);

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number
  ) => {
    const change = Math.max(0, paidAmount - total);
    const debtAmount = Math.max(0, total - paidAmount);

    const newSale: Sale = {
      id: `TKT-${Date.now().toString().slice(-6)}`,
      timestamp: Date.now(),
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change,
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false
    };

    setSales(prev => [newSale, ...prev]);

    // Update Customer Debt
    setCustomers(prev => prev.map(c => {
      if (c.id === customerId) {
        return { ...c, balance: (c.balance || 0) + debtAmount };
      }
      return c;
    }));

    // Update Inventory
    setProducts(prev => prev.map(p => {
      const cartItem = items.find(item => item.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    return newSale;
  };

  const saveCustomer = (customer: Customer) => {
    setCustomers(prev => {
      const exists = prev.find(c => c.id === customer.id);
      if (exists) return prev.map(c => c.id === customer.id ? customer : c);
      return [...prev, customer];
    });
  };

  const deleteCustomer = (id: string) => {
    setCustomers(prev => prev.filter(c => c.id !== id));
  };

  const syncData = useCallback((externalData: { sales: Sale[], customers: Customer[] }) => {
    // Merge Sales (by ID, ensuring no duplicates)
    setSales(prev => {
      const existingIds = new Set(prev.map(s => s.id));
      const newSales = externalData.sales.filter(s => !existingIds.has(s.id));
      return [...newSales, ...prev].sort((a, b) => b.timestamp - a.timestamp);
    });

    // Merge Customers (by ID, taking latest based on timestamp if we had it, or just updating)
    setCustomers(prev => {
      const customerMap = new Map(prev.map(c => [c.id, c]));
      externalData.customers.forEach(ec => {
        customerMap.set(ec.id, ec);
      });
      return Array.from(customerMap.values());
    });

    return true;
  }, []);

  return { 
    products, setProducts,
    customers, saveCustomer, deleteCustomer,
    sales, addSale,
    employees, setEmployees,
    vehicles, setVehicles,
    syncData
  };
};

import React, { useState, useEffect, useRef } from 'react';
import Peer, { DataConnection } from 'peerjs';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

export const SyncModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { sales, customers, syncData } = useERPData();
  const [peerId, setPeerId] = useState<string>('');
  const [targetId, setTargetId] = useState<string>('');
  const [status, setStatus] = useState<'idle' | 'connecting' | 'connected' | 'error'>('idle');
  const [lastSync, setLastSync] = useState<number | null>(null);
  const [logs, setLogs] = useState<string[]>([]);

  const peerRef = useRef<Peer | null>(null);
  const connRef = useRef<DataConnection | null>(null);

  const addLog = (msg: string) => setLogs(prev => [msg, ...prev].slice(0, 5));

  useEffect(() => {
    // Initialize Peer
    const peer = new Peer();
    peerRef.current = peer;

    peer.on('open', (id) => {
      setPeerId(id);
      addLog('Dispositivo listo para sincronizar.');
    });

    peer.on('connection', (conn) => {
      addLog(`Conexión entrante de: ${conn.peer.slice(0, 5)}...`);
      setupConnection(conn);
    });

    peer.on('error', (err) => {
      console.error(err);
      setStatus('error');
      addLog(`Error: ${err.type}`);
    });

    return () => {
      peer.destroy();
    };
  }, []);

  const setupConnection = (conn: DataConnection) => {
    connRef.current = conn;
    setStatus('connecting');

    conn.on('open', () => {
      setStatus('connected');
      addLog('¡Conexión establecida!');
      // Automatically send current data when connected
      sendData(conn);
    });

    conn.on('data', (data: any) => {
      if (data && data.type === 'SYNC_DATA') {
        addLog('Recibiendo datos de otro terminal...');
        syncData({ sales: data.sales, customers: data.customers });
        setLastSync(Date.now());
        addLog('Sincronización completada.');
      }
    });

    conn.on('close', () => {
      setStatus('idle');
      addLog('Conexión cerrada.');
    });
  };

  const connectToPeer = () => {
    if (!targetId || !peerRef.current) return;
    const conn = peerRef.current.connect(targetId);
    setupConnection(conn);
  };

  const sendData = (conn: DataConnection) => {
    conn.send({
      type: 'SYNC_DATA',
      sales,
      customers,
      timestamp: Date.now()
    });
    addLog('Enviando datos locales...');
  };

  return (
    <div className="h-full animate-fadeIn bg-sky-50 pb-24 flex flex-col overflow-hidden">
      <ModuleHeader title="Sincronización P2P" onBack={onBack} />

      <div className="flex-1 overflow-y-auto px-6 space-y-6 no-scrollbar pb-10">
        <RoundedCard className="bg-sky-900 text-white border-none shadow-xl relative overflow-hidden">
          <div className="relative z-10">
            <span className="text-[10px] font-black uppercase opacity-60 tracking-widest mb-2 block">ID de este Dispositivo</span>
            <div className="flex items-center justify-between gap-4">
              <h3 className="text-xl font-mono font-black break-all">{peerId || 'Generando...'}</h3>
              <button 
                onClick={() => navigator.clipboard.writeText(peerId)}
                className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center shrink-0"
              >
                <i className="fas fa-copy"></i>
              </button>
            </div>
            <p className="text-[9px] mt-4 opacity-50 italic">Comparte este ID con el otro repartidor o la planta para conectar.</p>
          </div>
          <i className="fas fa-tower-broadcast absolute -bottom-4 -right-4 text-8xl text-white/10"></i>
        </RoundedCard>

        <section className="space-y-4">
          <h4 className="text-[10px] font-black uppercase text-sky-400 ml-2 tracking-widest">Conectar a Terminal</h4>
          <div className="flex gap-2">
            <input 
              type="text" 
              placeholder="Pegar ID del otro dispositivo..." 
              className="flex-1 bg-white border-none rounded-[1.5rem] py-4 px-6 shadow-sm outline-none focus:ring-2 ring-sky-300 transition-all font-mono text-xs"
              value={targetId}
              onChange={(e) => setTargetId(e.target.value)}
            />
            <button 
              onClick={connectToPeer}
              className="w-14 h-14 bg-sky-600 text-white rounded-[1.5rem] flex items-center justify-center shadow-lg active:scale-95 transition-all"
            >
              <i className="fas fa-link"></i>
            </button>
          </div>
        </section>

        <section className="space-y-3">
          <h4 className="text-[10px] font-black uppercase text-sky-400 ml-2 tracking-widest">Estado del Motor</h4>
          <RoundedCard className="py-4">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-3">
                <div className={`w-3 h-3 rounded-full ${status === 'connected' ? 'bg-emerald-500 animate-pulse' : status === 'connecting' ? 'bg-amber-400 animate-bounce' : 'bg-slate-300'}`}></div>
                <span className="text-sm font-bold text-sky-900 uppercase tracking-tighter">
                  {status === 'idle' && 'Esperando conexión'}
                  {status === 'connecting' && 'Estableciendo puente...'}
                  {status === 'connected' && 'Terminales enlazadas'}
                  {status === 'error' && 'Error de red'}
                </span>
              </div>
              {lastSync && (
                <span className="text-[8px] font-black text-sky-300 uppercase">Sync: {new Date(lastSync).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
              )}
            </div>
          </RoundedCard>
        </section>

        <section className="space-y-2">
          <h4 className="text-[10px] font-black uppercase text-sky-400 ml-2 tracking-widest">Actividad Reciente</h4>
          <div className="bg-white/50 border border-white p-4 rounded-3xl space-y-2 min-h-[100px]">
            {logs.length === 0 ? (
              <p className="text-[10px] text-sky-300 text-center italic mt-4">Esperando actividad P2P...</p>
            ) : (
              logs.map((log, i) => (
                <div key={i} className="text-[9px] font-bold text-sky-600 flex items-start gap-2 animate-fadeIn">
                  <i className="fas fa-chevron-right mt-0.5 text-[7px] opacity-50"></i>
                  {log}
                </div>
              ))
            )}
          </div>
        </section>

        <RoundedCard className="bg-indigo-50 border-indigo-100">
          <div className="flex gap-4">
            <div className="w-12 h-12 bg-indigo-500 text-white rounded-2xl flex items-center justify-center shrink-0">
              <i className="fas fa-network-wired"></i>
            </div>
            <div>
              <h5 className="text-xs font-black text-indigo-900 uppercase">Sin Servidor Central</h5>
              <p className="text-[10px] text-indigo-700 leading-relaxed font-medium">Esta tecnología permite que las camionetas intercambien ventas directamente. No requiere internet una vez que las terminales se detectan.</p>
            </div>
          </div>
        </RoundedCard>
      </div>

      <div className="p-6 bg-white/80 backdrop-blur-xl border-t border-sky-100">
        <ActionButton onClick={onBack} variant="secondary">Cerrar Motor P2P</ActionButton>
      </div>
    </div>
  );
};

import React from 'react';
import { useNavigation } from './hooks/useNavigation';
