const LoginScreen: React.FC<{ onLogin: (emp: Employee) => void }> = ({ onLogin }) => {
  const { employees } = useERPData();
  const [pin, setPin] = useState('');
  const [error, setError] = useState(false);

  const handlePress = (num: string) => {
    if (pin.length < 4) {
      const newPin = pin + num;
      setPin(newPin);
      if (newPin.length === 4) {
        const emp = employees.find(e => e.pin === newPin);
        if (emp) {
          onLogin(emp);
        } else {
          setError(true);
          setTimeout(() => {
            setPin('');
            setError(false);
          }, 1000);
        }
      }
    }
  };

  return (
    <div className="fixed inset-0 bg-sky-50 flex flex-col items-center justify-center px-10 animate-fadeIn">
      <div className="mb-12 text-center">
        <div className="w-20 h-20 bg-white rounded-3xl flex items-center justify-center shadow-sm mx-auto mb-6">
          <i className="fas fa-lock text-sky-400 text-2xl"></i>
        </div>
        <h2 className="text-2xl font-black text-sky-900 mb-1">Acceso Seguro</h2>
        <p className="text-sky-400 text-xs font-bold uppercase tracking-widest">Ingresa tu PIN de 4 dígitos</p>
      </div>

      <div className="flex gap-4 mb-12">
        {[0, 1, 2, 3].map(i => (
          <div key={i} className={`w-4 h-4 rounded-full border-2 transition-all duration-300 ${error ? 'bg-red-500 border-red-500 animate-shake' : pin.length > i ? 'bg-sky-600 border-sky-600 scale-125' : 'bg-white border-sky-200'}`}></div>
        ))}
      </div>

      <div className="grid grid-cols-3 gap-6">
        {['1', '2', '3', '4', '5', '6', '7', '8', '9', 'C', '0', '⌫'].map(k => (
          <button 
            key={k} 
            onClick={() => {
              if (k === 'C') setPin('');
              else if (k === '⌫') setPin(pin.slice(0, -1));
              else handlePress(k);
            }}
            className={`w-16 h-16 rounded-2xl flex items-center justify-center text-xl font-black transition-all active:scale-90 ${k === 'C' || k === '⌫' ? 'bg-sky-100 text-sky-400' : 'bg-white text-sky-900 shadow-sm shadow-sky-100'}`}
          >
            {k}
          </button>
        ))}
      </div>
      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-5px); }
          75% { transform: translateX(5px); }
        }
        .animate-shake { animation: shake 0.2s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

const App: React.FC = () => {
  const { currentView, navigateTo, goBack } = useNavigation();
  const [showSplash, setShowSplash] = useState(true);
  const [user, setUser] = useState<Employee | null>(null);

  const handleLogout = () => {
    setUser(null);
    navigateTo('dashboard');
  };

  if (showSplash) return <SplashScreen onComplete={() => setShowSplash(false)} />;
  if (!user) return <LoginScreen onLogin={setUser} />;

  const renderContent = () => {
    // Permission Guard
    if (currentView !== 'dashboard' && !user.permissions.includes(currentView)) {
      return (
        <div className="h-full flex flex-col items-center justify-center p-10 text-center animate-fadeIn">
          <div className="w-20 h-20 bg-red-100 text-red-500 rounded-full flex items-center justify-center mb-6">
            <i className="fas fa-shield-halved text-3xl"></i>
          </div>
          <h2 className="text-xl font-black text-sky-900 mb-2">Acceso Denegado</h2>
          <p className="text-sky-400 text-sm font-bold mb-8 italic">No tienes permisos para acceder a este módulo. Contacta a tu administrador.</p>
          <button onClick={goBack} className="bg-sky-600 text-white px-8 py-4 rounded-3xl font-black uppercase text-xs shadow-lg shadow-sky-100">Regresar al Inicio</button>
        </div>
      );
    }

    switch (currentView) {
      case 'dashboard': return <Dashboard setView={navigateTo} user={user} onLogout={handleLogout} />;
      case 'pos': return <POSModule onBack={goBack} />;
      case 'customers': return <CustomersModule onBack={goBack} />;
      case 'production': return <ProductionModule onBack={goBack} />;
      case 'logistics': return <LogisticsModule onBack={goBack} />;
      case 'whatsapp': return <WhatsAppModule onBack={goBack} />;
      case 'employees': return <EmployeesModule onBack={goBack} currentUser={user} />;
      case 'reports': return <ReportsModule onBack={goBack} />;
      case 'settings': return <SettingsModule onBack={goBack} currentUser={user} />;
      case 'sync': return <SyncModule onBack={goBack} />;
      default: return <Dashboard setView={navigateTo} user={user} onLogout={handleLogout} />;
    }
  };

  return (
    <div className="max-w-md mx-auto min-h-screen bg-sky-50 relative overflow-x-hidden shadow-2xl">
      <main className="min-h-screen">
        {renderContent()}
      </main>
      {currentView === 'dashboard' && <VoiceAI onAction={(res) => res.action === 'SALE' && navigateTo('pos')} />}
    </div>
  );
};

export default App;

