export type ViewType = 'dashboard' | 'pos' | 'orders' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  balance: number; // Positive means debt
}

export interface Order {
  id: string;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  status: 'pendiente' | 'asignado' | 'entregado' | 'cancelado';
  vehicleId?: string;
  timestamp: number;
  priority: number;
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Crédito' | 'Multimodal';

export interface PaymentSplit {
  method: 'Efectivo' | 'Transferencia';
  amount: number;
}

export interface Sale {
  id: string;
  timestamp: number;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  paidAmount: number;
  change: number;
  paymentSplits: PaymentSplit[];
  emptyGarrafonsReturned: number;
  synced: boolean;
}

export type FilterStage = 'Multicama' | 'Carbon Activado' | 'Zeolita';
export type FilterProcess = 'Backwash' | 'Fast Rinse';

export interface ProductionStep {
  stage: FilterStage;
  process: FilterProcess;
  duration: number; // seconds
}

export interface Employee {
  id: string;
  name: string;
  role: 'Repartidor' | 'Planta' | 'Administrador';
  phone: string;
  pin: string;
  permissions: ViewType[];
}

export interface Vehicle {
  id: string;
  plate: string;
  description: string;
  loadCapacity: number;
  currentLoad: number;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function processVoiceCommand(command: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Procesa el siguiente comando de voz para una purificadora de agua y devuelve un JSON estructurado. 
      Comando: "${command}"`,
      config: {
        systemInstruction: "Eres un asistente de ERP. Interpreta intenciones de venta o consulta. Ejemplo: 'Vendí 3 garrafones a Juan' -> {action: 'SALE', quantity: 3, item: 'garrafon', customer: 'Juan'}",
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            action: { type: Type.STRING, description: "SALE, QUERY, or LOG" },
            quantity: { type: Type.NUMBER },
            item: { type: Type.STRING },
            customer: { type: Type.STRING },
            summary: { type: Type.STRING, description: "Resumen amigable de la acción" }
          },
          required: ["action", "summary"]
        }
      },
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    return { action: 'ERROR', summary: 'No pude entender el comando. Intenta de nuevo.' };
  }
}

export async function optimizeRoute(orders: any[]) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Optimiza esta lista de pedidos basándote en la eficiencia logística. 
      Pedidos: ${JSON.stringify(orders)}`,
      config: {
        systemInstruction: "Eres un despachador experto. Reordena los pedidos para minimizar el tiempo de viaje. Devuelve un JSON con el campo 'orderedIds' que sea un arreglo de los IDs en el orden óptimo.",
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
