const SplashScreen: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  useEffect(() => {
    const timer = setTimeout(onComplete, 2500);
    return () => clearTimeout(timer);
  }, [onComplete]);

  return (
    <div className="fixed inset-0 bg-sky-600 flex flex-col items-center justify-center z-[100] animate-fadeIn">
      <div className="w-24 h-24 bg-white rounded-[2rem] flex items-center justify-center shadow-2xl animate-bounce mb-6">
        <i className="fas fa-droplet text-sky-500 text-5xl"></i>
      </div>
      <h1 className="text-white text-3xl font-black tracking-tighter mb-2">Aqua+ Fundadores</h1>
      <p className="text-sky-200 text-xs font-bold uppercase tracking-[0.3em] opacity-80">ERP Pro Mobile</p>
      <div className="absolute bottom-16 w-48 h-1.5 bg-sky-800 rounded-full overflow-hidden">
        <div className="h-full bg-white w-full animate-[progress_2s_ease-in-out]"></div>
      </div>
      <style>{`
        @keyframes progress {
          0% { width: 0%; }
          100% { width: 100%; }
        }
      `}</style>
    </div>
  );
};

const LoginScreen: React.FC<{ onLogin: (emp: Employee) => void }> = ({ onLogin }) => {
  const { employees } = useERPData();
  const [pin, setPin] = useState('');
  const [error, setError] = useState(false);

  const handlePress = (num: string) => {
    if (pin.length < 4) {
      const newPin = pin + num;
      setPin(newPin);
      if (newPin.length === 4) {
        const emp = employees.find(e => e.pin === newPin);
        if (emp) {
          onLogin(emp);
        } else {
          setError(true);
          setTimeout(() => {
            setPin('');
            setError(false);
          }, 1000);
        }
      }
    }
  };

  return (
    <div className="fixed inset-0 bg-sky-50 flex flex-col items-center justify-center px-10 animate-fadeIn">
      <div className="mb-12 text-center">
        <div className="w-20 h-20 bg-white rounded-3xl flex items-center justify-center shadow-sm mx-auto mb-6">
          <i className="fas fa-lock text-sky-400 text-2xl"></i>
        </div>
        <h2 className="text-2xl font-black text-sky-900 mb-1">Acceso Seguro</h2>
        <p className="text-sky-400 text-xs font-bold uppercase tracking-widest">Ingresa tu PIN de 4 dígitos</p>
      </div>

      <div className="flex gap-4 mb-12">
        {[0, 1, 2, 3].map(i => (
          <div key={i} className={`w-4 h-4 rounded-full border-2 transition-all duration-300 ${error ? 'bg-red-500 border-red-500 animate-shake' : pin.length > i ? 'bg-sky-600 border-sky-600 scale-125' : 'bg-white border-sky-200'}`}></div>
        ))}
      </div>

      <div className="grid grid-cols-3 gap-6">
        {['1', '2', '3', '4', '5', '6', '7', '8', '9', 'C', '0', '⌫'].map(k => (
          <button 
            key={k} 
            onClick={() => {
              if (k === 'C') setPin('');
              else if (k === '⌫') setPin(pin.slice(0, -1));
              else handlePress(k);
            }}
            className={`w-16 h-16 rounded-2xl flex items-center justify-center text-xl font-black transition-all active:scale-90 ${k === 'C' || k === '⌫' ? 'bg-sky-100 text-sky-400' : 'bg-white text-sky-900 shadow-sm shadow-sky-100'}`}
          >
            {k}
          </button>
        ))}
      </div>
      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-5px); }
          75% { transform: translateX(5px); }
        }
        .animate-shake { animation: shake 0.2s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

const App: React.FC = () => {
  const { currentView, navigateTo, goBack } = useNavigation();
  const [showSplash, setShowSplash] = useState(true);
  const [user, setUser] = useState<Employee | null>(null);

  const handleLogout = () => {
    setUser(null);
    navigateTo('dashboard');
  };

  if (showSplash) return <SplashScreen onComplete={() => setShowSplash(false)} />;
  if (!user) return <LoginScreen onLogin={setUser} />;

  const renderContent = () => {
    // Permission Guard
    if (currentView !== 'dashboard' && !user.permissions.includes(currentView)) {
      return (
        <div className="h-full flex flex-col items-center justify-center p-10 text-center animate-fadeIn">
          <div className="w-20 h-20 bg-red-100 text-red-500 rounded-full flex items-center justify-center mb-6">
            <i className="fas fa-shield-halved text-3xl"></i>
          </div>
          <h2 className="text-xl font-black text-sky-900 mb-2">Acceso Denegado</h2>
          <p className="text-sky-400 text-sm font-bold mb-8 italic">No tienes permisos para acceder a este módulo. Contacta a tu administrador.</p>
          <button onClick={goBack} className="bg-sky-600 text-white px-8 py-4 rounded-3xl font-black uppercase text-xs shadow-lg shadow-sky-100">Regresar al Inicio</button>
        </div>
      );
    }

    switch (currentView) {
      case 'dashboard': return <Dashboard setView={navigateTo} user={user} onLogout={handleLogout} />;
      case 'pos': return <POSModule onBack={goBack} />;
      case 'orders': return <OrdersModule onBack={goBack} />;
      case 'customers': return <CustomersModule onBack={goBack} />;
      case 'production': return <ProductionModule onBack={goBack} />;
      case 'logistics': return <LogisticsModule onBack={goBack} />;
      case 'whatsapp': return <WhatsAppModule onBack={goBack} />;
      case 'employees': return <EmployeesModule onBack={goBack} currentUser={user} />;
      case 'reports': return <ReportsModule onBack={goBack} />;
      case 'settings': return <SettingsModule onBack={goBack} currentUser={user} />;
      case 'sync': return <SyncModule onBack={goBack} />;
      default: return <Dashboard setView={navigateTo} user={user} onLogout={handleLogout} />;
    }
  };

  return (
    <div className="max-w-md mx-auto min-h-screen bg-sky-50 relative overflow-x-hidden shadow-2xl">
      <main className="min-h-screen">
        {renderContent()}
      </main>
      {currentView === 'dashboard' && <VoiceAI onAction={(res) => res.action === 'SALE' && navigateTo('pos')} />}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Vehicle } from '../types';

export const LogisticsModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { vehicles, setVehicles } = useERPData();
  const [editingVehicle, setEditingVehicle] = useState<Partial<Vehicle> | null>(null);

  const updateLoad = (id: string, delta: number) => {
    setVehicles(prev => prev.map(v => v.id === id ? { ...v, currentLoad: Math.max(0, Math.min(v.loadCapacity, v.currentLoad + delta)) } : v));
  };

  const saveVehicle = () => {
    if (!editingVehicle?.plate || !editingVehicle?.description) return alert("Completa los datos.");
    setVehicles(prev => {
      const exists = prev.find(v => v.id === editingVehicle.id);
      if (exists) return prev.map(v => v.id === editingVehicle.id ? editingVehicle as Vehicle : v);
      return [...prev, { ...editingVehicle, id: Date.now().toString(), currentLoad: 0 } as Vehicle];
    });
    setEditingVehicle(null);
  };

  if (editingVehicle) {
    return (
      <div className="h-full bg-sky-50 animate-fadeIn">
        <ModuleHeader title={editingVehicle.id ? "Editar Vehículo" : "Nueva Unidad"} onBack={() => setEditingVehicle(null)} />
        <div className="px-6 space-y-5">
           <input className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-bold" placeholder="Placa" value={editingVehicle.plate || ''} onChange={e => setEditingVehicle({...editingVehicle, plate: e.target.value})}/>
           <input className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-bold" placeholder="Descripción (Ej: Nissan Blanca)" value={editingVehicle.description || ''} onChange={e => setEditingVehicle({...editingVehicle, description: e.target.value})}/>
           <div className="space-y-1">
              <label className="text-[10px] font-black text-sky-400 uppercase ml-4">Capacidad de Garrafones</label>
              <input type="number" className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-black text-sky-600 text-xl" value={editingVehicle.loadCapacity || ''} onChange={e => setEditingVehicle({...editingVehicle, loadCapacity: Number(e.target.value)})}/>
           </div>
           <ActionButton onClick={saveVehicle}>Guardar Unidad</ActionButton>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24">
      <ModuleHeader title="Gestión de Flota" onBack={onBack} />
      <div className="px-6 space-y-6">
        {vehicles.map(v => (
          <RoundedCard key={v.id} className="relative overflow-hidden border-none shadow-xl bg-white group active:scale-[0.98] transition-all">
             <div className="flex justify-between items-start mb-6">
               <div className="flex gap-4">
                 <div className="w-14 h-14 bg-sky-900 text-white rounded-[1.5rem] flex items-center justify-center text-xl shadow-lg shadow-sky-100">
                    <i className="fas fa-truck-pickup"></i>
                 </div>
                 <div>
                   <span className="text-[10px] font-black text-sky-400 uppercase tracking-widest leading-none block mb-1">{v.plate}</span>
                   <h3 className="text-xl font-black text-sky-900 leading-tight">{v.description}</h3>
                 </div>
               </div>
               <button onClick={() => setEditingVehicle(v)} className="w-10 h-10 bg-sky-50 text-sky-400 rounded-full flex items-center justify-center hover:bg-sky-100 transition-colors"><i className="fas fa-edit"></i></button>
             </div>

             <div className="flex items-end justify-between mb-4">
               <div>
                 <p className="text-[10px] font-black text-sky-400 uppercase tracking-tighter mb-1">Carga Actual</p>
                 <p className="text-4xl font-black text-sky-600 tracking-tighter">{v.currentLoad} <span className="text-xs font-bold text-sky-300 ml-1">UNIDADES</span></p>
               </div>
               <div className="flex gap-3">
                 <button onClick={() => updateLoad(v.id, -1)} className="w-14 h-14 bg-sky-50 rounded-2xl flex items-center justify-center text-sky-600 font-black text-2xl shadow-sm active:bg-sky-100 transition-all">-</button>
                 <button onClick={() => updateLoad(v.id, 1)} className="w-14 h-14 bg-sky-600 rounded-2xl flex items-center justify-center text-white font-black text-2xl shadow-lg shadow-sky-100 active:scale-90 transition-all">+</button>
               </div>
             </div>

             <div className="w-full bg-sky-50 h-3 rounded-full overflow-hidden border border-sky-100">
               <div className="h-full bg-gradient-to-r from-sky-400 to-sky-600 transition-all duration-700 ease-out" style={{ width: `${(v.currentLoad/v.loadCapacity)*100}%` }}></div>
             </div>
             <div className="flex justify-between mt-2">
                <span className="text-[9px] font-black text-sky-300 uppercase">Límite: {v.loadCapacity}</span>
                <span className="text-[9px] font-black text-sky-500 uppercase">{Math.round((v.currentLoad/v.loadCapacity)*100)}% Capacidad</span>
             </div>
          </RoundedCard>
        ))}

        <button 
          onClick={() => setEditingVehicle({})}
          className="w-full py-7 border-2 border-dashed border-sky-200 rounded-[2.5rem] text-sky-400 font-black text-sm uppercase hover:bg-white hover:text-sky-600 transition-all group"
        >
          <i className="fas fa-plus mr-2 group-hover:scale-125 transition-transform"></i> Registrar Nueva Unidad
        </button>
      </div>
    </div>
  );
};

export type ViewType = 'dashboard' | 'pos' | 'orders' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings' | 'quality' | 'scanner';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  balance: number; // Positive means debt
}

export interface Order {
  id: string;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  status: 'pendiente' | 'asignado' | 'entregado' | 'cancelado';
