export const ScannerModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [scanning, setScanning] = useState(true);
  const [result, setResult] = useState<any>(null);

  const decryptData = (encrypted: string) => {
    try {
      const decoded = atob(encrypted);
      if (decoded.startsWith('AQUA-PRO-SECURE|')) {
        return JSON.parse(decoded.split('|')[1]);
      }
      return null;
    } catch {
      return null;
    }
  };

  const handleManualEntry = (code: string) => {
    const data = decryptData(code);
    if (data) {
      setResult(data);
      setScanning(false);
    } else {
      alert("Código inválido o malformado.");
    }
  };

  return (
    <div className="h-full bg-sky-900 flex flex-col animate-fadeIn overflow-hidden">
      <div className="px-6 pt-8 pb-4 flex items-center gap-4">
        <button onClick={onBack} className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center text-white active:scale-90 transition-transform">
          <i className="fas fa-arrow-left"></i>
        </button>
        <h2 className="text-2xl font-black text-white tracking-tight">Validación QR</h2>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center px-10">
        {scanning ? (
          <div className="w-full space-y-8 flex flex-col items-center">
            <div className="w-64 h-64 border-4 border-sky-400 rounded-[3rem] relative overflow-hidden flex items-center justify-center bg-black/20">
              <div className="absolute top-0 left-0 right-0 h-1 bg-sky-400 shadow-[0_0_15px_rgba(56,189,248,0.8)] animate-scanner"></div>
              <i className="fas fa-qrcode text-6xl text-white/20"></i>
            </div>
            <style>{`
              @keyframes scanner {
                0% { transform: translateY(0); }
                100% { transform: translateY(256px); }
              }
              .animate-scanner { animation: scanner 2s linear infinite alternate; }
            `}</style>

            <div className="text-center">
              <h3 className="text-white font-black text-xl mb-2">Escaneando Ticket</h3>
              <p className="text-sky-300 text-xs font-medium px-4">Apunta la cámara al código QR impreso en el ticket del cliente.</p>
            </div>

            <div className="w-full">
              <input 
                type="text" 
                placeholder="O ingresa código manual..." 
                className="w-full bg-white/10 border border-white/20 rounded-2xl p-4 text-white text-xs outline-none focus:ring-2 ring-sky-400"
                onKeyDown={e => e.key === 'Enter' && handleManualEntry(e.currentTarget.value)}
              />
            </div>
          </div>
        ) : (
          <RoundedCard className="w-full bg-white animate-fadeIn p-8">
            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 bg-emerald-100 text-emerald-500 rounded-full flex items-center justify-center mb-6">
                <i className="fas fa-check-circle text-4xl"></i>
              </div>
              <h3 className="text-2xl font-black text-sky-900 mb-2">Ticket Válido</h3>
              <div className="w-full bg-sky-50 rounded-3xl p-6 mb-8 space-y-4">
                <div className="flex justify-between">
                  <span className="text-[10px] font-black text-sky-400 uppercase">Ticket ID</span>
                  <span className="text-xs font-black text-sky-900">{result.id}</span>
                </div>
                <div className="flex justify-between border-t border-sky-100 pt-3">
                  <span className="text-[10px] font-black text-sky-400 uppercase">Monto</span>
                  <span className="text-xl font-black text-sky-900">${result.total}</span>
                </div>
                <div className="flex justify-between border-t border-sky-100 pt-3">
                  <span className="text-[10px] font-black text-sky-400 uppercase">Fecha</span>
                  <span className="text-xs font-bold text-sky-600">{new Date(result.date).toLocaleDateString()}</span>
                </div>
              </div>
              <button 
                onClick={() => setScanning(true)} 
                className="w-full bg-sky-600 text-white py-5 rounded-[2rem] font-black uppercase text-xs tracking-widest shadow-xl shadow-sky-100"
              >
                Escanear Otro
              </button>
            </div>
          </RoundedCard>
        )}
      </div>

      <div className="p-10 text-center opacity-40">
        <p className="text-[10px] text-white font-black uppercase tracking-[0.3em]">Sistema de Seguridad Aqua+</p>
      </div>
    </div>
  );
};

