                             <span className="text-[8px] font-bold text-sky-300">{a.date}</span>
                          </div>
                          <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-full ${a.status === 'presente' ? 'bg-emerald-100 text-emerald-600' : a.status === 'retardo' ? 'bg-amber-100 text-amber-600' : 'bg-red-100 text-red-600'}`}>
                             {a.status}
                          </span>
                       </div>
                     ))}
                   </div>
                 )}
              </div>
            </section>
          </div>
        )}
      </div>

      {/* Assignment Modal */}
      {assigningTo && (
        <div className="fixed inset-0 bg-sky-900/60 backdrop-blur-md z-[100] flex items-end">
           <div className="w-full bg-white rounded-t-[2.5rem] p-8 animate-fadeIn max-h-[90vh] overflow-y-auto no-scrollbar">
              <div className="flex justify-between items-center mb-8">
                 <div>
                    <h3 className="text-xl font-black text-sky-900">Asignar Tarea</h3>
                    <p className="text-[10px] font-bold text-sky-400 uppercase tracking-widest">Para: {assigningTo.name}</p>
                 </div>
                 <button onClick={() => setAssigningTo(null)} className="w-12 h-12 bg-sky-50 text-sky-400 rounded-full flex items-center justify-center active:scale-90 transition-all"><i className="fas fa-times"></i></button>
              </div>

              <div className="grid grid-cols-2 gap-3 mb-8">
                 {TASK_PRESETS.map(preset => (
                   <button 
                    key={preset.title} 
                    onClick={() => handleAddTask(preset)}
                    className="bg-sky-50 p-5 rounded-[2rem] text-left border border-white hover:border-sky-300 active:scale-95 transition-all group"
                   >
                     <i className={`fas ${preset.icon} text-sky-600 mb-3 text-lg group-hover:rotate-12 transition-transform`}></i>
                     <h5 className="text-[10px] font-black text-sky-900 uppercase leading-none mb-1">{preset.title}</h5>
                     <p className="text-[8px] font-bold text-sky-400 leading-tight">{preset.desc}</p>
                   </button>
                 ))}
              </div>

              <div className="space-y-4 pt-6 border-t border-sky-50">
                 <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest">Tarea Personalizada</h4>
                 <input 
                  type="text" 
                  className="w-full bg-sky-50 border-none rounded-2xl p-5 text-sky-900 font-bold outline-none focus:ring-2 ring-sky-300" 
                  placeholder="Título de la tarea..." 
                  value={customTaskTitle}
                  onChange={e => setCustomTaskTitle(e.target.value)}
                 />
                 <ActionButton onClick={() => handleAddTask({ title: customTaskTitle, desc: 'Tarea personalizada asignada por administrador' })} disabled={!customTaskTitle}>Asignar Personalizada</ActionButton>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export type ViewType = 'dashboard' | 'pos' | 'orders' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings' | 'quality' | 'scanner' | 'inventory';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
  category?: 'Agua' | 'Insumos' | 'Accesorios';
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  balance: number; // Positive means debt
}

export interface Order {
  id: string;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  status: 'pendiente' | 'asignado' | 'entregado' | 'cancelado';
  vehicleId?: string;
  timestamp: number;
  priority: number;
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Crédito' | 'Multimodal';

export interface PaymentSplit {
  method: 'Efectivo' | 'Transferencia';
  amount: number;
}

export interface Sale {
  id: string;
  timestamp: number;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  paidAmount: number;
  change: number;
  paymentSplits: PaymentSplit[];
  emptyGarrafonsReturned: number;
  synced: boolean;
}

export interface QualityRecord {
  id: string;
  timestamp: number;
  type: 'Cruda' | 'Producto';
  ph: number;
  cloro: number;
  tds: number;
  dureza: number;
  color: string;
  sabor: string;
  turbiedad: string;
  employeeId: string;
}

export interface Task {
  id: string;
  employeeId: string;
  title: string;
  description?: string;
  status: 'pendiente' | 'completada';
  timestamp: number;
  date: string; // YYYY-MM-DD
}

export interface Attendance {
  id: string;
  employeeId: string;
  timestamp: number;
  date: string; // YYYY-MM-DD
  status: 'presente' | 'falta' | 'retardo';
}

export type FilterStage = 'Multicama' | 'Carbon Activado' | 'Zeolita';
export type FilterProcess = 'Backwash' | 'Fast Rinse';

export interface ProductionStep {
  stage: FilterStage;
  process: FilterProcess;
  duration: number; // seconds
}

export interface Employee {
  id: string;
  name: string;
  role: 'Repartidor' | 'Planta' | 'Administrador';
  phone: string;
  pin: string;
  permissions: ViewType[];
}

export interface Vehicle {
  id: string;
  plate: string;
  description: string;
  loadCapacity: number;
  currentLoad: number;
}

import { useState, useEffect, useCallback } from 'react';
import { Product, Customer, Sale, CartItem, Order, Employee, Vehicle, PaymentSplit, ViewType, QualityRecord, Task, Attendance } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS } from '../constants';

const DEFAULT_PERMISSIONS: ViewType[] = ['dashboard', 'pos', 'orders', 'customers', 'logistics', 'inventory', 'whatsapp', 'production', 'sync', 'reports', 'settings', 'employees', 'quality', 'scanner'];

export const useERPData = () => {
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('aqua_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [qualityRecords, setQualityRecords] = useState<QualityRecord[]>(() => {
    const saved = localStorage.getItem('aqua_quality');
    return saved ? JSON.parse(saved) : [];
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('aqua_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('aqua_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    return saved ? JSON.parse(saved) : [
      { 
        id: 'admin', 
        name: 'Gerente General', 
        role: 'Administrador', 
        phone: '3312345678', 
        pin: '1234', 
        permissions: [...DEFAULT_PERMISSIONS] 
      },
      { 
        id: 'e1', 
        name: 'Oscar El Rayo', 
        role: 'Repartidor', 
        phone: '3311223344', 
        pin: '1111', 
        permissions: ['dashboard', 'pos', 'orders', 'customers', 'logistics', 'sync', 'scanner', 'employees'] 
      },
      { 
        id: 'e2', 
        name: 'Ana Gomez', 
        role: 'Planta', 
        phone: '3355667788', 
        pin: '2222', 
        permissions: ['dashboard', 'production', 'reports', 'quality', 'employees', 'inventory'] 
      }
    ];
  });

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    return saved ? JSON.parse(saved) : [
      { id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0 }
    ];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_orders', JSON.stringify(orders));
    localStorage.setItem('aqua_quality', JSON.stringify(qualityRecords));
    localStorage.setItem('aqua_tasks', JSON.stringify(tasks));
    localStorage.setItem('aqua_attendance', JSON.stringify(attendance));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
  }, [products, customers, sales, orders, qualityRecords, tasks, attendance, employees, vehicles]);

  const saveProduct = (product: Product) => {
    setProducts(prev => {
      const exists = prev.find(p => p.id === product.id);
      if (exists) return prev.map(p => p.id === product.id ? product : p);
      return [...prev, product];
    });
  };

  const deleteProduct = (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const loadVehicle = (vehicleId: string, delta: number) => {
    // We assume the main product for fleet load is the 20L Garrafón (ID: 1)
    const productId = '1'; 
    const product = products.find(p => p.id === productId);
    const vehicle = vehicles.find(v => v.id === vehicleId);

    if (!product || !vehicle) return;

    // Check if we are adding load (delta > 0) and if we have enough stock
    if (delta > 0 && product.stock < delta) {
      alert("No hay suficiente stock en planta para cargar este vehículo.");
      return;
    }

    // Check if we are removing load (delta < 0) and if vehicle has enough load to remove
    if (delta < 0 && vehicle.currentLoad < Math.abs(delta)) {
      return;
    }

    // Update vehicle load
    setVehicles(prev => prev.map(v => 
      v.id === vehicleId 
        ? { ...v, currentLoad: Math.max(0, Math.min(v.loadCapacity, v.currentLoad + delta)) } 
        : v
    ));

    // Discount from central stock
    setProducts(prev => prev.map(p => 
      p.id === productId 
        ? { ...p, stock: p.stock - delta } 
        : p
    ));
  };

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number
  ) => {
    const debtAmount = Math.max(0, total - paidAmount);
    const newSale: Sale = {
      id: `TKT-${Date.now().toString().slice(-6)}`,
      timestamp: Date.now(),
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change: Math.max(0, paidAmount - total),
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false
    };

    setSales(prev => [newSale, ...prev]);
    setCustomers(prev => prev.map(c => c.id === customerId ? { ...c, balance: (c.balance || 0) + debtAmount } : c));
    setProducts(prev => prev.map(p => {
      const cartItem = items.find(item => item.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    return newSale;
  };

  const addOrder = (order: Omit<Order, 'id' | 'timestamp'>) => {
    const newOrder: Order = {
      ...order,
      id: `ORD-${Date.now().toString().slice(-6)}`,
      timestamp: Date.now(),
    };
    setOrders(prev => [...prev, newOrder]);
    return newOrder;
  };

  const updateOrder = (updated: Order) => {
    setOrders(prev => prev.map(o => o.id === updated.id ? updated : o));
  };

  const addQualityRecord = (record: Omit<QualityRecord, 'id' | 'timestamp'>) => {
    const newRecord: QualityRecord = {
      ...record,
      id: `LOG-${Date.now().toString().slice(-6)}`,
      timestamp: Date.now(),
    };
    setQualityRecords(prev => [newRecord, ...prev]);
  };

  const saveEmployee = (emp: Employee) => {
    setEmployees(prev => {
      const exists = prev.find(e => e.id === emp.id);
      if (exists) return prev.map(e => e.id === emp.id ? emp : e);
      return [...prev, emp];
    });
  };

  const addTask = (task: Omit<Task, 'id' | 'timestamp' | 'status'>) => {
    const newTask: Task = {
      ...task,
      id: `TSK-${Date.now().toString().slice(-6)}`,
      timestamp: Date.now(),
      status: 'pendiente'
    };
    setTasks(prev => [newTask, ...prev]);
  };

  const updateTaskStatus = (id: string, status: 'pendiente' | 'completada') => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status } : t));
  };

  const recordAttendance = (employeeId: string, status: Attendance['status']) => {
    const today = new Date().toISOString().split('T')[0];
    const existing = attendance.find(a => a.employeeId === employeeId && a.date === today);

    if (existing) {
      setAttendance(prev => prev.map(a => a.id === existing.id ? { ...a, status, timestamp: Date.now() } : a));
    } else {
      const newAtt: Attendance = {
        id: `ATT-${Date.now().toString().slice(-6)}`,
        employeeId,
        timestamp: Date.now(),
        date: today,
        status
      };
      setAttendance(prev => [...prev, newAtt]);
    }
  };

  const syncData = useCallback((externalData: { sales: Sale[], customers: Customer[] }) => {
    setSales(prev => {
      const existingIds = new Set(prev.map(s => s.id));
      const newSales = externalData.sales.filter(s => !existingIds.has(s.id));
      return [...newSales, ...prev].sort((a, b) => b.timestamp - a.timestamp);
    });
    setCustomers(prev => {
      const customerMap = new Map(prev.map(c => [c.id, c]));
      externalData.customers.forEach(ec => customerMap.set(ec.id, ec));
      return Array.from(customerMap.values());
    });
    return true;
  }, []);

  return { 
    products, saveProduct, deleteProduct,
    customers, saveCustomer: (c: Customer) => setCustomers(prev => prev.find(x => x.id === c.id) ? prev.map(x => x.id === c.id ? c : x) : [...prev, c]),
    deleteCustomer: (id: string) => setCustomers(prev => prev.filter(c => c.id !== id)),
    sales, addSale,
    orders, addOrder, updateOrder, setOrders,
    qualityRecords, addQualityRecord,
    tasks, addTask, updateTaskStatus,
    attendance, recordAttendance,
    employees, saveEmployee,
    vehicles, setVehicles, loadVehicle,
    syncData
  };
};

import React from 'react';
import { ViewType, Employee } from '../types';
import { useERPData } from '../hooks/useERPData';
