import React, { useState } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Product } from '../types';

export const InventoryModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { products, saveProduct, deleteProduct } = useERPData();
  const [editingProduct, setEditingProduct] = useState<Partial<Product> | null>(null);
  const [search, setSearch] = useState('');

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(search.toLowerCase())
  );

  const totalValue = products.reduce((acc, p) => acc + (p.stock * p.price), 0);

  const handleSave = () => {
    if (!editingProduct?.name || editingProduct.price === undefined || editingProduct.stock === undefined) {
      alert("Por favor completa todos los campos.");
      return;
    }
    const productToSave: Product = {
      id: editingProduct.id || Date.now().toString(),
      name: editingProduct.name,
      price: editingProduct.price,
      stock: editingProduct.stock,
      category: editingProduct.category || 'Agua'
    };
    saveProduct(productToSave);
    setEditingProduct(null);
  };

  if (editingProduct) {
    return (
      <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-32">
        <ModuleHeader title={editingProduct.id ? "Editar Producto" : "Nuevo Producto"} onBack={() => setEditingProduct(null)} />
        <div className="px-6 space-y-6 animate-fadeIn">
          <div className="space-y-4">
            <div>
              <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Nombre del Producto</label>
              <input 
                className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-bold text-sky-900 focus:ring-2 ring-violet-300 transition-all" 
                placeholder="Ej: Garrafón 20L (Llenado)" 
                value={editingProduct.name || ''} 
                onChange={e => setEditingProduct({...editingProduct, name: e.target.value})}
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Precio al Público</label>
                <div className="relative">
                   <span className="absolute left-5 top-1/2 -translate-y-1/2 font-black text-sky-400">$</span>
                   <input 
                    type="number"
                    className="w-full bg-white p-5 pl-10 rounded-[2rem] outline-none shadow-sm font-black text-sky-900 text-xl focus:ring-2 ring-violet-300 transition-all" 
                    placeholder="0.00" 
                    value={editingProduct.price || ''} 
                    onChange={e => setEditingProduct({...editingProduct, price: Number(e.target.value)})}
                  />
                </div>
              </div>
              <div>
                <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Stock Actual</label>
                <input 
                  type="number"
                  className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-black text-sky-900 text-xl focus:ring-2 ring-violet-300 transition-all" 
                  placeholder="0" 
                  value={editingProduct.stock === undefined ? '' : editingProduct.stock} 
                  onChange={e => setEditingProduct({...editingProduct, stock: Number(e.target.value)})}
                />
              </div>
            </div>

            <div>
              <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Categoría</label>
              <select 
                className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-bold text-sky-900 appearance-none focus:ring-2 ring-violet-300 transition-all"
                value={editingProduct.category || 'Agua'}
                onChange={e => setEditingProduct({...editingProduct, category: e.target.value as any})}
              >
                <option value="Agua">Agua Purificada</option>
                <option value="Insumos">Insumos (Tapas, Sellos)</option>
                <option value="Accesorios">Accesorios (Dispensadores)</option>
              </select>
            </div>
          </div>

          <div className="pt-4 space-y-3">
             <ActionButton onClick={handleSave}>Guardar en Inventario</ActionButton>
             {editingProduct.id && (
               <button 
                onClick={() => { if(confirm("¿Eliminar producto?")) { deleteProduct(editingProduct.id!); setEditingProduct(null); } }}
                className="w-full py-4 text-rose-500 font-black uppercase text-[10px] tracking-widest"
               >
                 Eliminar Producto definitivamente
               </button>
             )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 flex flex-col animate-fadeIn overflow-hidden pb-24">
      <ModuleHeader title="Gestión de Inventario" onBack={onBack} />

      <div className="px-6 space-y-4 shrink-0 mb-4">
        <RoundedCard className="bg-violet-600 text-white border-none shadow-xl flex items-center justify-between p-6">
           <div>
              <p className="text-[9px] font-black uppercase tracking-[0.2em] opacity-70 mb-1">Valor Total Almacén</p>
              <p className="text-3xl font-black tracking-tighter">${totalValue.toLocaleString()}</p>
           </div>
           <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center text-2xl">
              <i className="fas fa-warehouse"></i>
           </div>
        </RoundedCard>

        <div className="relative">
          <input 
            type="text" 
            placeholder="Buscar producto..." 
            className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm focus:ring-2 ring-violet-300 font-medium" 
            value={search} 
            onChange={e => setSearch(e.target.value)}
          />
          <i className="fas fa-magnifying-glass absolute right-6 top-1/2 -translate-y-1/2 text-sky-200"></i>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-3 no-scrollbar pb-10">
        {filteredProducts.map(p => (
          <RoundedCard key={p.id} className="p-4 border-none shadow-sm group hover:shadow-md transition-all active:scale-[0.98]" onClick={() => setEditingProduct(p)}>
            <div className="flex justify-between items-center">
               <div className="flex items-center gap-4">
                  <div className={`w-12 h-12 ${p.stock < 15 ? 'bg-rose-100 text-rose-500' : 'bg-sky-50 text-sky-500'} rounded-2xl flex items-center justify-center text-lg`}>
                     <i className={`fas ${p.category === 'Agua' ? 'fa-droplet' : p.category === 'Insumos' ? 'fa-tags' : 'fa-pump-medical'}`}></i>
                  </div>
                  <div>
                     <h4 className="font-black text-sky-900 text-sm leading-tight">{p.name}</h4>
                     <span className="text-[9px] font-bold text-sky-400 uppercase tracking-widest">{p.category || 'Agua'}</span>
                  </div>
               </div>
               <div className="text-right">
                  <span className={`text-xl font-black block leading-none ${p.stock < 15 ? 'text-rose-500' : 'text-sky-900'}`}>{p.stock}</span>
                  <span className="text-[8px] font-black text-sky-300 uppercase">Existencia</span>
               </div>
            </div>
            <div className="mt-4 pt-3 border-t border-sky-50 flex justify-between items-center">
               <span className="text-[10px] font-black text-sky-400 uppercase tracking-widest">Precio: <span className="text-sky-900">${p.price}</span></span>
               <div className="flex items-center gap-1">
                 <div className={`w-1.5 h-1.5 rounded-full ${p.stock < 15 ? 'bg-rose-500 animate-pulse' : 'bg-emerald-500'}`}></div>
                 <span className={`text-[8px] font-black uppercase ${p.stock < 15 ? 'text-rose-500' : 'text-emerald-500'}`}>
                    {p.stock < 15 ? 'Stock Crítico' : 'Stock Saludable'}
                 </span>
               </div>
            </div>
          </RoundedCard>
        ))}

        <button 
          onClick={() => setEditingProduct({ category: 'Agua', stock: 0, price: 0 })}
          className="w-full py-6 border-2 border-dashed border-violet-200 rounded-[2.5rem] text-violet-400 font-black text-sm uppercase hover:bg-white transition-all"
        >
          + Agregar Nuevo Producto
        </button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';
import { Vehicle } from '../types';

export const LogisticsModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { vehicles, setVehicles, loadVehicle } = useERPData();
  const [editingVehicle, setEditingVehicle] = useState<Partial<Vehicle> | null>(null);

  const saveVehicle = () => {
    if (!editingVehicle?.plate || !editingVehicle?.description) return alert("Completa los datos.");
    setVehicles(prev => {
      const exists = prev.find(v => v.id === editingVehicle.id);
      if (exists) return prev.map(v => v.id === editingVehicle.id ? editingVehicle as Vehicle : v);
      return [...prev, { ...editingVehicle, id: Date.now().toString(), currentLoad: 0 } as Vehicle];
    });
    setEditingVehicle(null);
  };

  if (editingVehicle) {
    return (
      <div className="h-full bg-sky-50 animate-fadeIn">
        <ModuleHeader title={editingVehicle.id ? "Editar Vehículo" : "Nueva Unidad"} onBack={() => setEditingVehicle(null)} />
        <div className="px-6 space-y-5">
           <input className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-bold" placeholder="Placa" value={editingVehicle.plate || ''} onChange={e => setEditingVehicle({...editingVehicle, plate: e.target.value})}/>
           <input className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-bold" placeholder="Descripción (Ej: Nissan Blanca)" value={editingVehicle.description || ''} onChange={e => setEditingVehicle({...editingVehicle, description: e.target.value})}/>
           <div className="space-y-1">
              <label className="text-[10px] font-black text-sky-400 uppercase ml-4">Capacidad de Garrafones</label>
              <input type="number" className="w-full bg-white p-5 rounded-[2rem] shadow-sm outline-none font-black text-sky-600 text-xl" value={editingVehicle.loadCapacity || ''} onChange={e => setEditingVehicle({...editingVehicle, loadCapacity: Number(e.target.value)})}/>
           </div>
           <ActionButton onClick={saveVehicle}>Guardar Unidad</ActionButton>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24">
      <ModuleHeader title="Gestión de Flota" onBack={onBack} />
      <div className="px-6 space-y-6">
        <RoundedCard className="bg-sky-100/50 border-sky-200">
           <div className="flex items-start gap-4">
              <i className="fas fa-info-circle text-sky-500 mt-1"></i>
              <p className="text-[10px] font-bold text-sky-700 leading-tight">
                Nota: Al aumentar la carga de un vehículo, el stock se descontará automáticamente del inventario central de planta.
              </p>
           </div>
        </RoundedCard>

        {vehicles.map(v => (
          <RoundedCard key={v.id} className="relative overflow-hidden border-none shadow-xl bg-white group active:scale-[0.98] transition-all">
             <div className="flex justify-between items-start mb-6">
               <div className="flex gap-4">
                 <div className="w-14 h-14 bg-sky-900 text-white rounded-[1.5rem] flex items-center justify-center text-xl shadow-lg shadow-sky-100">
                    <i className="fas fa-truck-pickup"></i>
                 </div>
                 <div>
                   <span className="text-[10px] font-black text-sky-400 uppercase tracking-widest leading-none block mb-1">{v.plate}</span>
                   <h3 className="text-xl font-black text-sky-900 leading-tight">{v.description}</h3>
                 </div>
               </div>
               <button onClick={() => setEditingVehicle(v)} className="w-10 h-10 bg-sky-50 text-sky-400 rounded-full flex items-center justify-center hover:bg-sky-100 transition-colors"><i className="fas fa-edit"></i></button>
             </div>

             <div className="flex items-end justify-between mb-4">
               <div>
                 <p className="text-[10px] font-black text-sky-400 uppercase tracking-tighter mb-1">Carga Actual</p>
                 <p className="text-4xl font-black text-sky-600 tracking-tighter">{v.currentLoad} <span className="text-xs font-bold text-sky-300 ml-1">UNIDADES</span></p>
               </div>
               <div className="flex gap-3">
                 <button onClick={() => loadVehicle(v.id, -1)} className="w-14 h-14 bg-sky-50 rounded-2xl flex items-center justify-center text-sky-600 font-black text-2xl shadow-sm active:bg-sky-100 transition-all">-</button>
                 <button onClick={() => loadVehicle(v.id, 1)} className="w-14 h-14 bg-sky-600 rounded-2xl flex items-center justify-center text-white font-black text-2xl shadow-lg shadow-sky-100 active:scale-90 transition-all">+</button>
               </div>
             </div>

             <div className="w-full bg-sky-50 h-3 rounded-full overflow-hidden border border-sky-100">
               <div className="h-full bg-gradient-to-r from-sky-400 to-sky-600 transition-all duration-700 ease-out" style={{ width: `${(v.currentLoad/v.loadCapacity)*100}%` }}></div>
             </div>
             <div className="flex justify-between mt-2">
                <span className="text-[9px] font-black text-sky-300 uppercase">Límite: {v.loadCapacity}</span>
                <span className="text-[9px] font-black text-sky-500 uppercase">{Math.round((v.currentLoad/v.loadCapacity)*100)}% Capacidad</span>
             </div>
          </RoundedCard>
        ))}

        <button 
          onClick={() => setEditingVehicle({})}
          className="w-full py-7 border-2 border-dashed border-sky-200 rounded-[2.5rem] text-sky-400 font-black text-sm uppercase hover:bg-white hover:text-sky-600 transition-all group"
        >
          <i className="fas fa-plus mr-2 group-hover:scale-125 transition-transform"></i> Registrar Nueva Unidad
        </button>
      </div>
    </div>
  );
};

