import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  build: {
    // Extendemos el límite de advertencia a 2MB (2000kB) para evitar la alerta en consola
    chunkSizeWarningLimit: 2000,
    rollupOptions: {
      output: {
        // Estrategia de fragmentación manual para separar librerías grandes en sus propios archivos
        // Esto mejora el almacenamiento en caché y reduce el tamaño del chunk principal
        manualChunks(id) {
          if (id.includes('node_modules')) {
            // Agrupar dependencias de IA (Gemini)
            if (id.includes('@google/genai')) {
              return 'vendor-ai';
            }
            // Agrupar PeerJS para sincronización P2P
            if (id.includes('peerjs')) {
              return 'vendor-p2p';
            }
            // Agrupar React y librerías core
            if (id.includes('react')) {
              return 'vendor-react';
            }
            // El resto de dependencias externas
            return 'vendor';
          }
        },
      },
    },
  },
