const LoadingModule: React.FC = () => (
  <div className="h-full w-full flex flex-col items-center justify-center bg-sky-50/50 backdrop-blur-sm animate-fadeIn">
    <div className="w-12 h-12 border-4 border-sky-200 border-t-sky-600 rounded-full animate-spin mb-4"></div>
