import React, { useState, useEffect, useRef } from 'react';
import Peer, { DataConnection } from 'peerjs';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

interface SyncModuleProps {
  onBack: () => void;
  onScanRequest: () => void;
  scannedId?: string;
}

export const SyncModule: React.FC<SyncModuleProps> = ({ onBack, onScanRequest, scannedId }) => {
  const { sales, customers, syncData } = useERPData();
  const [peerId, setPeerId] = useState<string>('');
  const [targetId, setTargetId] = useState<string>('');
  const [status, setStatus] = useState<'idle' | 'connecting' | 'connected' | 'error'>('idle');
  const [lastSync, setLastSync] = useState<number | null>(null);
  const [logs, setLogs] = useState<string[]>([]);

  const peerRef = useRef<Peer | null>(null);
  const connRef = useRef<DataConnection | null>(null);
  const heartbeatInterval = useRef<any>(null);

  const addLog = (msg: string) => setLogs(prev => [`[${new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit', second:'2-digit'})}] ${msg}`, ...prev].slice(0, 8));

  // Efecto para manejar IDs escaneados desde el módulo de cámara
  useEffect(() => {
    if (scannedId) {
      setTargetId(scannedId);
      addLog("ID capturado por cámara. Iniciando enlace...");
      // Pequeño delay para asegurar que el motor Peer esté listo
      setTimeout(() => connectToPeer(scannedId), 500);
    }
  }, [scannedId]);

  useEffect(() => {
    // Configuración robusta con servidores STUN de Google para saltar Firewalls
    const peer = new Peer({
      config: {
        'iceServers': [
          { url: 'stun:stun.l.google.com:19302' },
          { url: 'stun:stun1.l.google.com:19302' },
        ]
      }
    });

    peerRef.current = peer;

    peer.on('open', (id) => {
      setPeerId(id);
      addLog('Motor P2P En Línea. Listo para recibir.');
    });

    peer.on('connection', (conn) => {
      addLog(`Solicitud de enlace: ${conn.peer.slice(0, 5)}...`);
      setupConnection(conn);
    });

    peer.on('error', (err) => {
      console.error(err);
      setStatus('error');
      addLog(`Error de Red: ${err.type}`);
    });

    return () => {
      if (heartbeatInterval.current) clearInterval(heartbeatInterval.current);
      peer.destroy();
    };
  }, []);

  const setupConnection = (conn: DataConnection) => {
    connRef.current = conn;
    setStatus('connecting');

    conn.on('open', () => {
      setStatus('connected');
      addLog('¡Terminales enlazadas exitosamente!');

      // Enviar datos locales inmediatamente al conectar
      sendData(conn);

      // Iniciar latido para mantener la conexión activa en Android
      heartbeatInterval.current = setInterval(() => {
        if (conn.open) conn.send({ type: 'HEARTBEAT' });
      }, 5000);
    });

    conn.on('data', (data: any) => {
      if (!data) return;

      if (data.type === 'SYNC_DATA') {
        addLog(`Recibiendo: ${data.sales.length} ventas y ${data.customers.length} clientes...`);
        const success = syncData({ sales: data.sales, customers: data.customers });
        if (success) {
          setLastSync(Date.now());
          addLog('Base de datos sincronizada y mergeada.');
        }
      }

      if (data.type === 'REQUEST_DATA') {
        sendData(conn);
      }
    });

    conn.on('close', () => {
      setStatus('idle');
      addLog('Enlace finalizado.');
      if (heartbeatInterval.current) clearInterval(heartbeatInterval.current);
    });
  };

  const connectToPeer = (idToConnect: string = targetId) => {
    if (!idToConnect || !peerRef.current) return;
    addLog(`Intentando conectar a: ${idToConnect.slice(0, 8)}...`);
    const conn = peerRef.current.connect(idToConnect, {
      reliable: true
    });
    setupConnection(conn);
  };

  const sendData = (conn: DataConnection) => {
    if (!conn.open) return;
    conn.send({
      type: 'SYNC_DATA',
      sales,
      customers,
      timestamp: Date.now()
    });
    addLog('Datos locales enviados al par.');
  };

  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${peerId}`;

  return (
    <div className="h-full animate-fadeIn bg-sky-50 pb-24 flex flex-col overflow-hidden">
      <ModuleHeader title="Sincronización P2P" onBack={onBack} />

      <div className="flex-1 overflow-y-auto px-6 space-y-6 no-scrollbar pb-10">

        {/* Tu Identidad QR */}
        <RoundedCard className="bg-sky-900 text-white border-none shadow-xl relative overflow-hidden text-center py-8">
          <div className="relative z-10 flex flex-col items-center">
            <span className="text-[10px] font-black uppercase opacity-60 tracking-[0.2em] mb-4">Tu Código de Enlace</span>

            <div className="bg-white p-3 rounded-[2rem] mb-4 shadow-2xl">
              {peerId ? (
                <img src={qrUrl} alt="Peer ID QR" className="w-40 h-40" />
              ) : (
                <div className="w-40 h-40 flex items-center justify-center">
                  <i className="fas fa-spinner animate-spin text-sky-200 text-3xl"></i>
                </div>
              )}
            </div>

            <div className="flex items-center gap-2 bg-white/10 px-4 py-2 rounded-full mb-2">
              <span className="text-xs font-mono opacity-80">{peerId || 'Generando ID...'}</span>
              <button onClick={() => navigator.clipboard.writeText(peerId)} className="text-sky-300 active:scale-90 transition-transform">
                <i className="fas fa-copy"></i>
              </button>
            </div>
            <p className="text-[9px] opacity-40 italic">Muestra este código al otro dispositivo</p>
          </div>
          <i className="fas fa-tower-broadcast absolute -bottom-6 -right-6 text-9xl text-white/5 rotate-12"></i>
        </RoundedCard>

        {/* Acciones de Conexión */}
        <section className="space-y-4">
          <h4 className="text-[10px] font-black uppercase text-sky-400 ml-2 tracking-widest">Enlazar con otro terminal</h4>
          <div className="flex gap-2">
            <button 
              onClick={onScanRequest}
              className="flex-1 bg-white border border-sky-100 py-5 rounded-[2rem] shadow-sm flex items-center justify-center gap-3 text-sky-600 font-black text-xs active:scale-95 transition-all"
            >
              <i className="fas fa-camera text-lg"></i> ESCANEAR QR
            </button>
            <div className="flex-[1.5] relative">
               <input 
                type="text" 
                placeholder="ID Manual..." 
                className="w-full bg-white border-none rounded-[2rem] py-5 px-6 shadow-sm outline-none focus:ring-2 ring-sky-300 font-mono text-[10px]"
                value={targetId}
                onChange={(e) => setTargetId(e.target.value)}
              />
              <button 
                onClick={() => connectToPeer()}
                className="absolute right-2 top-2 bottom-2 w-12 bg-sky-600 text-white rounded-[1.5rem] flex items-center justify-center shadow-lg active:scale-90 transition-all"
              >
                <i className="fas fa-link"></i>
              </button>
            </div>
          </div>
        </section>

        {/* Estado y Logs */}
        <section className="space-y-3">
          <div className="flex justify-between items-center px-2">
            <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest">Monitor de Red</h4>
            <div className="flex items-center gap-2">
               <div className={`w-2 h-2 rounded-full ${status === 'connected' ? 'bg-emerald-500 animate-pulse' : 'bg-slate-300'}`}></div>
               <span className="text-[9px] font-black text-sky-900 uppercase">
                 {status === 'connected' ? 'Sincronizado' : status === 'connecting' ? 'Enlazando...' : 'Desconectado'}
               </span>
            </div>
          </div>

          <div className="bg-white/80 backdrop-blur border border-white p-5 rounded-[2.5rem] shadow-sm">
             <div className="space-y-2 mb-4">
                {logs.length === 0 ? (
                  <p className="text-[10px] text-sky-300 text-center italic py-4">Sin actividad reciente...</p>
                ) : (
                  logs.map((log, i) => (
                    <div key={i} className={`text-[9px] font-bold flex gap-2 ${i === 0 ? 'text-sky-600' : 'text-sky-300'} animate-fadeIn`}>
                      <span className="opacity-30">•</span> {log}
                    </div>
                  ))
                )}
             </div>

             {status === 'connected' && (
               <button 
                onClick={() => connRef.current && sendData(connRef.current)}
                className="w-full py-3 bg-sky-50 text-sky-600 rounded-2xl text-[10px] font-black uppercase tracking-widest active:bg-sky-100 transition-colors"
               >
                 Forzar Envío de Datos
               </button>
             )}
          </div>
        </section>

        <RoundedCard className="bg-indigo-50 border-indigo-100 py-5">
          <div className="flex gap-4 items-center">
            <div className="w-10 h-10 bg-indigo-500 text-white rounded-xl flex items-center justify-center shrink-0 shadow-lg shadow-indigo-100">
              <i className="fas fa-shield-halved"></i>
            </div>
            <p className="text-[9px] text-indigo-700 leading-tight font-bold">
              Las transferencias P2P están encriptadas de punto a punto. No se guardan datos en ningún servidor externo.
            </p>
          </div>
        </RoundedCard>
      </div>

      <div className="p-6 bg-white/80 backdrop-blur-xl border-t border-sky-100">
        <ActionButton onClick={onBack} variant="secondary">Regresar al Panel</ActionButton>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ModuleHeader, RoundedCard } from './ui/Cards';

interface ScannerModuleProps {
  onBack: () => void;
  onScanSuccess?: (data: string, type: 'TICKET' | 'PEER_ID') => void;
  mode?: 'TICKET' | 'P2P';
}

export const ScannerModule: React.FC<ScannerModuleProps> = ({ onBack, onScanSuccess, mode = 'TICKET' }) => {
  const [scanning, setScanning] = useState(true);
  const [result, setResult] = useState<any>(null);

  const decryptData = (encrypted: string) => {
    try {
      const decoded = atob(encrypted);
      if (decoded.startsWith('AQUA-PRO-SECURE|')) {
        return JSON.parse(decoded.split('|')[1]);
      }
      return null;
    } catch {
      return null;
    }
  };

  const handleManualEntry = (code: string) => {
    if (mode === 'P2P') {
      // Si el código parece un PeerID (UUID o string largo alfanumérico)
      if (code.length > 5) {
        if (onScanSuccess) onScanSuccess(code, 'PEER_ID');
        return;
      }
    }

    const data = decryptData(code);
    if (data) {
      if (onScanSuccess) {
        onScanSuccess(code, 'TICKET');
      } else {
        setResult(data);
        setScanning(false);
      }
    } else {
      alert("Código inválido o malformado.");
    }
  };

  return (
    <div className={`h-full flex flex-col animate-fadeIn overflow-hidden ${mode === 'P2P' ? 'bg-sky-50' : 'bg-sky-900'}`}>
      <div className="px-6 pt-8 pb-4 flex items-center gap-4">
        <button onClick={onBack} className={`w-12 h-12 rounded-2xl flex items-center justify-center active:scale-90 transition-transform ${mode === 'P2P' ? 'bg-white shadow-sm text-sky-600' : 'bg-white/10 text-white'}`}>
          <i className="fas fa-arrow-left"></i>
        </button>
        <h2 className={`text-2xl font-black tracking-tight ${mode === 'P2P' ? 'text-sky-900' : 'text-white'}`}>
          {mode === 'P2P' ? 'Vincular Terminal' : 'Validación QR'}
        </h2>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center px-10">
        {scanning ? (
          <div className="w-full space-y-8 flex flex-col items-center">
            <div className={`w-64 h-64 border-4 rounded-[3rem] relative overflow-hidden flex items-center justify-center ${mode === 'P2P' ? 'border-sky-500 bg-sky-100/50' : 'border-sky-400 bg-black/20'}`}>
              <div className={`absolute top-0 left-0 right-0 h-1 shadow-[0_0_15px_rgba(56,189,248,0.8)] animate-scanner ${mode === 'P2P' ? 'bg-sky-600' : 'bg-sky-400'}`}></div>
              <i className={`fas fa-qrcode text-6xl ${mode === 'P2P' ? 'text-sky-300' : 'text-white/20'}`}></i>
            </div>

            <div className="text-center">
              <h3 className={`font-black text-xl mb-2 ${mode === 'P2P' ? 'text-sky-900' : 'text-white'}`}>
                {mode === 'P2P' ? 'Escanea el ID del par' : 'Escaneando Ticket'}
              </h3>
              <p className={`text-xs font-medium px-4 ${mode === 'P2P' ? 'text-sky-500' : 'text-sky-300'}`}>
                {mode === 'P2P' ? 'Apunta al código QR generado en el módulo Sync del otro dispositivo.' : 'Apunta la cámara al código QR impreso en el ticket del cliente.'}
              </p>
            </div>

            <div className="w-full">
              <input 
                type="text" 
                placeholder="O ingresa código manual..." 
                className={`w-full border rounded-2xl p-4 text-xs outline-none focus:ring-2 ring-sky-400 transition-all ${mode === 'P2P' ? 'bg-white border-sky-100 text-sky-900' : 'bg-white/10 border-white/20 text-white'}`}
                onKeyDown={e => e.key === 'Enter' && handleManualEntry(e.currentTarget.value)}
              />
            </div>

            {/* Simulación de escaneo para demo o si no hay cámara activa en WebView */}
            <p className="text-[8px] uppercase tracking-widest text-sky-400 opacity-50">Cámara Activa • Autofocus On</p>
          </div>
        ) : (
          <RoundedCard className="w-full bg-white animate-fadeIn p-8">
            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 bg-emerald-100 text-emerald-500 rounded-full flex items-center justify-center mb-6">
                <i className="fas fa-check-circle text-4xl"></i>
              </div>
              <h3 className="text-2xl font-black text-sky-900 mb-2">Ticket Válido</h3>
              <div className="w-full bg-sky-50 rounded-3xl p-6 mb-8 space-y-4">
                <div className="flex justify-between">
                  <span className="text-[10px] font-black text-sky-400 uppercase">Ticket ID</span>
                  <span className="text-xs font-black text-sky-900">{result?.id}</span>
                </div>
                <div className="flex justify-between border-t border-sky-100 pt-3">
                  <span className="text-[10px] font-black text-sky-400 uppercase">Monto</span>
                  <span className="text-xl font-black text-sky-900">${result?.total}</span>
                </div>
              </div>
              <button 
                onClick={() => setScanning(true)} 
                className="w-full bg-sky-600 text-white py-5 rounded-[2rem] font-black uppercase text-xs tracking-widest shadow-xl shadow-sky-100"
              >
                Escanear Otro
              </button>
            </div>
          </RoundedCard>
        )}
      </div>

      <style>{`
        @keyframes scanner {
          0% { transform: translateY(0); }
          100% { transform: translateY(256px); }
        }
        .animate-scanner { animation: scanner 2s linear infinite alternate; }
      `}</style>

      <div className={`p-10 text-center opacity-40 ${mode === 'P2P' ? 'text-sky-900' : 'text-white'}`}>
        <p className="text-[10px] font-black uppercase tracking-[0.3em]">Sistema de Seguridad Aqua+</p>
      </div>
    </div>
  );
};

