import React, { useState, useEffect, useRef } from 'react';
import Peer, { DataConnection } from 'peerjs';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

interface SyncModuleProps {
  onBack: () => void;
  onScanRequest: () => void;
  scannedId?: string;
}

export const SyncModule: React.FC<SyncModuleProps> = ({ onBack, onScanRequest, scannedId }) => {
  const { sales, customers, syncData, addSale } = useERPData();
  const [peerId, setPeerId] = useState<string>('');
  const [targetId, setTargetId] = useState<string>('');
  const [status, setStatus] = useState<'idle' | 'connecting' | 'connected' | 'error'>('idle');
  const [logs, setLogs] = useState<string[]>([]);
  const [latency, setLatency] = useState<number | null>(null);

  const peerRef = useRef<Peer | null>(null);
  const connRef = useRef<DataConnection | null>(null);
  const heartbeatInterval = useRef<any>(null);

  const addLog = (msg: string) => setLogs(prev => [`[${new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit', second:'2-digit'})}] ${msg}`, ...prev].slice(0, 10));

  useEffect(() => {
    if (scannedId) {
      setTargetId(scannedId);
      addLog("QR Detectado. Intentando vinculación...");
      setTimeout(() => connectToPeer(scannedId), 800);
    }
  }, [scannedId]);

  useEffect(() => {
    const peer = new Peer({
      config: {
        'iceServers': [
          { url: 'stun:stun.l.google.com:19302' },
          { url: 'stun:stun1.l.google.com:19302' }
        ]
      }
    });

    peerRef.current = peer;

    peer.on('open', (id) => {
      setPeerId(id);
      addLog('Sistema P2P listo. Esperando pares.');
    });

    peer.on('connection', (conn) => {
      addLog(`Enlace entrante desde: ${conn.peer.slice(0, 6)}`);
      setupConnection(conn);
    });

    peer.on('error', (err) => {
      setStatus('error');
      addLog(`Error Crítico: ${err.type}`);
    });

    return () => {
      if (heartbeatInterval.current) clearInterval(heartbeatInterval.current);
      peer.destroy();
    };
  }, []);

  const setupConnection = (conn: DataConnection) => {
    connRef.current = conn;
    setStatus('connecting');

    conn.on('open', () => {
      setStatus('connected');
      addLog('¡Conexión Establecida! Sincronizando...');

      // Sincronización inicial
      sendSyncData(conn);

      heartbeatInterval.current = setInterval(() => {
        if (conn.open) conn.send({ type: 'HEARTBEAT', t: Date.now() });
      }, 4000);
    });

    conn.on('data', (data: any) => {
      if (!data) return;

      if (data.type === 'HEARTBEAT') {
        // Responder al latido si es necesario o ignorar silenciosamente
      }

      if (data.type === 'PING') {
        conn.send({ type: 'PONG', t: data.t });
        addLog('Recibido: PING (Respondido)');
      }

      if (data.type === 'PONG') {
        const diff = Date.now() - data.t;
        setLatency(diff);
        addLog(`PONG recibido. Latencia: ${diff}ms`);
      }

      if (data.type === 'SYNC_DATA') {
        addLog(`Sync: ${data.sales.length} ventas recibidas.`);
        syncData({ sales: data.sales, customers: data.customers });
      }
    });

    conn.on('close', () => {
      setStatus('idle');
      setLatency(null);
      addLog('Conexión cerrada por el par.');
    });
  };

  const connectToPeer = (id: string = targetId) => {
    if (!id || !peerRef.current) return;
    if (id === peerId) return addLog("No puedes conectarte a ti mismo.");

    addLog(`Buscando terminal: ${id.slice(0, 8)}...`);
    const conn = peerRef.current.connect(id, { reliable: true });
    setupConnection(conn);
  };

  const sendSyncData = (conn: DataConnection) => {
    if (!conn.open) return;
    conn.send({
      type: 'SYNC_DATA',
      sales,
      customers
    });
    addLog('Datos enviados exitosamente.');
  };

  const sendPing = () => {
    if (connRef.current?.open) {
      addLog('Enviando PING...');
      connRef.current.send({ type: 'PING', t: Date.now() });
    }
  };

  const simulateSale = () => {
    if (customers.length === 0) return alert("Crea un cliente primero.");
    const sale = addSale(customers[0].id, [], 100, 100, [{method: 'Efectivo', amount: 100}], 0);
    addLog(`Venta simulada creada (${sale.id}).`);
    if (connRef.current?.open) sendSyncData(connRef.current);
  };

  const copyId = () => {
    navigator.clipboard.writeText(peerId);
    addLog("ID copiado al portapapeles.");
  };

  return (
    <div className="h-full animate-fadeIn bg-sky-50 pb-24 flex flex-col overflow-hidden">
      <ModuleHeader title="Terminal P2P" onBack={onBack} />

      <div className="flex-1 overflow-y-auto px-6 space-y-6 no-scrollbar pb-10">

        {/* Identidad Local */}
        <RoundedCard className="bg-sky-900 text-white border-none shadow-xl relative overflow-hidden">
          <div className="relative z-10 flex flex-col items-center py-4">
            <span className="text-[9px] font-black uppercase opacity-60 tracking-[0.3em] mb-4">Tu Punto de Enlace</span>
            <div className="bg-white p-3 rounded-[2rem] mb-4 shadow-2xl">
              {peerId ? (
                <img src={`https://api.qrserver.com/v1/create-qr-code/?size=160x160&data=${peerId}`} alt="QR" className="w-32 h-32" />
              ) : (
                <div className="w-32 h-32 flex items-center justify-center"><i className="fas fa-spinner animate-spin text-sky-200 text-3xl"></i></div>
              )}
            </div>
            <button onClick={copyId} className="flex items-center gap-2 bg-white/10 px-5 py-2 rounded-full active:scale-95 transition-all">
              <span className="text-[10px] font-mono opacity-80">{peerId ? peerId.slice(0, 16) + '...' : 'Generando...'}</span>
              <i className="fas fa-copy text-sky-300"></i>
            </button>
          </div>
          <i className="fas fa-satellite-dish absolute -bottom-6 -right-6 text-9xl text-white/5 rotate-12"></i>
        </RoundedCard>

        {/* Panel de Conexión */}
        <section className="space-y-4">
          <div className="flex gap-2">
            <button onClick={onScanRequest} className="flex-1 bg-white border border-sky-100 py-5 rounded-[2rem] shadow-sm flex items-center justify-center gap-2 text-sky-600 font-black text-[10px] active:scale-95 transition-all">
              <i className="fas fa-camera"></i> ESCANEAR
            </button>
            <div className="flex-[1.5] relative">
               <input 
                type="text" 
                placeholder="Pegar ID del par..." 
                className="w-full bg-white border-none rounded-[2rem] py-5 px-6 shadow-sm outline-none focus:ring-2 ring-sky-300 font-mono text-[10px]"
                value={targetId}
                onChange={(e) => setTargetId(e.target.value)}
              />
              <button onClick={() => connectToPeer()} className="absolute right-2 top-2 bottom-2 w-12 bg-sky-600 text-white rounded-[1.5rem] flex items-center justify-center shadow-lg active:scale-90 transition-all">
                <i className="fas fa-link"></i>
              </button>
            </div>
          </div>
        </section>

        {/* Diagnóstico y Pruebas */}
        <section className="space-y-3">
          <div className="flex justify-between items-center px-2">
            <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest">Estado y Diagnóstico</h4>
            {latency !== null && (
              <span className="text-[10px] font-black text-emerald-500 uppercase">{latency}ms latencia</span>
            )}
          </div>

          <div className="bg-white/80 backdrop-blur border border-white p-5 rounded-[2.5rem] shadow-sm">
             <div className="space-y-2 mb-5 max-h-40 overflow-y-auto no-scrollbar flex flex-col-reverse">
                {logs.length === 0 ? (
                  <p className="text-[10px] text-sky-300 text-center italic py-4">Esperando actividad...</p>
                ) : (
                  logs.map((log, i) => (
                    <div key={i} className={`text-[9px] font-bold flex gap-2 ${i === 0 ? 'text-sky-600' : 'text-sky-300'} animate-fadeIn`}>
                      <span className="opacity-30">•</span> {log}
                    </div>
                  ))
                )}
             </div>

             {status === 'connected' ? (
               <div className="grid grid-cols-2 gap-2">
                  <button onClick={sendPing} className="py-4 bg-sky-50 text-sky-600 rounded-2xl text-[10px] font-black uppercase tracking-widest active:bg-sky-100">
                    <i className="fas fa-bolt mr-2"></i> Test Ping
                  </button>
                  <button onClick={simulateSale} className="py-4 bg-emerald-50 text-emerald-600 rounded-2xl text-[10px] font-black uppercase tracking-widest active:bg-emerald-100">
                    <i className="fas fa-vial mr-2"></i> Venta Test
                  </button>
               </div>
             ) : (
               <div className="text-center py-2">
                  <div className={`inline-block px-4 py-1.5 rounded-full text-[9px] font-black uppercase ${status === 'connecting' ? 'bg-amber-100 text-amber-600 animate-pulse' : 'bg-sky-50 text-sky-400'}`}>
                    {status === 'connecting' ? 'Enlazando...' : 'Terminal en espera'}
                  </div>
               </div>
             )}
          </div>
        </section>

        <RoundedCard className="bg-indigo-50 border-indigo-100 py-5">
          <div className="flex gap-4 items-center">
            <div className="w-10 h-10 bg-indigo-500 text-white rounded-xl flex items-center justify-center shrink-0 shadow-lg">
              <i className="fas fa-network-wired"></i>
            </div>
            <p className="text-[9px] text-indigo-700 leading-tight font-bold">
              Instrucción de prueba: Abre esta app en dos ventanas. Copia el ID de una, pégalo en la otra y presiona el enlace. Luego usa "Venta Test".
            </p>
          </div>
        </RoundedCard>
      </div>

      <div className="p-6 bg-white/80 backdrop-blur-xl border-t border-sky-100">
        <ActionButton onClick={onBack} variant="secondary">Regresar al Panel</ActionButton>
      </div>
    </div>
  );
};

