import React, { useState } from 'react';
import { Product, Customer, CartItem, PaymentSplit, Sale, Employee } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

export const POSModule: React.FC<{ onBack: () => void; user: Employee }> = ({ onBack, user }) => {
  const { products, customers, sales, addSale, ticketConfig } = useERPData();
  const [activeTab, setActiveTab] = useState<'sell' | 'history'>('sell');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [search, setSearch] = useState('');
  const [vacios, setVacios] = useState(0);
  const [manualDate, setManualDate] = useState<string>(new Date().toISOString().slice(0, 16));
  const [showSuccessModal, setShowSuccessModal] = useState<Sale | null>(null);

  const [paidCash, setPaidCash] = useState<string>('');
  const [paidTransfer, setPaidTransfer] = useState<string>('');

  const total = cart.reduce((sum, item) => {
    const price = (customer?.specialPrice && item.id === '1') ? customer.specialPrice : item.price;
    return sum + (price * item.quantity);
  }, 0);

  const totalPaid = (parseFloat(paidCash) || 0) + (parseFloat(paidTransfer) || 0);
  const change = Math.max(0, totalPaid - total);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) return prev.map(i => i.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const generateTicketPDF = (sale: Sale) => {
    const qrData = btoa(`AQUA-PRO-SECURE|${JSON.stringify({ id: sale.id, total: sale.total })}`);
    const ticketHtml = `
      <div style="font-family: 'Courier New', monospace; padding: 15px; text-align: center; width: 280px; margin: auto; color: #000; background: #fff;">
        ${ticketConfig.logoUrl ? `<img src="${ticketConfig.logoUrl}" style="width: 80px; height: 80px; object-fit: contain; margin-bottom: 10px;"/>` : ''}
        <h2 style="margin: 0; font-size: 16px; text-transform: uppercase;">${ticketConfig.businessName}</h2>
        <p style="font-size: 10px; margin: 2px 0;">RFC: ${ticketConfig.rfc}</p>
        <p style="font-size: 9px; margin: 0;">${ticketConfig.address}</p>
        <p style="font-size: 9px; margin: 0;">Tel: ${ticketConfig.phone}</p>
        ${ticketConfig.website ? `<p style="font-size: 9px; margin: 0;">${ticketConfig.website}</p>` : ''}
        ${ticketConfig.socialMedia ? `<p style="font-size: 9px; margin: 0;">${ticketConfig.socialMedia}</p>` : ''}

        <div style="border-top: 1px dashed #000; margin: 10px 0;"></div>

        <div style="font-size: 11px; text-align: left;">
          <p style="margin: 2px 0;">TICKET: <b>${sale.id}</b></p>
          <p style="margin: 2px 0;">FECHA: ${new Date(sale.timestamp).toLocaleString()}</p>
          <p style="margin: 2px 0;">CLIENTE: ${sale.customerAlias}</p>
        </div>

        <div style="border-top: 1px dashed #000; margin: 10px 0;"></div>

        <table style="width: 100%; font-size: 11px; border-collapse: collapse;">
          <thead>
            <tr>
              <th style="text-align: left;">CANT</th>
              <th style="text-align: left;">DESC</th>
              <th style="text-align: right;">IMP</th>
            </tr>
          </thead>
          <tbody>
            ${sale.items.map(i => `
              <tr>
                <td style="text-align: left;">${i.quantity}</td>
                <td style="text-align: left;">${i.name.slice(0, 15)}</td>
                <td style="text-align: right;">$${(i.quantity * i.price).toFixed(2)}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>

        <div style="border-top: 1px dashed #000; margin: 10px 0;"></div>

        <div style="text-align: right; font-size: 12px; font-weight: bold;">
          <p style="margin: 2px 0;">TOTAL: $${sale.total.toFixed(2)}</p>
        </div>
        <div style="text-align: right; font-size: 11px;">
          <p style="margin: 2px 0;">RECIBIDO: $${sale.paidAmount.toFixed(2)}</p>
          <p style="margin: 2px 0;">CAMBIO: $${sale.change.toFixed(2)}</p>
        </div>

        <div style="border-top: 1px dashed #000; margin: 10px 0;"></div>

        <p style="font-size: 10px; font-weight: bold; margin: 5px 0;">${ticketConfig.footerMessage}</p>
        ${ticketConfig.extraNote ? `<p style="font-size: 8px; font-style: italic; margin: 0;">* ${ticketConfig.extraNote}</p>` : ''}

        <div style="margin-top: 10px;">
          <img src="https://api.qrserver.com/v1/create-qr-code/?size=100x100&data=${encodeURIComponent(qrData)}" style="width: 100px; height: 100px;"/>
          <p style="font-size: 7px; margin-top: 4px; color: #888;">Validación Digital Aqua+</p>
        </div>
      </div>
    `;
    const win = window.open('', '_blank');
    if (win) {
      win.document.write(ticketHtml);
      win.document.close();
      win.print();
    }
  };

  const handleSendWhatsApp = (sale: Sale) => {
    const phone = customer?.phone?.replace(/\D/g, '');
    if (!phone) return alert("El cliente no tiene teléfono.");

    const itemsText = sale.items.map(i => `• ${i.quantity}x ${i.name}`).join('%0A');
    const msg = `¡Hola ${sale.customerAlias}!%0A%0A*${ticketConfig.businessName}*%0AGracias por tu compra.%0A%0A*Detalles de tu pedido:*%0A${itemsText}%0A%0A*Total:* $${sale.total.toFixed(2)}%0A*Ticket:* ${sale.id}%0A%0A_Validación de seguridad QR disponible en planta._`;
    window.open(`https://wa.me/52${phone}?text=${msg}`, '_blank');
  };

  const handleCheckout = () => {
    if (!customer) return alert("Selecciona un cliente.");
    const splits: PaymentSplit[] = [];
    if (parseFloat(paidCash) > 0) splits.push({ method: 'Efectivo', amount: parseFloat(paidCash) });
    if (parseFloat(paidTransfer) > 0) splits.push({ method: 'Transferencia', amount: parseFloat(paidTransfer) });

    const sale = addSale(
      customer.id, cart, total, totalPaid, splits, vacios, 
      user.role === 'Administrador' ? new Date(manualDate).getTime() : undefined
    );

    setShowSuccessModal(sale);
    setCart([]);
    setCustomer(null);
    setSearch('');
    setPaidCash('');
    setPaidTransfer('');
  };

  return (
    <div className="h-full flex flex-col animate-fadeIn bg-sky-50 pb-24 overflow-hidden relative">
      <ModuleHeader title="Punto de Venta" onBack={onBack} />

      <div className="px-6 flex gap-2 mb-4">
        <button onClick={() => setActiveTab('sell')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'sell' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Nueva Venta</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-3 rounded-2xl text-xs font-bold ${activeTab === 'history' ? 'bg-sky-600 text-white shadow-lg' : 'bg-white text-sky-400'}`}>Historial</button>
      </div>

      {activeTab === 'sell' ? (
        <div className="flex-1 overflow-y-auto px-6 space-y-6 pb-32 no-scrollbar">
          {/* Admin Date Control */}
          {user.role === 'Administrador' && (
            <div className="bg-amber-50 p-4 rounded-3xl border border-amber-200">
              <label className="text-[9px] font-black text-amber-600 uppercase mb-2 block tracking-widest">Cronología de Venta (Sólo Admin)</label>
              <input 
                type="datetime-local" 
                className="w-full bg-white border-none rounded-2xl p-3 text-xs font-bold text-amber-900 shadow-inner"
                value={manualDate}
                onChange={e => setManualDate(e.target.value)}
              />
            </div>
          )}

          <section>
            <div className="relative">
              <input type="text" placeholder="Buscar Cliente..." className="w-full bg-white border-none rounded-[2rem] py-5 px-8 shadow-sm outline-none" value={search} onChange={e => setSearch(e.target.value)} />
              {search && !customer && (
                <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-3xl mt-2 z-50 overflow-hidden">
                  {customers.filter(c => c.alias.toLowerCase().includes(search.toLowerCase())).map(c => (
                    <button key={c.id} onClick={() => { setCustomer(c); setSearch(c.alias); }} className="w-full text-left p-4 hover:bg-sky-50 font-bold border-b border-sky-50">
                      {c.alias} <span className="text-[10px] text-sky-300 ml-2">${c.balance}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
          </section>

          <div className="grid grid-cols-2 gap-3">
            {products.map(p => (
              <button key={p.id} onClick={() => addToCart(p)} className="bg-white p-5 rounded-[2rem] shadow-sm active:bg-sky-50 text-left relative overflow-hidden group">
                <div className="text-sm font-black text-sky-900">{p.name}</div>
                <div className="text-sky-600 font-bold">${p.price}</div>
                <i className="fas fa-plus absolute -bottom-2 -right-2 text-3xl text-sky-100 opacity-20"></i>
              </button>
            ))}
          </div>

          {cart.length > 0 && (
            <RoundedCard className="shadow-xl">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className="text-[10px] text-sky-400 font-black uppercase mb-1 block">Total Venta</span>
                  <span className="text-4xl font-black text-sky-900 tracking-tighter">${total.toFixed(2)}</span>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <input type="number" value={paidCash} onChange={e => setPaidCash(e.target.value)} className="bg-sky-50/50 p-4 rounded-2xl font-bold text-lg" placeholder="Efectivo $" />
                <input type="number" value={paidTransfer} onChange={e => setPaidTransfer(e.target.value)} className="bg-sky-50/50 p-4 rounded-2xl font-bold text-lg" placeholder="Transf. $" />
              </div>
              <div className="mt-4 p-4 bg-emerald-50 rounded-2xl flex justify-between items-center">
                <span className="text-xs font-black text-emerald-700">CAMBIO</span>
                <span className="text-xl font-black text-emerald-600">${change.toFixed(2)}</span>
              </div>
            </RoundedCard>
          )}
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto px-6 space-y-3 pb-10">
          {sales.map(s => (
            <RoundedCard key={s.id} className="py-4">
              <div className="flex justify-between">
                <div>
                  <h4 className="font-black text-sky-900">{s.customerAlias}</h4>
                  <p className="text-[9px] text-sky-400">{new Date(s.timestamp).toLocaleString()}</p>
                </div>
                <span className="font-black text-sky-600">${s.total}</span>
              </div>
              <div className="flex gap-2 mt-3">
                 <button onClick={() => generateTicketPDF(s)} className="text-[8px] font-black uppercase bg-sky-100 text-sky-600 px-3 py-1 rounded-full">Re-imprimir</button>
                 <button onClick={() => handleSendWhatsApp(s)} className="text-[8px] font-black uppercase bg-emerald-100 text-emerald-600 px-3 py-1 rounded-full">Enviar WA</button>
              </div>
            </RoundedCard>
          ))}
        </div>
      )}

      {activeTab === 'sell' && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/95 border-t border-sky-100 shadow-2xl z-50">
          <ActionButton onClick={handleCheckout} disabled={!customer || cart.length === 0}>
            Completar Venta
          </ActionButton>
        </div>
      )}

      {/* Success Modal */}
      {showSuccessModal && (
        <div className="fixed inset-0 bg-sky-900/80 backdrop-blur-md z-[100] flex items-center justify-center p-8 animate-fadeIn">
          <div className="bg-white w-full rounded-[2.5rem] p-8 text-center shadow-2xl">
            <div className="w-20 h-20 bg-emerald-100 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-6">
              <i className="fas fa-check-circle text-4xl"></i>
            </div>
            <h3 className="text-2xl font-black text-sky-900 mb-2">¡Venta Exitosa!</h3>
            <p className="text-sky-400 text-xs font-bold mb-8">¿Qué deseas hacer con el ticket?</p>

            <div className="space-y-3">
              <button 
                onClick={() => { generateTicketPDF(showSuccessModal); setShowSuccessModal(null); }}
                className="w-full bg-sky-600 text-white py-5 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-3"
              >
                <i className="fas fa-print"></i> Imprimir Físico
              </button>
              <button 
                onClick={() => { handleSendWhatsApp(showSuccessModal); setShowSuccessModal(null); }}
                className="w-full bg-emerald-500 text-white py-5 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-3"
              >
                <i className="fab fa-whatsapp"></i> Enviar a Cliente
              </button>
              <button 
                onClick={() => setShowSuccessModal(null)}
                className="w-full bg-sky-50 text-sky-400 py-4 rounded-2xl font-black uppercase text-[10px]"
              >
                Cerrar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export type ViewType = 'dashboard' | 'pos' | 'orders' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings' | 'quality' | 'scanner' | 'inventory';

