  name: string;
  price: number;
  stock: number;
  category?: 'Agua' | 'Insumos' | 'Accesorios';
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  balance: number;
