const PermissionShield: React.FC<{ onGranted: () => void }> = ({ onGranted }) => {
  const [status, setStatus] = useState<'idle' | 'requesting' | 'error'>('idle');

  const requestPermissions = async () => {
    setStatus('requesting');
    try {
      // Solicitar Cámara y Micrófono simultáneamente
      if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ 
            audio: true, 
            video: { facingMode: 'environment' } 
          });
          // Detener los tracks inmediatamente después de obtener el permiso para no dejar la cámara encendida
          stream.getTracks().forEach(track => track.stop());
        } catch (mediaErr) {
          console.warn("Media permissions denied or failed:", mediaErr);
          // Continuamos aunque falle media, el usuario puede haberlo denegado
        }
      }

      // Solicitar Ubicación
      if (navigator.geolocation) {
        await new Promise((resolve) => {
          navigator.geolocation.getCurrentPosition(
            (pos) => resolve(pos), 
            (err) => {
              console.warn("Geolocation denied:", err);
              resolve(null); // Resolvemos incluso con error para no bloquear
            }, 
            { enableHighAccuracy: true, timeout: 3000 }
          );
        });
      }

      localStorage.setItem('aqua_permissions_granted', 'true');
      onGranted();
    } catch (e) {
      console.error("Global Permission error:", e);
      setStatus('error');
    }
  };

  return (
    <div className="fixed inset-0 bg-sky-900 flex flex-col items-center justify-center z-[200] px-10 text-center animate-fadeIn">
      <div className="w-24 h-24 bg-white/10 rounded-[2.5rem] flex items-center justify-center mb-8">
        <i className={`fas ${status === 'requesting' ? 'fa-circle-notch animate-spin' : 'fa-shield-halved'} text-sky-400 text-4xl`}></i>
      </div>
      <h2 className="text-white text-3xl font-black mb-4 tracking-tighter">Acceso Requerido</h2>
      <p className="text-sky-300 text-sm mb-12 font-medium leading-relaxed">
        Aqua+ necesita permisos de <b>Cámara</b> (para tickets), <b>Micrófono</b> (para comandos de voz) y <b>Ubicación</b> (para rutas de reparto).
      </p>

      {status === 'error' ? (
        <div className="space-y-4 w-full">
           <p className="text-red-300 text-[10px] font-bold uppercase bg-red-900/50 p-3 rounded-xl">Algunos permisos no pudieron ser verificados.</p>
           <button 
            onClick={() => { localStorage.setItem('aqua_permissions_granted', 'true'); onGranted(); }}
            className="w-full bg-white/20 text-white py-6 rounded-[2rem] font-black text-xs uppercase tracking-widest active:scale-95 transition-all"
          >
            Continuar de todos modos
          </button>
           <button 
            onClick={requestPermissions}
            className="w-full bg-sky-500 text-white py-6 rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-2xl shadow-sky-500/20 active:scale-95 transition-all"
          >
            Reintentar
          </button>
        </div>
      ) : (
        <button 
          onClick={requestPermissions}
          disabled={status === 'requesting'}
          className={`w-full ${status === 'requesting' ? 'bg-sky-700' : 'bg-sky-500'} text-white py-6 rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-2xl shadow-sky-500/20 active:scale-95 transition-all`}
        >
          {status === 'requesting' ? 'Autorizando...' : 'Conceder Todos los Permisos'}
        </button>
      )}
    </div>
  );
};

const SplashScreen: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
