import React, { useState, useEffect, useRef } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard } from './ui/Cards';

const BACKWASH_SEQUENCE = [
  { stage: 'Multicama', process: 'Backwash', time: 300 }, // 5 min
  { stage: 'Multicama', process: 'Enjuague Rápido', time: 180 }, // 3 min
  { stage: 'Carbón Activado', process: 'Backwash', time: 300 },
  { stage: 'Carbón Activado', process: 'Enjuague Rápido', time: 180 },
  { stage: 'Suavizador', process: 'Backwash', time: 300 },
  { stage: 'Suavizador', process: 'Enjuague Rápido', time: 180 },
];

const REGENERATION_SEQUENCE = [
  { stage: 'Suavizador', process: 'Backwash Inicial', time: 300 }, // 5 min
  { stage: 'Suavizador', process: 'Succión Salmuera', time: 1800 }, // 30 min
  { stage: 'Suavizador', process: 'Enjuague Lento', time: 1200 }, // 20 min
  { stage: 'Suavizador', process: 'Enjuague Rápido', time: 180 }, // 3 min
  { stage: 'Tanque Sal', process: 'Relleno Nivel', time: 300 }, // 5 min
];

// Sonido de alarma industrial
const ALARM_SOUND_URL = "https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3";

export const ProductionModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const [mode, setMode] = useState<'backwash' | 'regen'>('backwash');
  const [currentStepIdx, setCurrentStepIdx] = useState(0);
  const [timeLeft, setTimeLeft] = useState(0);
  const [isRunning, setIsRunning] = useState(false);
  const [endTime, setEndTime] = useState<number | null>(null);

  const [hardness, setHardness] = useState(8);
  const [showRegenAlert, setShowRegenAlert] = useState(false);

  const wakeLock = useRef<WakeLockSentinel | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const currentSequence = mode === 'backwash' ? BACKWASH_SEQUENCE : REGENERATION_SEQUENCE;

  // Solicitar permisos de notificación al montar
  useEffect(() => {
    if ("Notification" in window && Notification.permission !== "granted") {
      Notification.requestPermission();
    }
    audioRef.current = new Audio(ALARM_SOUND_URL);
  }, []);

  // Control de Wake Lock (Mantener pantalla encendida)
  const requestWakeLock = async () => {
    try {
      if ('wakeLock' in navigator) {
        wakeLock.current = await navigator.wakeLock.request('screen');
        console.log("Pantalla mantenida activa para proceso.");
      }
    } catch (err) {
      console.warn(`No se pudo bloquear la pantalla: ${err}`);
    }
  };

  const releaseWakeLock = async () => {
    if (wakeLock.current) {
      await wakeLock.current.release();
      wakeLock.current = null;
    }
  };

  // Función de Alarma
  const triggerAlarm = () => {
    // 1. Vibración
    if (navigator.vibrate) {
      navigator.vibrate([1000, 500, 1000, 500, 2000]); 
    }

    // 2. Sonido (Intentar reproducir incluso si no hay interacción reciente)
    if (audioRef.current) {
      audioRef.current.currentTime = 0;
      audioRef.current.play().catch(e => console.log("Interacción de audio requerida:", e));
    }

    // 3. Notificación del Sistema
    if ("Notification" in window && Notification.permission === "granted") {
      new Notification("Aqua+ Producción", {
        body: "¡Etapa finalizada! Atención requerida en planta.",
        icon: "/vite.svg", // Usar icono predeterminado si no hay uno específico
        vibrate: [200, 100, 200]
      });
    }
  };

  useEffect(() => {
    let interval: any;

    if (isRunning && endTime) {
      requestWakeLock(); // Asegurar que la pantalla no se apague

      interval = setInterval(() => {
        const now = Date.now();
        const remaining = Math.ceil((endTime - now) / 1000);

        if (remaining <= 0) {
          // Paso completado
          triggerAlarm();

          if (currentStepIdx < currentSequence.length - 1) {
            // Avanzar automáticamente al siguiente paso con un pequeño delay para que suene la alarma
            const nextIdx = currentStepIdx + 1;
            setCurrentStepIdx(nextIdx);
            // Iniciamos el siguiente paso automáticamente
            const nextTime = currentSequence[nextIdx].time;
            setEndTime(Date.now() + nextTime * 1000);
            setTimeLeft(nextTime);
          } else {
            // Fin del ciclo completo
            setIsRunning(false);
            setEndTime(null);
            releaseWakeLock();

            const msg = mode === 'backwash' 
              ? "¡PROCESO FINALIZADO! Tren de filtrado listo."
              : "¡REGENERACIÓN COMPLETADA! Suavizador operativo.";

            // Alerta visual final
            setTimeout(() => alert(msg), 500);

            if (mode === 'regen') {
              setHardness(5); 
              setShowRegenAlert(false);
            }
          }
        } else {
          setTimeLeft(remaining);
        }
      }, 1000);
    } else {
      releaseWakeLock();
    }

    return () => clearInterval(interval);
  }, [isRunning, endTime, currentStepIdx, currentSequence, mode]);

  const startSequence = () => {
    // Si estamos pausados y reanudamos, calculamos nuevo endTime basado en timeLeft actual
    // Si empezamos de cero, usamos el tiempo total del paso
    const duration = timeLeft > 0 ? timeLeft : currentSequence[0].time;

    setEndTime(Date.now() + duration * 1000);
    setTimeLeft(duration);
    setIsRunning(true);

    // Pre-cargar audio para iOS/Android
    if(audioRef.current) {
      audioRef.current.load();
      // Reproducir y pausar inmediatamente para "desbloquear" el audio en móviles
      audioRef.current.play().then(() => audioRef.current?.pause()).catch(() => {});
    }
  };

  const pauseSequence = () => {
    setIsRunning(false);
    setEndTime(null); // Detenemos el cálculo absoluto
    releaseWakeLock();
  };

  const handleHardnessChange = (val: number) => {
    setHardness(val);
    setShowRegenAlert(val > 50);
  };

  const changeMode = (newMode: 'backwash' | 'regen') => {
    if (isRunning) {
      if (!confirm("Hay un proceso en curso. ¿Deseas detenerlo para cambiar de modo?")) return;
      pauseSequence();
    }
    setMode(newMode);
    setCurrentStepIdx(0);
    setTimeLeft(0);
    setEndTime(null);
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  return (
    <div className="px-6 py-8 animate-fadeIn h-full bg-sky-50 overflow-y-auto pb-24 no-scrollbar">
      <ModuleHeader title="Planta de Producción" onBack={onBack} />

      <div className="space-y-6">

        {/* Mode Selector */}
        <div className="flex bg-white p-1.5 rounded-[2rem] shadow-sm">
          <button 
            onClick={() => changeMode('backwash')}
            className={`flex-1 py-4 rounded-[1.8rem] text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'backwash' ? 'bg-sky-500 text-white shadow-md' : 'text-sky-300'}`}
          >
            Retrolavado Diario
          </button>
          <button 
            onClick={() => changeMode('regen')}
            className={`flex-1 py-4 rounded-[1.8rem] text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'regen' ? 'bg-amber-500 text-white shadow-md' : 'text-sky-300'}`}
          >
            Regeneración Resina
          </button>
        </div>

        {/* Sequence Progress Bar */}
        <div className="flex justify-between gap-1 px-2">
          {currentSequence.map((s, idx) => (
            <div key={idx} className="flex-1 flex flex-col items-center gap-2">
              <div className={`h-2 w-full rounded-full transition-all duration-500 ${idx === currentStepIdx ? (mode === 'regen' ? 'bg-amber-500 shadow-lg shadow-amber-200' : 'bg-sky-500 shadow-lg shadow-sky-200') + ' scale-y-125' : idx < currentStepIdx ? 'bg-emerald-400' : 'bg-slate-200'}`}></div>
              <span className={`text-[6px] font-black uppercase tracking-tighter ${idx === currentStepIdx ? 'text-sky-900' : 'text-sky-300'}`}>{s.stage.slice(0, 4)}</span>
            </div>
          ))}
        </div>

        {/* Sequential Control Timer */}
        <RoundedCard className="text-center bg-white border-none shadow-2xl relative overflow-hidden">
          {isRunning && (
            <div className="absolute top-2 right-4 animate-pulse">
               <i className="fas fa-lock text-emerald-500 text-xs"></i> <span className="text-[8px] font-bold text-emerald-600 uppercase">Pantalla Activa</span>
            </div>
          )}
          <div className="absolute top-0 left-0 w-full h-1 bg-slate-100">
            <div 
              className={`h-full transition-all duration-1000 ${mode === 'regen' ? 'bg-amber-500' : 'bg-sky-500'}`} 
              style={{ width: `${((currentSequence[currentStepIdx].time - timeLeft) / currentSequence[currentStepIdx].time) * 100}%` }}
            ></div>
          </div>

          <div className="mb-6 pt-4">
            <div className={`w-fit mx-auto px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest mb-3 border ${mode === 'regen' ? 'bg-amber-50 text-amber-500 border-amber-100' : 'bg-sky-50 text-sky-500 border-sky-100'}`}>
              Paso {currentStepIdx + 1} de {currentSequence.length}
            </div>
            <h3 className="text-2xl font-black text-sky-900 tracking-tight leading-none mb-1">{currentSequence[currentStepIdx].stage}</h3>
            <p className={`font-black uppercase text-xs tracking-widest ${mode === 'regen' ? 'text-amber-500' : 'text-sky-500'}`}>{currentSequence[currentStepIdx].process}</p>
          </div>

          <div className="text-7xl font-mono font-black text-sky-900 mb-8 tabular-nums tracking-tighter flex justify-center items-baseline">
            {formatTime(timeLeft)}
            <span className="text-lg text-sky-300 ml-2 font-sans font-bold">min</span>
          </div>

          <div className="flex gap-3">
            {!isRunning ? (
              <button 
                onClick={startSequence} 
                className={`flex-1 text-white py-5 rounded-[2.5rem] font-black text-sm shadow-xl active:scale-95 transition-all ${mode === 'regen' ? 'bg-amber-500 shadow-amber-100' : 'bg-sky-600 shadow-sky-100'}`}
              >
                {timeLeft > 0 && timeLeft < currentSequence[currentStepIdx].time ? 'REANUDAR' : mode === 'regen' ? 'INICIAR REGENERACIÓN' : 'INICIAR RETROLAVADO'}
              </button>
            ) : (
              <button 
                onClick={pauseSequence} 
                className="flex-1 bg-red-500 text-white py-5 rounded-[2.5rem] font-black text-sm shadow-xl shadow-red-100 active:scale-95 transition-all flex items-center justify-center gap-2"
              >
                <i className="fas fa-pause"></i> PAUSAR PROCESO
              </button>
            )}
          </div>
        </RoundedCard>

        {/* Hardness & Regeneration Section */}
        <section className="space-y-4">
          <div className="flex items-center justify-between px-2">
             <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest">Estado de Resinas y Dureza</h4>
             <span className="text-[10px] font-bold text-sky-300">Medidor TDS/PPM</span>
          </div>

          <RoundedCard className="bg-white border-none shadow-lg">
            <div className="flex justify-between items-center mb-6">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-500">
                  <i className="fas fa-flask"></i>
                </div>
                <span className="text-sm font-black text-sky-900">Dureza del Agua</span>
              </div>
              <div className="flex items-center gap-2 bg-sky-50 p-1 rounded-2xl">
                 <button onClick={() => handleHardnessChange(Math.max(0, hardness - 1))} className="w-10 h-10 bg-white rounded-xl shadow-sm text-sky-600 font-black">-</button>
                 <span className="text-2xl font-black text-sky-900 w-12 text-center">{hardness}</span>
                 <button onClick={() => handleHardnessChange(hardness + 1)} className="w-10 h-10 bg-white rounded-xl shadow-sm text-sky-600 font-black">+</button>
              </div>
            </div>

            {showRegenAlert ? (
              <div className="bg-red-50 border-2 border-red-100 p-5 rounded-[2rem] animate-pulse">
                <div className="flex items-center gap-3 text-red-600 font-black text-xs uppercase mb-3">
                  <i className="fas fa-triangle-exclamation text-xl"></i> CRÍTICO: REGENERAR ZEOLITA
                </div>
                <p className="text-[10px] text-red-800 font-bold leading-relaxed mb-4">
                  Dureza detectada: <span className="underline">{hardness} PPM</span>. Se requiere REGENERACIÓN inmediata del filtro de Zeolita: Cargar sal al tanque de salmuera para lavado químico de resinas.
                </p>
                <button 
                  onClick={() => { changeMode('regen'); alert("Modo cambiado a Regeneración. Verifica el nivel de sal e inicia el proceso."); }}
                  className="w-full bg-red-600 text-white py-4 rounded-3xl text-[10px] font-black uppercase shadow-lg shadow-red-200"
                >
                  Ir a Modo Regeneración
                </button>
              </div>
            ) : (
              <div className="bg-emerald-50 p-5 rounded-[2rem] border border-emerald-100 flex items-center gap-4">
                <div className="w-12 h-12 bg-emerald-500 text-white rounded-2xl flex items-center justify-center text-xl shadow-lg shadow-emerald-100">
                  <i className="fas fa-shield-halved"></i>
                </div>
                <div>
                  <span className="text-xs font-black text-emerald-700 block uppercase tracking-tight">Estado Óptimo</span>
                  <p className="text-[10px] text-emerald-600 font-medium">Resinas trabajando bajo parámetros seguros.</p>
                </div>
              </div>
            )}
          </RoundedCard>
        </section>

        {/* Maintenance Tips */}
        <RoundedCard className="bg-indigo-900 text-white shadow-indigo-100 border-none">
           <div className="flex items-start gap-4">
              <div className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center shrink-0">
                <i className="fas fa-lightbulb text-indigo-300"></i>
              </div>
              <div>
                <h5 className="font-black text-sm mb-1 uppercase tracking-tighter">Tip de Mantenimiento</h5>
                <p className="text-[10px] opacity-70 leading-relaxed font-bold">
                  {mode === 'backwash' 
