              Paso {currentStepIdx + 1} de {currentSequence.length}
            </div>
            <h3 className="text-2xl font-black text-sky-900 tracking-tight leading-none mb-1">{currentSequence[currentStepIdx].stage}</h3>
            <p className={`font-black uppercase text-xs tracking-widest ${mode === 'regen' ? 'text-amber-500' : 'text-sky-500'}`}>{currentSequence[currentStepIdx].process}</p>
          </div>

          <div className="text-7xl font-mono font-black text-sky-900 mb-8 tabular-nums tracking-tighter flex justify-center items-baseline">
            {formatTime(timeLeft)}
            <span className="text-lg text-sky-300 ml-2 font-sans font-bold">min</span>
