              >
                {timeLeft > 0 && timeLeft < currentSequence[currentStepIdx].time ? 'REANUDAR' : mode === 'regen' ? 'INICIAR REGENERACIÓN' : 'INICIAR RETROLAVADO'}
              </button>
            ) : (
              <button 
                onClick={pauseSequence} 
