const PermissionShield: React.FC<{ onGranted: () => void }> = ({ onGranted }) => {
  const [status, setStatus] = useState<'idle' | 'requesting' | 'error'>('idle');

  const requestPermissions = async () => {
    setStatus('requesting');
    try {
      // 1. Solicitar Notificaciones (Vital para Producción)
      if ("Notification" in window) {
        const result = await Notification.requestPermission();
        if (result !== 'granted') console.warn("Notificaciones denegadas");
      }

      // 2. Solicitar Persistencia de Datos (Storage) - CRUCIAL PARA ERP
      if (navigator.storage && navigator.storage.persist) {
        const isPersisted = await navigator.storage.persist();
        console.log(`Persistencia de datos ${isPersisted ? 'activada' : 'no garantizada'}`);
      }

      // 3. Solicitar Cámara y Micrófono simultáneamente
      if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ 
            audio: true, 
            video: { facingMode: 'environment' } 
          });
          // Detener los tracks inmediatamente después de obtener el permiso para liberar hardware
          stream.getTracks().forEach(track => track.stop());
        } catch (mediaErr) {
          console.warn("Media permissions denied or failed:", mediaErr);
          // No lanzamos error fatal aquí para permitir que la app continúe sin cámara/mic si es necesario
        }
      }

      // 4. Solicitar Ubicación
      if (navigator.geolocation) {
        await new Promise((resolve) => {
          navigator.geolocation.getCurrentPosition(
            (pos) => resolve(pos), 
            (err) => {
              console.warn("Geolocation denied:", err);
              resolve(null);
            }, 
            { enableHighAccuracy: true, timeout: 3000 }
          );
        });
      }

      // Marca como concedido permanentemente en este dispositivo
      localStorage.setItem('aqua_permissions_granted', 'true');
      onGranted();
    } catch (e) {
      console.error("Global Permission error:", e);
      setStatus('error');
    }
  };

  return (
    <div className="fixed inset-0 bg-sky-900 flex flex-col items-center justify-center z-[200] px-10 text-center animate-fadeIn">
      <div className="w-24 h-24 bg-white/10 rounded-[2.5rem] flex items-center justify-center mb-8">
        <i className={`fas ${status === 'requesting' ? 'fa-circle-notch animate-spin' : 'fa-shield-halved'} text-sky-400 text-4xl`}></i>
      </div>
      <h2 className="text-white text-3xl font-black mb-4 tracking-tighter">Acceso Requerido</h2>
      <p className="text-sky-300 text-sm mb-12 font-medium leading-relaxed">
        Aqua+ Pro ERP necesita permisos de sistema para operar:<br/><br/>
        <span className="block mb-2"><i className="fas fa-bell w-6"></i> <b>Notificaciones:</b> Alertas de producción</span>
        <span className="block mb-2"><i className="fas fa-camera w-6"></i> <b>Cámara:</b> Escáner de seguridad</span>
        <span className="block mb-2"><i className="fas fa-microphone w-6"></i> <b>Micrófono:</b> Comandos de voz</span>
        <span className="block mb-2"><i className="fas fa-database w-6"></i> <b>Datos:</b> Almacenamiento persistente</span>
        <span className="block"><i className="fas fa-location-dot w-6"></i> <b>Ubicación:</b> Logística de ruta</span>
      </p>

      {status === 'error' ? (
        <div className="space-y-4 w-full">
           <p className="text-red-300 text-[10px] font-bold uppercase bg-red-900/50 p-3 rounded-xl">Error al solicitar acceso nativo.</p>
