import { useState, useEffect, useCallback } from 'react';
import { Product, Customer, Sale, CartItem, Order, Employee, Vehicle, PaymentSplit, ViewType, QualityRecord, Task, Attendance, TicketConfig } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS } from '../constants';

const DEFAULT_PERMISSIONS: ViewType[] = ['dashboard', 'pos', 'orders', 'customers', 'logistics', 'inventory', 'whatsapp', 'production', 'sync', 'reports', 'settings', 'employees', 'quality', 'scanner'];

const INITIAL_TICKET_CONFIG: TicketConfig = {
  businessName: 'AQUA+ FUNDADORES',
  rfc: 'AQUA900101-XXX',
  address: 'Calle del Agua #123, Col. Manantiales',
  phone: '33-1234-5678',
  footerMessage: '¡Gracias por tu preferencia! Frescura que hidrata tu vida.',
  website: 'www.aquafun.mx',
  socialMedia: '@aquafun_pro',
  extraNote: 'No hay cambios después de 24 horas.',
  logoUrl: 'data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><rect width=%22100%22 height=%22100%22 rx=%2225%22 fill=%22%230284c7%22/><path d=%22M50 20C50 20 30 45 30 60C30 71.0457 38.9543 80 50 80C61.0457 80 70 71.0457 70 60C70 45 50 20 50 20Z%22 fill=%22white%22/></svg>'
};

export const useERPData = () => {
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [ticketConfig, setTicketConfig] = useState<TicketConfig>(() => {
    const saved = localStorage.getItem('aqua_ticket_config');
    return saved ? JSON.parse(saved) : INITIAL_TICKET_CONFIG;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('aqua_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    const initial = saved ? JSON.parse(saved) : [
      { id: 'admin', name: 'Gerente General', role: 'Administrador', phone: '3312345678', pin: '1234', permissions: [...DEFAULT_PERMISSIONS] }
    ];
    return initial;
  });

  // Force update admin permissions to include all new modules
  useEffect(() => {
    setEmployees(prev => prev.map(e => 
      e.role === 'Administrador' 
        ? { ...e, permissions: [...DEFAULT_PERMISSIONS] } 
        : e
    ));
  }, []);

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    return saved ? JSON.parse(saved) : [{ id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0 }];
  });

  const [qualityRecords, setQualityRecords] = useState<QualityRecord[]>(() => {
    const saved = localStorage.getItem('aqua_quality');
    return saved ? JSON.parse(saved) : [];
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('aqua_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('aqua_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_orders', JSON.stringify(orders));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
    localStorage.setItem('aqua_ticket_config', JSON.stringify(ticketConfig));
    localStorage.setItem('aqua_quality', JSON.stringify(qualityRecords));
    localStorage.setItem('aqua_tasks', JSON.stringify(tasks));
    localStorage.setItem('aqua_attendance', JSON.stringify(attendance));
  }, [products, customers, sales, orders, employees, vehicles, ticketConfig, qualityRecords, tasks, attendance]);

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number, 
    manualTimestamp?: number
  ) => {
    const debtAmount = Math.max(0, total - paidAmount);
    const newSale: Sale = {
      id: `TKT-${Date.now().toString().slice(-6)}`,
      timestamp: manualTimestamp || Date.now(),
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change: Math.max(0, paidAmount - total),
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false
    };

    setSales(prev => [newSale, ...prev]);
    setCustomers(prev => prev.map(c => c.id === customerId ? { ...c, balance: (c.balance || 0) + debtAmount } : c));
    setProducts(prev => prev.map(p => {
      const cartItem = items.find(item => item.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    return newSale;
  };

  const syncData = useCallback((externalData: { sales: Sale[], customers: Customer[] }) => {
    setSales(prev => {
      const existingIds = new Set(prev.map(s => s.id));
      const newSales = externalData.sales.filter(s => !existingIds.has(s.id));
      return [...newSales, ...prev].sort((a, b) => b.timestamp - a.timestamp);
    });
    return true;
  }, []);

  const importCustomers = useCallback((newCustomers: Customer[]) => {
    setCustomers(prev => {
      const existingIds = new Set(prev.map(c => c.id));
      const filteredNew = newCustomers.filter(c => !existingIds.has(c.id));
      return [...prev, ...filteredNew];
    });
  }, []);

  return { 
    products, 
    saveProduct: (p: Product) => setProducts(prev => prev.find(x => x.id === p.id) ? prev.map(x => x.id === p.id ? p : x) : [...prev, p]),
    deleteProduct: (id: string) => setProducts(prev => prev.filter(p => p.id !== id)),
    customers, 
    saveCustomer: (c: Customer) => setCustomers(prev => prev.find(x => x.id === c.id) ? prev.map(x => x.id === c.id ? c : x) : [...prev, c]),
    deleteCustomer: (id: string) => setCustomers(prev => prev.filter(c => c.id !== id)),
    importCustomers,
    sales, addSale,
    orders, 
    setOrders,
    addOrder: (o: Partial<Order>) => {
      const newOrder: Order = {
        id: `ORD-${Date.now().toString().slice(-6)}`,
        timestamp: Date.now(),
        status: 'pendiente',
        priority: 1,
        items: [],
        total: 0,
        customerId: '',
        customerAlias: '',
        ...o
      } as Order;
      setOrders(prev => [newOrder, ...prev]);
    },
    updateOrder: (o: Order) => setOrders(prev => prev.map(item => item.id === o.id ? o : item)),
    employees, 
    saveEmployee: (e: Employee) => setEmployees(prev => prev.find(x => x.id === e.id) ? prev.map(x => x.id === e.id ? e : x) : [...prev, e]),
    vehicles, 
    setVehicles,
    loadVehicle: (id: string, delta: number) => setVehicles(prev => prev.map(v => v.id === id ? { ...v, currentLoad: Math.max(0, Math.min(v.loadCapacity, v.currentLoad + delta)) } : v)),
    tasks,
    addTask: (t: Partial<Task>) => {
      const newTask: Task = {
        id: `TSK-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        status: 'pendiente',
        ...t
      } as Task;
      setTasks(prev => [newTask, ...prev]);
    },
    updateTaskStatus: (id: string, status: Task['status']) => setTasks(prev => prev.map(t => t.id === id ? { ...t, status } : t)),
    attendance,
    recordAttendance: (employeeId: string, status: Attendance['status']) => {
      const date = new Date().toISOString().split('T')[0];
      setAttendance(prev => {
        const filtered = prev.filter(a => !(a.employeeId === employeeId && a.date === date));
        return [{ id: `ATT-${Date.now()}`, employeeId, status, date, timestamp: Date.now() }, ...filtered];
      });
    },
    qualityRecords,
    addQualityRecord: (r: Partial<QualityRecord>) => {
      const newRecord: QualityRecord = {
        id: `QUAL-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        employeeId: 'admin',
        ...r
      } as QualityRecord;
      setQualityRecords(prev => [newRecord, ...prev]);
    },
    ticketConfig, setTicketConfig,
    syncData
  };
};

import React, { useState, useRef } from 'react';
import { Customer, GarrafonType } from '../types';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

const GARRAFON_TYPES: { type: GarrafonType, color: string }[] = [
  { type: 'Aqua', color: 'bg-blue-500' },
  { type: 'Bonafont', color: 'bg-orange-500' },
  { type: 'Ciel', color: 'bg-sky-400' },
  { type: 'E-Pura', color: 'bg-red-500' },
  { type: 'Generico', color: 'bg-slate-400' }
];

export const CustomersModule: React.FC<{ onBack: () => void }> = ({ onBack }) => {
  const { customers, saveCustomer, deleteCustomer, sales, importCustomers } = useERPData();
  const [search, setSearch] = useState('');
  const [editingCustomer, setEditingCustomer] = useState<Partial<Customer> | null>(null);
  const [viewingHistory, setViewingHistory] = useState<Customer | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(search.toLowerCase()) || 
    c.alias.toLowerCase().includes(search.toLowerCase())
  );

  const handleSave = () => {
    if (!editingCustomer?.name || !editingCustomer?.alias) {
      alert("Nombre y Alias son obligatorios.");
      return;
    }
    const customerToSave: Customer = {
      id: editingCustomer.id || Math.random().toString(36).substr(2, 9),
      name: editingCustomer.name,
      alias: editingCustomer.alias,
      phone: editingCustomer.phone || '',
      specialPrice: editingCustomer.specialPrice || undefined,
      garrafonType: editingCustomer.garrafonType || 'Generico',
      balance: editingCustomer.balance || 0,
      lat: editingCustomer.lat,
      lng: editingCustomer.lng,
    };
    saveCustomer(customerToSave);
    setEditingCustomer(null);
  };

  const handleDelete = () => {
    if (!editingCustomer?.id) return;
    const confirmDelete = window.confirm(
      `¿Estás seguro de eliminar a "${editingCustomer.alias}"?\n\nEsta acción eliminará el registro del cliente permanentemente. Su historial de ventas se mantendrá como anónimo.`
    );
    if (confirmDelete) {
      deleteCustomer(editingCustomer.id);
      setEditingCustomer(null);
    }
  };

  const handleGetLocation = () => {
    if (!navigator.geolocation) {
      alert("Tu dispositivo no soporta geolocalización.");
      return;
    }

    const btn = document.getElementById('gps-btn');
    if(btn) {
       btn.innerHTML = '<i class="fas fa-circle-notch animate-spin"></i> Obteniendo...';
       btn.classList.add('opacity-50', 'pointer-events-none');
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        setEditingCustomer(prev => prev ? ({
          ...prev,
          lat: position.coords.latitude,
          lng: position.coords.longitude
        }) : null);

        if(btn) {
          btn.innerHTML = '<i class="fas fa-check"></i> Ubicación Capturada';
          btn.classList.remove('opacity-50', 'pointer-events-none', 'bg-emerald-50', 'text-emerald-600');
          btn.classList.add('bg-emerald-500', 'text-white');
          setTimeout(() => {
             btn.innerHTML = '<i class="fas fa-location-crosshairs"></i> Actualizar GPS';
             btn.classList.remove('bg-emerald-500', 'text-white');
             btn.classList.add('bg-emerald-50', 'text-emerald-600');
          }, 3000);
        }
      },
      (error) => {
        console.error(error);
        alert("Error al obtener ubicación. Asegúrate de dar permisos de ubicación a la app.");
        if(btn) {
          btn.innerHTML = '<i class="fas fa-triangle-exclamation"></i> Error';
          btn.classList.remove('opacity-50', 'pointer-events-none');
        }
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  };

  const openGoogleMaps = (lat?: number, lng?: number) => {
    if (lat && lng) {
      window.open(`https://www.google.com/maps/search/?api=1&query=${lat},${lng}`, '_blank');
    } else {
      alert("Este cliente no tiene ubicación registrada.");
    }
  };

  // --- LOGICA DE EXPORTACIÓN E IMPORTACIÓN ---

  const downloadFile = (content: string, filename: string, type: string) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleExportCSV = () => {
    const headers = ["ID", "Nombre", "Alias", "Telefono", "Saldo", "Precio Especial", "Tipo Garrafon", "Lat", "Lng"];
    const rows = customers.map(c => [
      c.id,
      `"${c.name}"`,
      `"${c.alias}"`,
      c.phone || '',
      c.balance,
      c.specialPrice || '',
      c.garrafonType || 'Generico',
      c.lat || '',
      c.lng || ''
    ]);
    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    downloadFile(csvContent, `Clientes_Aqua_${new Date().toISOString().split('T')[0]}.csv`, 'text/csv');
  };

  const handleExportVCard = () => {
    let vCardContent = '';
    customers.forEach(c => {
      vCardContent += 'BEGIN:VCARD\nVERSION:3.0\n';
      vCardContent += `FN:Aqua - ${c.alias}\n`;
      vCardContent += `N:Aqua;${c.alias};;;\n`;
      if (c.phone) vCardContent += `TEL;TYPE=CELL:${c.phone}\n`;
      vCardContent += `NOTE:Cliente Aqua+. Saldo: $${c.balance}. Tipo: ${c.garrafonType}\n`;
      vCardContent += 'END:VCARD\n';
    });
    downloadFile(vCardContent, `Contactos_Aqua_${new Date().toISOString().split('T')[0]}.vcf`, 'text/vcard');
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (!text) return;

      try {
        let importedCount = 0;
        const newCustomers: Customer[] = [];

        if (file.name.endsWith('.csv')) {
          // Importar CSV
          const lines = text.split('\n');
          lines.slice(1).forEach(line => {
            if (!line.trim()) return;
            const cols = line.split(',').map(c => c.replace(/^"|"$/g, '').trim()); // Basic CSV parsing
            if (cols.length >= 3) {
              newCustomers.push({
                id: cols[0] || Math.random().toString(36).substr(2, 9),
                name: cols[1],
                alias: cols[2],
                phone: cols[3],
                balance: parseFloat(cols[4]) || 0,
                specialPrice: parseFloat(cols[5]) || undefined,
                garrafonType: (cols[6] as any) || 'Generico',
                lat: parseFloat(cols[7]) || undefined,
                lng: parseFloat(cols[8]) || undefined
              });
              importedCount++;
            }
          });
        } else if (file.name.endsWith('.vcf') || file.name.endsWith('.vcard')) {
          // Importar vCard (Básico)
          const vcards = text.split('BEGIN:VCARD');
          vcards.forEach(vc => {
            const fnMatch = vc.match(/FN:(.*)/);
            const telMatch = vc.match(/TEL.*:(.*)/);
            if (fnMatch) {
              const name = fnMatch[1].trim();
              const phone = telMatch ? telMatch[1].trim().replace(/[^0-9+]/g, '') : undefined;
              newCustomers.push({
                id: Math.random().toString(36).substr(2, 9),
                name: name,
                alias: name.replace('Aqua - ', ''), // Remove prefix if re-importing
                phone: phone,
                balance: 0,
                garrafonType: 'Generico'
              });
              importedCount++;
            }
          });
        }

        if (importedCount > 0) {
          importCustomers(newCustomers);
          alert(`¡Éxito! Se importaron ${importedCount} clientes.`);
        } else {
          alert("No se encontraron datos válidos para importar.");
        }
      } catch (err) {
        alert("Error al procesar el archivo. Verifique el formato.");
        console.error(err);
      }
      // Limpiar input
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  // --- FIN LÓGICA IMPORT/EXPORT ---

  if (viewingHistory) {
    const customerSales = sales.filter(s => s.customerId === viewingHistory.id);
    const hasDebt = viewingHistory.balance > 0;
    const hasCredit = viewingHistory.balance < 0;

    return (
      <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24">
        <ModuleHeader title={`Perfil: ${viewingHistory.alias}`} onBack={() => setViewingHistory(null)} />
        <div className="px-6 space-y-4">
          <RoundedCard className={`${hasDebt ? 'bg-red-500' : hasCredit ? 'bg-emerald-500' : 'bg-sky-600'} text-white shadow-lg border-none transition-colors duration-500`}>
             <div className="flex justify-between items-center">
                <div>
                   <span className="text-[10px] font-black uppercase opacity-70">
                     {hasDebt ? 'Estado: Adeudo' : hasCredit ? 'Estado: Saldo a Favor' : 'Estado: Al Corriente'}
                   </span>
                   <p className="text-3xl font-black">
                     ${Math.abs(viewingHistory.balance).toLocaleString()}
                   </p>
                </div>
                <div className="bg-white/20 p-4 rounded-2xl">
                   <i className={`fas ${hasDebt ? 'fa-hand-holding-dollar' : 'fa-piggy-bank'} text-2xl`}></i>
                </div>
             </div>
          </RoundedCard>

          <div className="grid grid-cols-2 gap-3">
             <div className="bg-white p-4 rounded-3xl shadow-sm border border-sky-50">
                <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">WhatsApp</span>
                <p className="text-xs font-bold text-sky-900">{viewingHistory.phone || 'No registrado'}</p>
             </div>
             <div className="bg-white p-4 rounded-3xl shadow-sm border border-sky-50">
                <span className="text-[9px] font-black text-sky-400 uppercase block mb-1">Precio Esp.</span>
                <p className="text-xs font-bold text-sky-900">{viewingHistory.specialPrice ? `$${viewingHistory.specialPrice}` : 'Precio Base'}</p>
             </div>
          </div>

          {viewingHistory.lat && viewingHistory.lng && (
             <button 
               onClick={() => openGoogleMaps(viewingHistory.lat, viewingHistory.lng)}
               className="w-full py-4 bg-white border border-sky-100 rounded-[2rem] flex items-center justify-center gap-2 shadow-sm text-sky-600 font-black uppercase text-[10px] active:scale-95 transition-all"
             >
               <i className="fas fa-map-location-dot text-lg text-red-500"></i>
               Ver Ubicación en Mapa
             </button>
          )}

          <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest px-2 mt-4">Transacciones Recientes</h4>
          {customerSales.length === 0 ? (
            <div className="text-center py-20 text-sky-300 italic animate-fadeIn">Sin compras registradas aún.</div>
          ) : (
            customerSales.map(s => (
              <RoundedCard key={s.id} className="py-5 border-none shadow-sm animate-fadeIn">
                <div className="flex justify-between items-start mb-3">
                  <div>
                    <span className="text-sky-900 font-black">{s.id}</span>
                    <p className="text-[10px] text-sky-400 font-bold uppercase">{new Date(s.timestamp).toLocaleDateString()}</p>
                  </div>
                  <span className="font-black text-sky-600 text-xl">${s.total}</span>
                </div>
                <div className="flex flex-wrap gap-2">
                  {s.items.map(i => <span key={i.id} className="bg-sky-50 text-sky-600 text-[8px] px-3 py-1 rounded-full font-black uppercase">{i.quantity}x {i.name}</span>)}
                </div>
              </RoundedCard>
            ))
          )}
        </div>
      </div>
    );
  }

  if (editingCustomer) {
    return (
      <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-32">
        <ModuleHeader title={editingCustomer.id ? "Editar Perfil" : "Nuevo Cliente"} onBack={() => setEditingCustomer(null)} />
        <div className="px-6 space-y-5">
          <div className="space-y-4">
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Nombre Comercial / Alias</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-bold text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="Ej: Doña Mary" value={editingCustomer.alias || ''} onChange={e => setEditingCustomer({...editingCustomer, alias: e.target.value})}/>
            </div>
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Nombre Legal</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="Ej: María de los Angeles" value={editingCustomer.name || ''} onChange={e => setEditingCustomer({...editingCustomer, name: e.target.value})}/>
            </div>
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">WhatsApp</label>
               <input className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm text-sky-900 focus:ring-2 ring-sky-300 transition-all" placeholder="33..." value={editingCustomer.phone || ''} onChange={e => setEditingCustomer({...editingCustomer, phone: e.target.value})}/>
            </div>

            {/* Sección de Geolocalización */}
            <div>
               <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Ubicación de Entrega (Pin Google Maps)</label>
               <div className="flex gap-2">
                 <button 
                   id="gps-btn"
                   onClick={handleGetLocation} 
                   className="flex-1 bg-emerald-50 text-emerald-600 p-4 rounded-[2rem] font-bold text-[10px] uppercase flex items-center justify-center gap-2 border border-emerald-100 shadow-sm active:scale-95 transition-all"
                 >
                   <i className="fas fa-location-crosshairs"></i> Capturar GPS Actual
                 </button>
                 {editingCustomer?.lat && (
                   <button 
                     onClick={() => openGoogleMaps(editingCustomer.lat, editingCustomer.lng)} 
                     className="w-14 bg-sky-50 text-sky-500 rounded-[1.5rem] flex items-center justify-center text-lg active:scale-90 transition-transform shadow-sm"
                   >
                     <i className="fas fa-map-location-dot text-red-500"></i>
                   </button>
                 )}
               </div>
               {editingCustomer?.lat && (
                 <div className="mt-2 px-4 flex gap-4 text-[9px] font-mono font-bold text-sky-400 bg-white/50 py-2 rounded-xl border border-white">
                   <span>Lat: {editingCustomer.lat.toFixed(6)}</span>
                   <span>Lng: {editingCustomer.lng.toFixed(6)}</span>
                 </div>
               )}
            </div>

            <div className="space-y-3">
              <label className="text-[10px] font-black uppercase text-sky-400 ml-3 block">Tipo de Garrafón Preferido</label>
              <div className="grid grid-cols-2 gap-3">
                {GARRAFON_TYPES.map(g => (
                  <button 
                    key={g.type}
                    onClick={() => setEditingCustomer({...editingCustomer, garrafonType: g.type})}
                    className={`py-4 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${editingCustomer.garrafonType === g.type ? `${g.color} text-white shadow-lg scale-[1.02]` : 'bg-white text-sky-400 shadow-sm border border-sky-50'}`}
                  >
                    <div className={`w-2 h-2 rounded-full ${editingCustomer.garrafonType === g.type ? 'bg-white' : g.color}`}></div>
                    {g.type}
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                 <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Precio Especial</label>
                 <input type="number" className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-black text-sky-600 text-xl focus:ring-2 ring-sky-300" placeholder="0.00" value={editingCustomer.specialPrice || ''} onChange={e => setEditingCustomer({...editingCustomer, specialPrice: Number(e.target.value)})}/>
              </div>
              <div>
                 <label className="text-[10px] font-black text-sky-400 uppercase ml-3 mb-1 block">Saldo (Pos=Adeudo)</label>
                 <input type="number" className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm font-black text-sky-900 text-xl focus:ring-2 ring-sky-300" placeholder="0.00" value={editingCustomer.balance || ''} onChange={e => setEditingCustomer({...editingCustomer, balance: Number(e.target.value)})}/>
              </div>
            </div>
          </div>

          <div className="pt-4 space-y-3">
             <ActionButton onClick={handleSave}>Guardar Cliente</ActionButton>

             {editingCustomer.id && (
               <button 
                 onClick={handleDelete}
                 className="w-full py-4 text-rose-500 font-black uppercase text-[10px] tracking-widest bg-rose-50 rounded-[2rem] active:scale-95 transition-all border border-rose-100 shadow-sm hover:bg-rose-100"
               >
                 <i className="fas fa-trash-can mr-2"></i> Eliminar Cliente
               </button>
             )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full bg-sky-50 overflow-y-auto no-scrollbar pb-24">
      <ModuleHeader title="Directorio" onBack={onBack} />
      <div className="px-6 space-y-4">

        {/* PANEL DE HERRAMIENTAS DE DATOS */}
        <div className="bg-indigo-600 rounded-[2.5rem] p-6 text-white shadow-lg shadow-indigo-200">
          <div className="flex justify-between items-center mb-4">
            <h4 className="text-sm font-black uppercase tracking-tight">Herramientas de Datos</h4>
            <i className="fas fa-database opacity-50"></i>
          </div>
          <div className="grid grid-cols-3 gap-2">
            <button onClick={handleExportCSV} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl flex flex-col items-center gap-2 transition-colors">
               <i className="fas fa-file-csv text-xl"></i>
               <span className="text-[8px] font-bold uppercase text-center">CSV / Excel</span>
            </button>
            <button onClick={handleExportVCard} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl flex flex-col items-center gap-2 transition-colors">
               <i className="fas fa-address-book text-xl"></i>
               <span className="text-[8px] font-bold uppercase text-center">Contactos</span>
            </button>
            <label className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl flex flex-col items-center gap-2 transition-colors cursor-pointer relative">
               <i className="fas fa-cloud-arrow-up text-xl"></i>
               <span className="text-[8px] font-bold uppercase text-center">Importar</span>
               <input 
                 type="file" 
                 ref={fileInputRef}
                 accept=".csv, .vcf, .vcard" 
                 className="absolute inset-0 opacity-0 cursor-pointer"
                 onChange={handleImportFile}
               />
            </label>
          </div>
        </div>

        <div className="relative">
          <input type="text" placeholder="Buscar por alias o teléfono..." className="w-full bg-white p-5 rounded-[2rem] outline-none shadow-sm focus:ring-2 ring-sky-300 font-medium" value={search} onChange={e => setSearch(e.target.value)}/>
          <i className="fas fa-search absolute right-6 top-1/2 -translate-y-1/2 text-sky-200"></i>
        </div>

        <div className="space-y-3">
          {filteredCustomers.map(c => (
            <RoundedCard key={c.id} className="py-5 border-none shadow-sm group hover:shadow-md transition-all active:scale-[0.98]">
              <div className="flex justify-between items-center">
                <div className="flex gap-4 items-center flex-1" onClick={() => setViewingHistory(c)}>
                  <div className={`w-14 h-14 rounded-3xl flex items-center justify-center text-white font-black text-xl shadow-lg transition-transform group-active:scale-90 ${GARRAFON_TYPES.find(g => g.type === c.garrafonType)?.color || 'bg-slate-400'}`}>
                    {c.alias[0].toUpperCase()}
                  </div>
                  <div>
                    <h4 className="font-black text-sky-900 leading-tight">{c.alias}</h4>
                    <div className="flex gap-2 mt-1 flex-wrap">
                      <span className="bg-sky-100 text-sky-600 text-[8px] font-black px-2 py-0.5 rounded-full uppercase">{c.garrafonType || 'Aqua'}</span>
                      {c.lat && c.lng && (
                         <span className="bg-emerald-100 text-emerald-600 text-[8px] font-black px-2 py-0.5 rounded-full uppercase flex items-center gap-1">
                           <i className="fas fa-map-pin text-[8px]"></i> GPS
                         </span>
                      )}
                      {c.balance > 0 && (
                        <span className="bg-red-100 text-red-600 text-[8px] font-black px-2 py-0.5 rounded-full uppercase border border-red-200">
                          Adeudo
                        </span>
                      )}
                    </div>
                  </div>
                </div>
                <div className="flex gap-1">
                  <button onClick={() => setViewingHistory(c)} className="w-10 h-10 bg-sky-50 text-sky-500 rounded-xl flex items-center justify-center text-sm active:bg-sky-200 transition-colors"><i className="fas fa-eye"></i></button>
                  <button onClick={() => setEditingCustomer(c)} className="w-10 h-10 bg-sky-50 text-sky-500 rounded-xl flex items-center justify-center text-sm active:bg-sky-200 transition-colors"><i className="fas fa-pen"></i></button>
                  <a href={`https://wa.me/52${c.phone}`} className="w-10 h-10 bg-emerald-50 text-emerald-500 rounded-xl flex items-center justify-center text-sm active:bg-emerald-200 transition-colors"><i className="fab fa-whatsapp"></i></a>
                </div>
              </div>
            </RoundedCard>
          ))}
        </div>
        <button onClick={() => setEditingCustomer({})} className="w-full py-6 border-2 border-dashed border-sky-200 rounded-[2.5rem] text-sky-400 font-black text-sm uppercase hover:bg-white hover:text-sky-600 transition-all">+ Añadir Nuevo Cliente</button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import Peer, { DataConnection } from 'peerjs';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

interface SyncModuleProps {
  onBack: () => void;
  onScanRequest: () => void;
  scannedId?: string;
}

export const SyncModule: React.FC<SyncModuleProps> = ({ onBack, onScanRequest, scannedId }) => {
  const { sales, customers, syncData, addSale } = useERPData();
  const [peerId, setPeerId] = useState<string>('');
  const [targetId, setTargetId] = useState<string>('');
  const [status, setStatus] = useState<'idle' | 'connecting' | 'connected' | 'error' | 'disconnected' | 'reconnecting'>('idle');
  const [logs, setLogs] = useState<string[]>([]);
  const [latency, setLatency] = useState<number | null>(null);

  const peerRef = useRef<Peer | null>(null);
  const connRef = useRef<DataConnection | null>(null);
  const heartbeatInterval = useRef<any>(null);

  // Referencias para manejo de reconexión persistente
  const activeConnectionId = useRef<string | null>(null);
  const isManualDisconnect = useRef<boolean>(false);
  const retryTimeoutRef = useRef<any>(null);

  const addLog = (msg: string) => setLogs(prev => [`[${new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit', second:'2-digit'})}] ${msg}`, ...prev].slice(0, 15));

  const initPeer = () => {
    if (peerRef.current) peerRef.current.destroy();

    // Configuración robusta de servidores ICE (STUN) para atravesar NAT
    const peer = new Peer({
      debug: 1,
      config: {
        iceServers: [
          { urls: 'stun:stun.l.google.com:19302' },
          { urls: 'stun:global.stun.twilio.com:3478' }
        ]
      }
    });

    peerRef.current = peer;

    peer.on('open', (id) => {
      setPeerId(id);
      setStatus('idle');
      addLog('✅ Terminal activa en la nube P2P.');

      // Si perdimos conexión con el servidor broker, al volver intentamos reconectar el data channel si existía
      if (activeConnectionId.current && !connRef.current) {
        addLog('🔄 Restaurando sesión previa...');
        connectToPeer(activeConnectionId.current);
      }
    });

    peer.on('connection', (conn) => {
      addLog(`🔗 Solicitud entrante de: ${conn.peer.slice(0, 5)}...`);
      setupConnection(conn);
    });

    peer.on('error', (err) => {
      console.error("Peer Error:", err);
      if (err.type === 'peer-unavailable') {
        // No cambiamos a error fatal, intentamos reintentar si estamos en modo persistente
        if (activeConnectionId.current && !isManualDisconnect.current) {
             setStatus('reconnecting');
             addLog('⏳ Destino no disponible. Reintentando en 5s...');
             clearTimeout(retryTimeoutRef.current);
             retryTimeoutRef.current = setTimeout(() => {
                 if(activeConnectionId.current) connectToPeer(activeConnectionId.current);
             }, 5000);
        } else {
            setStatus('error');
            addLog('❌ Terminal destino no encontrada.');
        }
      } else if (err.type === 'network') {
        setStatus('disconnected');
        addLog('❌ Error de red. Verifique conexión a internet.');
      } else {
        addLog(`❌ Error P2P: ${err.type}`);
      }
    });

    peer.on('disconnected', () => {
      // Desconectado del servidor de señalización (PeerServer), no necesariamente del par
      if (!isManualDisconnect.current) {
          addLog('⚠️ Desconectado del servidor. Reintentando...');
          setTimeout(() => {
             if (peer && !peer.destroyed) peer.reconnect();
          }, 3000);
      }
    });
  };

  useEffect(() => {
    initPeer();
    return () => {
      cleanup();
    };
  }, []);

  const cleanup = () => {
    isManualDisconnect.current = true;
    activeConnectionId.current = null;
    if (retryTimeoutRef.current) clearTimeout(retryTimeoutRef.current);
    if (heartbeatInterval.current) clearInterval(heartbeatInterval.current);
    if (connRef.current) connRef.current.close();
    if (peerRef.current) peerRef.current.destroy();
  };

  useEffect(() => {
    if (scannedId && peerRef.current && !connRef.current) {
      const cleanId = scannedId.trim();
      setTargetId(cleanId);
      addLog("📸 QR Procesado. Iniciando enlace...");
      setTimeout(() => connectToPeer(cleanId), 1000);
    }
  }, [scannedId]);

  const setupConnection = (conn: DataConnection) => {
    // Si ya existe una conexión abierta, la cerramos para usar la nueva
    if (connRef.current && connRef.current.open) {
        connRef.current.close();
    }

    connRef.current = conn;
    // Guardamos el ID para reconexión futura
    activeConnectionId.current = conn.peer;
    isManualDisconnect.current = false;

    setStatus('connecting');

    conn.on('open', () => {
      setStatus('connected');
      addLog('🚀 ¡Enlace P2P Exitoso y Estable!');
      sendSyncData(conn);

      // Heartbeat agresivo para mantener NAT abierto
      if (heartbeatInterval.current) clearInterval(heartbeatInterval.current);
      heartbeatInterval.current = setInterval(() => {
        if (conn.open) {
            conn.send({ type: 'HEARTBEAT', t: Date.now() });
        } else {
            // Si detectamos que no está open aquí, forzamos cierre para disparar el handler 'close'
            conn.close();
        }
      }, 3000);
    });

    conn.on('data', (data: any) => {
      if (!data) return;
      if (data.type === 'PING') {
        conn.send({ type: 'PONG', t: data.t });
      } else if (data.type === 'PONG') {
        setLatency(Date.now() - data.t);
      } else if (data.type === 'SYNC_DATA') {
        addLog(`📦 Recibidos: ${data.sales.length} ventas.`);
        syncData({ sales: data.sales, customers: data.customers });
      }
    });

    conn.on('close', () => {
      setLatency(null);
      connRef.current = null;
      if (heartbeatInterval.current) clearInterval(heartbeatInterval.current);

      // LÓGICA DE AUTO-RECONEXIÓN
      if (!isManualDisconnect.current && activeConnectionId.current) {
          setStatus('reconnecting');
          addLog('⚠️ Enlace caído. Auto-reconectando en 2s...');

          clearTimeout(retryTimeoutRef.current);
          retryTimeoutRef.current = setTimeout(() => {
              if (activeConnectionId.current) {
                  addLog(`🔄 Re-conectando a: ${activeConnectionId.current.slice(0,5)}...`);
                  connectToPeer(activeConnectionId.current);
              }
          }, 2000);
      } else {
          setStatus('idle');
          addLog('🔌 Conexión finalizada correctamente.');
      }
    });

    conn.on('error', (err) => {
      addLog(`❌ Error en túnel: ${err}`);
      // El error usualmente dispara close, pero por si acaso
      conn.close();
    });
  };

  const connectToPeer = (id: string = targetId) => {
    const cleanId = id.trim();
    if (!cleanId || !peerRef.current) return;
    if (cleanId === peerId) return addLog("⚠️ No puedes auto-conectarte.");

    // Actualizamos referencia para persistencia
    activeConnectionId.current = cleanId;
    isManualDisconnect.current = false;

    addLog(`📡 Buscando: ${cleanId.slice(0, 6)}...`);

    // Cerramos conexión previa si existe para evitar conflictos
    if (connRef.current) {
        // No marcamos manual disconnect para permitir fluidez, pero cerramos el socket anterior
        try { connRef.current.close(); } catch(e){}
    }

    const conn = peerRef.current.connect(cleanId, { 
        reliable: true,
        serialization: 'json'
    });
    setupConnection(conn);
  };

  const sendSyncData = (conn: DataConnection) => {
    if (!conn.open) return;
    conn.send({
      type: 'SYNC_DATA',
      sales,
      customers
    });
    addLog('📤 Datos enviados al par.');
  };

  const sendPing = () => {
    if (connRef.current?.open) {
      addLog('Enviando PING...');
      connRef.current.send({ type: 'PING', t: Date.now() });
    }
  };

  const simulateSale = () => {
    if (customers.length === 0) return alert("Crea un cliente primero.");
    const sale = addSale(customers[0].id, [], 100, 100, [{method: 'Efectivo', amount: 100}], 0);
    addLog(`Venta simulada (${sale.id}).`);
    if (connRef.current?.open) sendSyncData(connRef.current);
  };

  const copyId = () => {
    navigator.clipboard.writeText(peerId);
    addLog("📋 ID copiado.");
  };

  const handleManualBack = () => {
      isManualDisconnect.current = true;
      activeConnectionId.current = null;
      if (connRef.current) connRef.current.close();
      onBack();
  };

  return (
    <div className="h-full animate-fadeIn bg-sky-50 pb-24 flex flex-col overflow-hidden">
      <ModuleHeader title="Terminal P2P" onBack={handleManualBack} />

      <div className="flex-1 overflow-y-auto px-6 space-y-6 no-scrollbar pb-10">

        {/* Identidad Local */}
        <RoundedCard className="bg-sky-900 text-white border-none shadow-xl relative overflow-hidden">
          <div className="relative z-10 flex flex-col items-center py-4">
            <span className="text-[9px] font-black uppercase opacity-60 tracking-[0.3em] mb-4">Tu Punto de Enlace</span>
            <div className="bg-white p-3 rounded-[2rem] mb-4 shadow-2xl">
              {peerId ? (
                <img src={`https://api.qrserver.com/v1/create-qr-code/?size=160x160&data=${peerId}`} alt="QR" className="w-32 h-32" />
              ) : (
                <div className="w-32 h-32 flex items-center justify-center">
                  <div className="flex flex-col items-center">
                    <i className="fas fa-satellite-dish animate-pulse text-sky-200 text-3xl mb-2"></i>
                    <span className="text-[8px] text-sky-400 font-bold uppercase">Conectando a Nube...</span>
                  </div>
                </div>
              )}
            </div>
            <button onClick={copyId} className="flex items-center gap-2 bg-white/10 px-5 py-2 rounded-full active:scale-95 transition-all">
              <span className="text-[10px] font-mono opacity-80">{peerId ? peerId.slice(0, 16) + '...' : 'Generando...'}</span>
              <i className="fas fa-copy text-sky-300"></i>
            </button>
          </div>
          <div className="absolute top-2 right-4">
            <div className={`w-3 h-3 rounded-full ${status === 'connected' ? 'bg-emerald-400 animate-pulse' : status === 'reconnecting' ? 'bg-amber-400 animate-ping' : 'bg-red-500'}`}></div>
          </div>
          <i className="fas fa-network-wired absolute -bottom-6 -right-6 text-9xl text-white/5 rotate-12"></i>
        </RoundedCard>

        {/* Panel de Conexión */}
        <section className="space-y-4">
          <div className="flex gap-2">
            <button onClick={onScanRequest} className="flex-1 bg-white border border-sky-100 py-5 rounded-[2rem] shadow-sm flex items-center justify-center gap-2 text-sky-600 font-black text-[10px] active:scale-95 transition-all">
              <i className="fas fa-camera"></i> ESCANEAR
            </button>
            <div className="flex-[1.5] relative">
               <input 
                type="text" 
                placeholder="ID Manual..." 
                className="w-full bg-white border-none rounded-[2rem] py-5 px-6 shadow-sm outline-none focus:ring-2 ring-sky-300 font-mono text-[10px]"
                value={targetId}
                onChange={(e) => setTargetId(e.target.value)}
              />
              <button onClick={() => connectToPeer()} disabled={!peerId} className="absolute right-2 top-2 bottom-2 w-12 bg-sky-600 text-white rounded-[1.5rem] flex items-center justify-center shadow-lg active:scale-90 transition-all disabled:opacity-50">
                <i className="fas fa-link"></i>
              </button>
            </div>
          </div>
        </section>

        {/* Diagnóstico */}
        <section className="space-y-3">
          <div className="flex justify-between items-center px-2">
            <h4 className="text-[10px] font-black uppercase text-sky-400 tracking-widest">Consola de Estado</h4>
            {latency !== null && (
              <span className="text-[10px] font-black text-emerald-500 uppercase">{latency}ms ping</span>
            )}
          </div>

          <div className="bg-white/80 backdrop-blur border border-white p-5 rounded-[2.5rem] shadow-sm">
             <div className="space-y-1 mb-5 max-h-40 overflow-y-auto no-scrollbar flex flex-col-reverse bg-sky-50/50 p-4 rounded-2xl min-h-[100px]">
                {logs.length === 0 ? (
                  <p className="text-[10px] text-sky-300 text-center italic mt-4">Esperando actividad de red...</p>
                ) : (
                  logs.map((log, i) => (
                    <div key={i} className={`text-[9px] font-mono font-bold flex gap-2 ${log.includes('❌') ? 'text-red-500' : log.includes('✅') ? 'text-emerald-600' : log.includes('🔄') ? 'text-amber-600' : 'text-sky-700'}`}>
                      {log}
                    </div>
                  ))
                )}
             </div>

             {status === 'connected' ? (
               <div className="grid grid-cols-2 gap-2">
                  <button onClick={sendPing} className="py-4 bg-sky-100 text-sky-600 rounded-2xl text-[9px] font-black uppercase tracking-widest active:bg-sky-200">
                    <i className="fas fa-bolt mr-2"></i> Ping Test
                  </button>
                  <button onClick={simulateSale} className="py-4 bg-emerald-100 text-emerald-600 rounded-2xl text-[9px] font-black uppercase tracking-widest active:bg-emerald-200">
                    <i className="fas fa-sync mr-2"></i> Sync Test
                  </button>
               </div>
             ) : (
               <div className="grid grid-cols-2 gap-2">
                  <div className={`flex items-center justify-center gap-2 py-3 rounded-2xl text-[9px] font-black uppercase ${status === 'connecting' || status === 'reconnecting' ? 'bg-amber-100 text-amber-600 animate-pulse' : 'bg-slate-100 text-slate-400'}`}>
                    {status === 'connecting' || status === 'reconnecting' ? <i className="fas fa-circle-notch animate-spin"></i> : <i className="fas fa-power-off"></i>}
                    {status === 'connecting' ? 'Enlazando...' : status === 'reconnecting' ? 'Re-conectando...' : 'Desconectado'}
                  </div>
                  <button onClick={initPeer} className="py-3 bg-sky-100 text-sky-600 rounded-2xl text-[9px] font-black uppercase tracking-widest active:bg-sky-200">
                    <i className="fas fa-rotate mr-2"></i> Reiniciar Red
                  </button>
               </div>
             )}
          </div>
        </section>
      </div>

      <div className="p-6 bg-white/80 backdrop-blur-xl border-t border-sky-100">
        <ActionButton onClick={handleManualBack} variant="secondary">Regresar</ActionButton>
      </div>
    </div>
  );
};

export type ViewType = 'dashboard' | 'pos' | 'orders' | 'logistics' | 'production' | 'sync' | 'whatsapp' | 'customers' | 'employees' | 'reports' | 'settings' | 'quality' | 'scanner' | 'inventory' | 'tickets';

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
  category?: 'Agua' | 'Insumos' | 'Accesorios';
}

export type GarrafonType = 'Aqua' | 'Bonafont' | 'Ciel' | 'E-Pura' | 'Generico';

export interface Customer {
  id: string;
  name: string;
  alias: string;
  phone?: string;
  specialPrice?: number;
  lat?: number;
  lng?: number;
  garrafonType?: GarrafonType;
  balance: number;
}

export interface TicketConfig {
  businessName: string;
  rfc: string;
  address: string;
  phone: string;
  footerMessage: string;
  logoUrl?: string;
  website?: string;
  socialMedia?: string;
  extraNote?: string;
  slogan?: string;
  email?: string;
}

export interface Order {
  id: string;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  status: 'pendiente' | 'asignado' | 'entregado' | 'cancelado';
  vehicleId?: string;
  timestamp: number;
  priority: number;
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Crédito' | 'Multimodal';

export interface PaymentSplit {
  method: 'Efectivo' | 'Transferencia';
  amount: number;
}

export interface Sale {
  id: string;
  timestamp: number;
  customerId: string;
  customerAlias: string;
  items: CartItem[];
  total: number;
  paidAmount: number;
  change: number;
  paymentSplits: PaymentSplit[];
  emptyGarrafonsReturned: number;
  synced: boolean;
}

export interface QualityRecord {
  id: string;
  timestamp: number;
  type: 'Cruda' | 'Producto';
  ph: number;
  cloro: number;
  tds: number;
  dureza: number;
  color: string;
  sabor: string;
  turbiedad: string;
  employeeId: string;
}

export interface Task {
  id: string;
  employeeId: string;
  title: string;
  description?: string;
  status: 'pendiente' | 'completada';
  timestamp: number;
  date: string;
}

export interface Attendance {
  id: string;
  employeeId: string;
  timestamp: number;
  date: string;
  status: 'presente' | 'falta' | 'retardo';
}

export interface Employee {
  id: string;
  name: string;
  role: 'Repartidor' | 'Planta' | 'Administrador';
  phone: string;
  pin: string;
  permissions: ViewType[];
}

export interface Vehicle {
  id: string;
  plate: string;
  description: string;
  loadCapacity: number;
  currentLoad: number;
}

import { useState, useEffect, useCallback } from 'react';
import { Product, Customer, Sale, CartItem, Order, Employee, Vehicle, PaymentSplit, ViewType, QualityRecord, Task, Attendance, TicketConfig } from '../types';
import { INITIAL_PRODUCTS, INITIAL_CUSTOMERS } from '../constants';

const DEFAULT_PERMISSIONS: ViewType[] = ['dashboard', 'pos', 'orders', 'customers', 'logistics', 'inventory', 'whatsapp', 'production', 'sync', 'reports', 'settings', 'employees', 'quality', 'scanner', 'tickets'];

const INITIAL_TICKET_CONFIG: TicketConfig = {
  businessName: 'AQUA+ FUNDADORES',
  rfc: 'AQUA900101-XXX',
  address: 'Calle del Agua #123, Col. Manantiales',
  phone: '33-1234-5678',
  footerMessage: '¡Gracias por tu preferencia! Frescura que hidrata tu vida.',
  website: 'www.aquafun.mx',
  socialMedia: '@aquafun_pro',
  extraNote: 'No hay cambios después de 24 horas.',
  logoUrl: 'data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><rect width=%22100%22 height=%22100%22 rx=%2225%22 fill=%22%230284c7%22/><path d=%22M50 20C50 20 30 45 30 60C30 71.0457 38.9543 80 50 80C61.0457 80 70 71.0457 70 60C70 45 50 20 50 20Z%22 fill=%22white%22/></svg>'
};

export const useERPData = () => {
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('aqua_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('aqua_customers');
    return saved ? JSON.parse(saved).map((c: any) => ({ ...c, balance: c.balance || 0 })) : INITIAL_CUSTOMERS;
  });

  const [ticketConfig, setTicketConfig] = useState<TicketConfig>(() => {
    const saved = localStorage.getItem('aqua_ticket_config');
    return saved ? JSON.parse(saved) : INITIAL_TICKET_CONFIG;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('aqua_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('aqua_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('aqua_employees');
    const initial = saved ? JSON.parse(saved) : [
      { id: 'admin', name: 'Gerente General', role: 'Administrador', phone: '3312345678', pin: '1234', permissions: [...DEFAULT_PERMISSIONS] }
    ];
    return initial;
  });

  // Force update admin permissions to include all new modules
  useEffect(() => {
    setEmployees(prev => prev.map(e => 
      e.role === 'Administrador' 
        ? { ...e, permissions: [...DEFAULT_PERMISSIONS] } 
        : e
    ));
  }, []);

  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('aqua_vehicles');
    return saved ? JSON.parse(saved) : [{ id: 'v1', plate: 'ABC-123', description: 'Nissan NP300', loadCapacity: 60, currentLoad: 0 }];
  });

  const [qualityRecords, setQualityRecords] = useState<QualityRecord[]>(() => {
    const saved = localStorage.getItem('aqua_quality');
    return saved ? JSON.parse(saved) : [];
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('aqua_tasks');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<Attendance[]>(() => {
    const saved = localStorage.getItem('aqua_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('aqua_products', JSON.stringify(products));
    localStorage.setItem('aqua_customers', JSON.stringify(customers));
    localStorage.setItem('aqua_sales', JSON.stringify(sales));
    localStorage.setItem('aqua_orders', JSON.stringify(orders));
    localStorage.setItem('aqua_employees', JSON.stringify(employees));
    localStorage.setItem('aqua_vehicles', JSON.stringify(vehicles));
    localStorage.setItem('aqua_ticket_config', JSON.stringify(ticketConfig));
    localStorage.setItem('aqua_quality', JSON.stringify(qualityRecords));
    localStorage.setItem('aqua_tasks', JSON.stringify(tasks));
    localStorage.setItem('aqua_attendance', JSON.stringify(attendance));
  }, [products, customers, sales, orders, employees, vehicles, ticketConfig, qualityRecords, tasks, attendance]);

  const addSale = (
    customerId: string, 
    items: CartItem[], 
    total: number, 
    paidAmount: number, 
    splits: PaymentSplit[], 
    returnedVacios: number, 
    manualTimestamp?: number
  ) => {
    const debtAmount = Math.max(0, total - paidAmount);
    const newSale: Sale = {
      id: `TKT-${Date.now().toString().slice(-6)}`,
      timestamp: manualTimestamp || Date.now(),
      customerId,
      customerAlias: customers.find(c => c.id === customerId)?.alias || 'Anonimo',
      items,
      total,
      paidAmount,
      change: Math.max(0, paidAmount - total),
      paymentSplits: splits,
      emptyGarrafonsReturned: returnedVacios,
      synced: false
    };

    setSales(prev => [newSale, ...prev]);
    setCustomers(prev => prev.map(c => c.id === customerId ? { ...c, balance: (c.balance || 0) + debtAmount } : c));
    setProducts(prev => prev.map(p => {
      const cartItem = items.find(item => item.id === p.id);
      return cartItem ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    return newSale;
  };

  const syncData = useCallback((externalData: { sales: Sale[], customers: Customer[] }) => {
    setSales(prev => {
      const existingIds = new Set(prev.map(s => s.id));
      const newSales = externalData.sales.filter(s => !existingIds.has(s.id));
      return [...newSales, ...prev].sort((a, b) => b.timestamp - a.timestamp);
    });
    return true;
  }, []);

  const importCustomers = useCallback((newCustomers: Customer[]) => {
    setCustomers(prev => {
      const existingIds = new Set(prev.map(c => c.id));
      const filteredNew = newCustomers.filter(c => !existingIds.has(c.id));
      return [...prev, ...filteredNew];
    });
  }, []);

  return { 
    products, 
    saveProduct: (p: Product) => setProducts(prev => prev.find(x => x.id === p.id) ? prev.map(x => x.id === p.id ? p : x) : [...prev, p]),
    deleteProduct: (id: string) => setProducts(prev => prev.filter(p => p.id !== id)),
    customers, 
    saveCustomer: (c: Customer) => setCustomers(prev => prev.find(x => x.id === c.id) ? prev.map(x => x.id === c.id ? c : x) : [...prev, c]),
    deleteCustomer: (id: string) => setCustomers(prev => prev.filter(c => c.id !== id)),
    importCustomers,
    sales, addSale,
    orders, 
    setOrders,
    addOrder: (o: Partial<Order>) => {
      const newOrder: Order = {
        id: `ORD-${Date.now().toString().slice(-6)}`,
        timestamp: Date.now(),
        status: 'pendiente',
        priority: 1,
        items: [],
        total: 0,
        customerId: '',
        customerAlias: '',
        ...o
      } as Order;
      setOrders(prev => [newOrder, ...prev]);
    },
    updateOrder: (o: Order) => setOrders(prev => prev.map(item => item.id === o.id ? o : item)),
    employees, 
    saveEmployee: (e: Employee) => setEmployees(prev => prev.find(x => x.id === e.id) ? prev.map(x => x.id === e.id ? e : x) : [...prev, e]),
    vehicles, 
    setVehicles,
    loadVehicle: (id: string, delta: number) => setVehicles(prev => prev.map(v => v.id === id ? { ...v, currentLoad: Math.max(0, Math.min(v.loadCapacity, v.currentLoad + delta)) } : v)),
    tasks,
    addTask: (t: Partial<Task>) => {
      const newTask: Task = {
        id: `TSK-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        status: 'pendiente',
        ...t
      } as Task;
      setTasks(prev => [newTask, ...prev]);
    },
    updateTaskStatus: (id: string, status: Task['status']) => setTasks(prev => prev.map(t => t.id === id ? { ...t, status } : t)),
    attendance,
    recordAttendance: (employeeId: string, status: Attendance['status']) => {
      const date = new Date().toISOString().split('T')[0];
      setAttendance(prev => {
        const filtered = prev.filter(a => !(a.employeeId === employeeId && a.date === date));
        return [{ id: `ATT-${Date.now()}`, employeeId, status, date, timestamp: Date.now() }, ...filtered];
      });
    },
    qualityRecords,
    addQualityRecord: (r: Partial<QualityRecord>) => {
      const newRecord: QualityRecord = {
        id: `QUAL-${Date.now().toString().slice(-4)}`,
        timestamp: Date.now(),
        employeeId: 'admin',
        ...r
      } as QualityRecord;
      setQualityRecords(prev => [newRecord, ...prev]);
    },
    ticketConfig, setTicketConfig,
    syncData
  };
};

