import React, { useState, useEffect } from 'react';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

interface SyncModuleProps {
  onBack: () => void;
  onScanRequest: () => void;
  scannedId?: string;
}

export const SyncModule: React.FC<SyncModuleProps> = ({ onBack, onScanRequest, scannedId }) => {
  const { sales, customers, syncData } = useERPData();
  const [mode, setMode] = useState<'menu' | 'export' | 'import' | 'success'>('menu');
  const [qrData, setQrData] = useState<string>('');
  const [syncStats, setSyncStats] = useState({ sales: 0, customers: 0 });

  // Procesar datos escaneados si vienen desde el ScannerModule
  useEffect(() => {
    if (scannedId) {
      handleImportData(scannedId);
    }
  }, [scannedId]);

  const generateSyncQR = () => {
    // 1. Filtramos datos relevantes (ej. últimas 48 horas para no saturar el QR)
    const recentSales = sales.slice(0, 50); // Últimas 50 ventas para mantener el QR legible
    const recentCustomers = customers; // Todos los clientes (suelen ser texto ligero)

    const payload = {
      t: Date.now(),
      s: recentSales,
      c: recentCustomers
    };

    // 2. Comprimimos y codificamos
    try {
      const jsonString = JSON.stringify(payload);
      // Usamos un prefijo único para identificar este tipo de QR
      const encoded = `AQUA-SYNC|${btoa(encodeURIComponent(jsonString))}`;

      setQrData(encoded);
      setMode('export');
    } catch (e) {
      alert("Error generando paquete de datos: Demasiada información para un solo QR.");
    }
  };

  const handleImportData = (rawCode: string) => {
    try {
      if (!rawCode.startsWith('AQUA-SYNC|')) {
        // Si no es un QR de sync, lo ignoramos o mostramos error sutil
        if (mode === 'import') alert("Código QR no válido para sincronización.");
        return;
      }

      const base64Part = rawCode.split('|')[1];
      const jsonString = decodeURIComponent(atob(base64Part));
      const data = JSON.parse(jsonString);

      if (data.s && data.c) {
        syncData({ sales: data.s, customers: data.c });
        setSyncStats({ sales: data.s.length, customers: data.c.length });
        setMode('success');
      }
    } catch (e) {
      console.error(e);
      alert("Error al procesar los datos de sincronización. El QR podría estar dañado.");
    }
  };

  return (
    <div className="h-full animate-fadeIn bg-slate-50 flex flex-col overflow-hidden pb-24">
      <ModuleHeader title="AirGap Sync" onBack={onBack} />

      <div className="flex-1 overflow-y-auto px-6 space-y-6 no-scrollbar pb-10">

        {/* MENU PRINCIPAL */}
        {mode === 'menu' && (
          <div className="space-y-6">
            <RoundedCard className="bg-sky-900 text-white border-none shadow-xl">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-white/20 rounded-[2rem] flex items-center justify-center text-3xl">
                  <i className="fas fa-tower-cell"></i>
                </div>
                <div>
                  <h3 className="text-xl font-black">Sincronización Segura</h3>
                  <p className="text-[10px] font-bold uppercase opacity-60 tracking-widest">Tecnología Offline</p>
                </div>
              </div>
              <p className="mt-4 text-[10px] leading-relaxed opacity-80 font-medium">
                Sincroniza datos entre dispositivos sin necesidad de internet ni cables. 
                Usa la cámara para transferir ventas y clientes instantáneamente.
              </p>
            </RoundedCard>

            <div className="grid grid-cols-1 gap-4">
              <button 
                onClick={generateSyncQR}
                className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-sky-100 flex items-center justify-between active:scale-95 transition-all group"
              >
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-sky-100 text-sky-600 rounded-2xl flex items-center justify-center text-xl group-hover:bg-sky-600 group-hover:text-white transition-colors">
                    <i className="fas fa-qrcode"></i>
                  </div>
                  <div className="text-left">
                    <h4 className="font-black text-sky-900 text-sm uppercase">Enviar Datos</h4>
                    <p className="text-[9px] font-bold text-sky-400">Generar código maestro</p>
                  </div>
                </div>
                <i className="fas fa-chevron-right text-sky-200"></i>
              </button>

              <button 
                onClick={onScanRequest}
                className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-sky-100 flex items-center justify-between active:scale-95 transition-all group"
              >
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-emerald-100 text-emerald-600 rounded-2xl flex items-center justify-center text-xl group-hover:bg-emerald-600 group-hover:text-white transition-colors">
                    <i className="fas fa-camera"></i>
                  </div>
                  <div className="text-left">
                    <h4 className="font-black text-sky-900 text-sm uppercase">Recibir Datos</h4>
                    <p className="text-[9px] font-bold text-sky-400">Escanear código maestro</p>
                  </div>
                </div>
                <i className="fas fa-chevron-right text-sky-200"></i>
              </button>
            </div>

            <div className="text-center mt-8 opacity-40">
               <i className="fas fa-wifi text-sky-900 text-2xl line-through"></i>
               <p className="text-[9px] font-black uppercase text-sky-900 mt-2">No requiere internet</p>
            </div>
          </div>
        )}

        {/* MODO EXPORTAR (MOSTRAR QR) */}
        {mode === 'export' && (
          <div className="flex flex-col items-center animate-fadeIn">
            <div className="bg-white p-4 rounded-[3rem] shadow-2xl border-4 border-sky-100 mb-6">
              <img 
                src={`https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${qrData}`} 
                alt="Sync QR" 
                className="w-64 h-64 object-contain rounded-2xl opacity-90" 
              />
            </div>
            <h3 className="text-xl font-black text-sky-900 mb-2">Código Maestro Generado</h3>
            <p className="text-xs text-sky-500 font-bold text-center px-8 mb-8">
              Escanea este código desde el otro dispositivo para transferir la base de datos actualizada.
            </p>
            <ActionButton onClick={() => setMode('menu')} variant="secondary">Cerrar</ActionButton>
          </div>
        )}

        {/* MODO SUCCESS */}
        {mode === 'success' && (
          <div className="flex flex-col items-center animate-fadeIn pt-10">
            <div className="w-24 h-24 bg-emerald-100 text-emerald-500 rounded-full flex items-center justify-center mb-6 shadow-xl shadow-emerald-100">
              <i className="fas fa-check-double text-4xl"></i>
            </div>
            <h3 className="text-2xl font-black text-sky-900 mb-2">¡Sincronización Exitosa!</h3>
            <div className="bg-white p-6 rounded-[2rem] w-full max-w-xs shadow-sm border border-sky-50 mb-8 space-y-3">
               <div className="flex justify-between items-center border-b border-sky-50 pb-2">
                 <span className="text-xs font-bold text-sky-400 uppercase">Ventas Procesadas</span>
                 <span className="text-xl font-black text-sky-900">{syncStats.sales}</span>
               </div>
               <div className="flex justify-between items-center">
                 <span className="text-xs font-bold text-sky-400 uppercase">Clientes Actualizados</span>
                 <span className="text-xl font-black text-sky-900">{syncStats.customers}</span>
               </div>
            </div>
            <ActionButton onClick={() => setMode('menu')}>Volver al Menú</ActionButton>
          </div>
        )}

      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ModuleHeader, RoundedCard } from './ui/Cards';

interface ScannerModuleProps {
  onBack: () => void;
  onScanSuccess?: (data: string, type: 'TICKET' | 'SYNC') => void;
  mode?: 'TICKET' | 'P2P'; // 'P2P' ahora se usa para Sync
}

export const ScannerModule: React.FC<ScannerModuleProps> = ({ onBack, onScanSuccess, mode = 'TICKET' }) => {
  const [scanning, setScanning] = useState(true);
  const [result, setResult] = useState<any>(null);

  const decryptData = (encrypted: string) => {
    try {
      // Detección de Tickets
      const decoded = atob(encrypted);
      if (decoded.startsWith('AQUA-PRO-SECURE|')) {
        return { type: 'TICKET', data: JSON.parse(decoded.split('|')[1]) };
      }
      return null;
    } catch {
      // Detección de Sync
      if (encrypted.startsWith('AQUA-SYNC|')) {
        return { type: 'SYNC', data: encrypted };
      }
      return null;
    }
  };

  const handleManualEntry = (code: string) => {
    // Lógica para AirGap Sync
    if (code.startsWith('AQUA-SYNC|')) {
      if (onScanSuccess) onScanSuccess(code, 'SYNC');
      else alert("Modo de escaneo incorrecto para Sincronización.");
      return;
    }

    // Lógica para Tickets
    const decoded = decryptData(code);
    if (decoded?.type === 'TICKET') {
      if (onScanSuccess && mode === 'TICKET') {
        onScanSuccess(code, 'TICKET');
      } else {
        setResult(decoded.data);
        setScanning(false);
      }
    } else {
      alert("Código no reconocido.");
    }
  };

  return (
    <div className={`h-full flex flex-col animate-fadeIn overflow-hidden ${mode === 'P2P' ? 'bg-slate-800' : 'bg-sky-900'}`}>
      <div className="px-6 pt-8 pb-4 flex items-center gap-4">
        <button onClick={onBack} className="w-12 h-12 bg-white/10 text-white rounded-2xl flex items-center justify-center active:scale-90 transition-transform">
          <i className="fas fa-arrow-left"></i>
        </button>
        <h2 className="text-2xl font-black tracking-tight text-white">
          {mode === 'P2P' ? 'Escanear Datos' : 'Validar Ticket'}
        </h2>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center px-10">
        {scanning ? (
          <div className="w-full space-y-8 flex flex-col items-center">
            <div className={`w-64 h-64 border-4 rounded-[3rem] relative overflow-hidden flex items-center justify-center ${mode === 'P2P' ? 'border-emerald-400 bg-emerald-900/20' : 'border-sky-400 bg-black/20'}`}>
              <div className={`absolute top-0 left-0 right-0 h-1 shadow-[0_0_15px_rgba(56,189,248,0.8)] animate-scanner ${mode === 'P2P' ? 'bg-emerald-500' : 'bg-sky-400'}`}></div>
              <i className={`fas fa-qrcode text-6xl ${mode === 'P2P' ? 'text-emerald-500/50' : 'text-white/20'}`}></i>
            </div>

            <div className="text-center">
              <h3 className="font-black text-xl mb-2 text-white">
                {mode === 'P2P' ? 'Apunta al QR Maestro' : 'Escaneando Ticket'}
              </h3>
              <p className="text-xs font-medium px-4 text-white/50">
                {mode === 'P2P' 
                  ? 'Escanea el código generado en la pantalla "Enviar Datos" del otro dispositivo.' 
                  : 'Apunta la cámara al código QR impreso en el ticket.'}
              </p>
            </div>

            <div className="w-full">
              <input 
                type="text" 
                placeholder="Entrada manual de código..." 
                className="w-full border border-white/20 bg-white/10 text-white rounded-2xl p-4 text-xs outline-none focus:ring-2 ring-white/30 transition-all placeholder-white/30"
                onKeyDown={e => e.key === 'Enter' && handleManualEntry(e.currentTarget.value)}
              />
            </div>
          </div>
        ) : (
          <RoundedCard className="w-full bg-white animate-fadeIn p-8">
            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 bg-emerald-100 text-emerald-500 rounded-full flex items-center justify-center mb-6">
                <i className="fas fa-check-circle text-4xl"></i>
              </div>
              <h3 className="text-2xl font-black text-sky-900 mb-2">Ticket Válido</h3>
              <div className="w-full bg-sky-50 rounded-3xl p-6 mb-8 space-y-4">
                <div className="flex justify-between">
                  <span className="text-[10px] font-black text-sky-400 uppercase">Ticket ID</span>
                  <span className="text-xs font-black text-sky-900">{result?.id}</span>
                </div>
                <div className="flex justify-between border-t border-sky-100 pt-3">
                  <span className="text-[10px] font-black text-sky-400 uppercase">Monto</span>
                  <span className="text-xl font-black text-sky-900">${result?.total}</span>
                </div>
              </div>
              <button 
                onClick={() => setScanning(true)} 
                className="w-full bg-sky-600 text-white py-5 rounded-[2rem] font-black uppercase text-xs tracking-widest shadow-xl shadow-sky-100"
              >
                Escanear Otro
              </button>
            </div>
          </RoundedCard>
        )}
      </div>

      <style>{`
        @keyframes scanner {
          0% { transform: translateY(0); }
          100% { transform: translateY(256px); }
        }
        .animate-scanner { animation: scanner 2s linear infinite alternate; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Peer, DataConnection } from 'peerjs';
import { useERPData } from '../hooks/useERPData';
import { ModuleHeader, RoundedCard, ActionButton } from './ui/Cards';

interface SyncModuleProps {
  onBack: () => void;
  onScanRequest: () => void;
  scannedId?: string;
}

type ConnectionStatus = 'disconnected' | 'connecting' | 'connected' | 'error';
type Role = 'host' | 'client' | null;

export const SyncModule: React.FC<SyncModuleProps> = ({ onBack, onScanRequest, scannedId }) => {
  const { sales, customers, syncData } = useERPData();
  const [role, setRole] = useState<Role>(null);
  const [peerId, setPeerId] = useState<string>('');
  const [status, setStatus] = useState<ConnectionStatus>('disconnected');
  const [logs, setLogs] = useState<string[]>([]);
  const [connectedPeers, setConnectedPeers] = useState<number>(0);

  const peerRef = useRef<Peer | null>(null);
  const connRef = useRef<DataConnection | null>(null);
  const wakeLockRef = useRef<WakeLockSentinel | null>(null);

  // Mantener referencias actualizadas para los callbacks de PeerJS
  const salesRef = useRef(sales);
  const customersRef = useRef(customers);
  const syncDataRef = useRef(syncData);

  useEffect(() => {
    salesRef.current = sales;
    customersRef.current = customers;
  }, [sales, customers]);

  // Activar WakeLock al entrar al módulo para evitar desconexiones por suspensión
  useEffect(() => {
    const requestWakeLock = async () => {
      try {
        if ('wakeLock' in navigator) {
          wakeLockRef.current = await navigator.wakeLock.request('screen');
          addLog('Pantalla mantenida activa para sincronización.');
        }
      } catch (err) {
        console.warn('WakeLock error:', err);
      }
    };
    requestWakeLock();
    return () => {
      wakeLockRef.current?.release();
    };
  }, []);

  // Inicialización de PeerJS según el rol
  useEffect(() => {
    if (!role) return;

    const initPeer = () => {
      // Generamos un ID corto si es Host para facilitar el escaneo, o aleatorio si es cliente
      const newPeerId = role === 'host' 
        ? `aqua-planta-${Math.floor(Math.random() * 1000)}` 
        : `aqua-movil-${Math.floor(Math.random() * 10000)}`;

      const peer = new Peer(newPeerId);

      peer.on('open', (id) => {
        setPeerId(id);
        setStatus(role === 'host' ? 'connected' : 'disconnected'); // Host está "conectado" esperando
        addLog(`ID Local generado: ${id}`);
      });

      peer.on('connection', (conn) => {
        if (role === 'host') {
          handleConnection(conn);
        } else {
          // Si somos cliente, rechazamos conexiones entrantes inesperadas (seguridad básica)
          conn.close();
        }
      });

      peer.on('error', (err) => {
        console.error(err);
        setStatus('error');
        addLog(`Error P2P: ${err.type}`);
        // Auto-retry simple
        if (err.type === 'network' || err.type === 'peer-unavailable') {
          setTimeout(initPeer, 5000);
        }
      });

      peer.on('disconnected', () => {
        setStatus('disconnected');
        addLog('Desconectado del servidor de señalización.');
        peer.reconnect();
      });

      peerRef.current = peer;
    };

    initPeer();

    return () => {
      peerRef.current?.destroy();
      peerRef.current = null;
    };
  }, [role]);

  // Manejo de conexión entrante (Lado Host) o Saliente (Lado Cliente)
  const handleConnection = (conn: DataConnection) => {
    conn.on('open', () => {
      connRef.current = conn;
      setStatus('connected');
      setConnectedPeers(prev => prev + 1);
      addLog(`Conectado con: ${conn.peer}`);

      // Sincronización Inicial: Enviar estado actual
      sendData(conn);
    });

    conn.on('data', (data: any) => {
      addLog('Datos recibidos...');
      if (data && data.sales && data.customers) {
        const hasChanges = syncDataRef.current({ sales: data.sales, customers: data.customers });
        if (hasChanges) addLog('Base de datos actualizada.');
      }
    });

    conn.on('close', () => {
      setStatus(role === 'host' ? 'connected' : 'disconnected');
      setConnectedPeers(prev => Math.max(0, prev - 1));
      addLog('Conexión cerrada.');
      connRef.current = null;
    });

    conn.on('error', (err) => {
      addLog(`Error de conexión: ${err}`);
      connRef.current = null;
    });
  };

  // Conectar a un Host (Lado Cliente)
  const connectToHost = (hostId: string) => {
    if (!peerRef.current) return;
    setStatus('connecting');
    addLog(`Conectando a Planta: ${hostId}...`);
    const conn = peerRef.current.connect(hostId, { reliable: true });
    handleConnection(conn);
  };

  // Procesar escaneo de QR
  useEffect(() => {
    if (scannedId && role === 'client') {
      // Limpiamos el ID por si viene con prefijos antiguos o nuevos
      const cleanId = scannedId.replace('AQUA-SYNC|', '').replace('AQUA-P2P|', ''); 
      connectToHost(cleanId);
    }
  }, [scannedId, role]);

  // Enviar datos
  const sendData = (conn: DataConnection | null = connRef.current) => {
    if (conn && conn.open) {
      conn.send({
        sales: salesRef.current,
        customers: customersRef.current,
        timestamp: Date.now()
      });
      // addLog('Sincronización enviada.'); // Comentado para no saturar logs
    }
  };

  // Listener de cambios locales para enviar actualizaciones en Tiempo Real
  useEffect(() => {
    if (status === 'connected' && connRef.current) {
      // Debounce ligero para no saturar el canal
      const timer = setTimeout(() => {
        sendData();
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [sales, customers, status]);

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev.slice(0, 4)]);
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(peerId);
    alert("ID copiado al portapapeles");
  };

  // --- RENDER ---

  if (!role) {
    return (
      <div className="h-full bg-slate-50 flex flex-col animate-fadeIn pb-24">
        <ModuleHeader title="Sincronización P2P" onBack={onBack} />
        <div className="px-6 flex-1 flex flex-col justify-center space-y-6">
          <div className="text-center mb-8">
            <div className="w-24 h-24 bg-sky-100 text-sky-600 rounded-full flex items-center justify-center mx-auto mb-4 text-4xl shadow-xl shadow-sky-100">
              <i className="fas fa-network-wired"></i>
            </div>
            <h3 className="text-xl font-black text-sky-900">Modo de Conexión</h3>
            <p className="text-sm text-sky-400 font-medium mt-2">Selecciona el rol de este dispositivo para iniciar la red en tiempo real.</p>
          </div>

          <button 
            onClick={() => setRole('host')}
            className="bg-white p-8 rounded-[2.5rem] shadow-lg border-2 border-transparent hover:border-indigo-500 group transition-all"
          >
            <div className="flex items-center gap-4 mb-2">
              <div className="w-12 h-12 bg-indigo-100 text-indigo-600 rounded-2xl flex items-center justify-center text-xl group-hover:scale-110 transition-transform">
                <i className="fas fa-server"></i>
              </div>
              <div className="text-left">
                <h4 className="font-black text-sky-900 text-lg uppercase">Soy Planta (Host)</h4>
                <p className="text-xs text-sky-400 font-bold">Crear sala de sincronización</p>
              </div>
            </div>
          </button>

          <button 
            onClick={() => setRole('client')}
            className="bg-white p-8 rounded-[2.5rem] shadow-lg border-2 border-transparent hover:border-emerald-500 group transition-all"
          >
            <div className="flex items-center gap-4 mb-2">
