          {mode === 'P2P' ? 'Conectar Dispositivo' : 'Validar Ticket'}
        </h2>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center px-10">
        {scanning ? (
          <div className="w-full space-y-8 flex flex-col items-center">
            <div className={`w-64 h-64 border-4 rounded-[3rem] relative overflow-hidden flex items-center justify-center ${mode === 'P2P' ? 'border-indigo-400 bg-indigo-900/20' : 'border-sky-400 bg-black/20'}`}>
              <div className={`absolute top-0 left-0 right-0 h-1 shadow-[0_0_15px_rgba(56,189,248,0.8)] animate-scanner ${mode === 'P2P' ? 'bg-indigo-500' : 'bg-sky-400'}`}></div>
              <i className={`fas fa-qrcode text-6xl ${mode === 'P2P' ? 'text-indigo-500/50' : 'text-white/20'}`}></i>
